WordHunterWoW_QuestEN[44106] = { title = "Archdruid of Lore", description = "Elothir resides in the ancient grove Thas'talah, where he communes with nature and instructs his acolytes in the ways of healing and the preservation of lore.\n\nSeek him out and tell him that he is desperately needed here.", objectives = "Seek out Elothir in Thas'talah.", completion = "Welcome, <name>. News of your heroism spreads from the Dreamgrove." }
WordHunterWoW_QuestEN[44108] = { title = "Ragemaw", description = "", objectives = "" }
WordHunterWoW_QuestEN[44112] = { title = "Trading for Dreams", description = "From the look of you, I take it you're an alchemist, yes?\n\nI'd be willing to trade my services with you for a price that I deem is fair.\n\nI have been away from Suramar for some time now. I long for an Ysera's Dream Draught. To concoct it, you'll need some dreamleaf as well as the leaves of a Dreamer's Tear.\n\nOne grows not to far from here in the clearing of some ruins. Take my flask, make this drink for me, and I'll do as you ask.", objectives = "Use the Nightborne Flask to craft an Ysera's Dream Draught.", progress = "<Leyweaver Erenyi seems lost in thought.>", completion = "You've crafted this rather well. I'm slightly impressed.\n\nNow let me see that silk of yours..." }
WordHunterWoW_QuestEN[44113] = { title = "DANGER: Achronos", description = "", objectives = "" }
WordHunterWoW_QuestEN[44114] = { title = "DANGER: Magistrix Vilessa", description = "", objectives = "" }
WordHunterWoW_QuestEN[44115] = { title = "Welcome to Legion!", description = "Welcome to World of Warcraft: Legion! We hope you enjoy all of the new experiences that await you in the Broken Isles, and want to make sure you're well-armed to take on the Burning Legion.", objectives = "Welcome to World of Warcraft: Legion! We hope you enjoy all of the new experiences that await you in the Broken Isles, and want to make sure you're well-armed to take on the Burning Legion." }
WordHunterWoW_QuestEN[44116] = { title = "Mystery at Citrine Bay", description = "The Burning Legion invades Azeroth, and SI:7 is wasting valuable resources hunting down and assassinating one of their top agents?\n\nSomething isn't adding up...\n\nWe need to find out how deep this goes. Why was Amber Kearnen being hunted by her own organization?\n\nThe encrypted letter she was carrying may hold the clues... but we need more information.\n\nThe SI:7 assassins you tailed in Dalaran mentioned Citrine Bay... search Citrine Bay for clues and we'll see about getting this letter decrypted.", objectives = "Speak with Fleet Admiral Tethys at Citrine Bay in Stormheim.", completion = "Ye had best keep ye voice below whispers, matey... thar be a band 'o pirates ahead! Fer sure, these be not th' type ye want to mess around wit'..." }
WordHunterWoW_QuestEN[44117] = { title = "Time Flies When Yer Havin' Rum!", description = "Thar be few pirates ye want to cross swords wit' less than th' Red Blade! They be salty dogs, indeed!\n\nThat being said... they does have a way wit' rum! I'll level wit' ye, {name}... thar be few rums as jolly as that 'o th' Red Blade.\n\nSeein' as ye be headin' off in search 'o clues, ye might as well brin' back a few bottles while ye be at it!\n\nBrin' me back as many bottles as ye can find, and I'll reward ye handsomely! Pirates honor, {name}!", objectives = "Collect 10 bottles of Red Blade Rum.", progress = "Have ye got th' spiced rum, <name>?", completion = "<Fleet Admiral Tethys pops the cork from a bottle and takes a long gulp.>\n\nAye, 'tis be th' stuff, <name>. Ye've done well!" }
WordHunterWoW_QuestEN[44118] = { title = "DANGER: Auditor Esiel", description = "", objectives = "" }
WordHunterWoW_QuestEN[44119] = { title = "DANGER: Volshax, Breaker of Will", description = "", objectives = "" }
WordHunterWoW_QuestEN[44120] = { title = "Illidari Allies", description = "At first I was unsure whether it was wise to allow the Illidari inside the city. But they may have just saved all our lives.\n\nI gave the demon hunters leave to establish a temporary camp in the Mage Quarter. I'd like you to be my personal envoy to them. Thank the Illidari for their assistance and see how they can aid our cause.\n\nJust... keep your eyes open. They have harnessed a terrible power, and we must be ready should they be consumed by the darkness within.", objectives = "Meet with the Illidari representative in the Mage Quarter of Stormwind.", completion = "I see by the blood spatters that Jace revealed the demons to you. I trust the young king is safe.\n\nWe have more work ahead of us, <class>. Much more." }
