WordHunterWoW_QuestEN[44140] = { title = "From Within", description = "Our demon hunters, Kor'vas Bloodthorn and Cyana Nightglaive took a small force of the Illidari across to Faronaar. Their mission was to weaken the Legion from within.\n\nI haven't heard from them in a while.\n\nIt would be best if you could find and lead them to success. Agreed?", objectives = "Find Kor'vas Bloodthorn on Faronaar at Vanquish Point.", completion = "Oh, <name>, it's you. Good, we've got a little problem here.\n\nKayn didn't think that Cyana and I could handle this on our own? He might have been right this time." }
