WordHunterWoW_QuestEN[44195] = { title = "Workorders for Armaments", description = "I can get you the best deals on some slightly... used... equipment.", objectives = "Place a workorder for a shipment of Champion Armaments and Equipment.", progress = "Place a workorder for a shipment of Champion Armaments and Equipment.", completion = "The orders been sent, my people are on the case.  Check back soon and you can pickup the shipment right here." }
