WordHunterWoW_QuestEN[44202] = { title = "For the Cause", description = "", objectives = "<name>, I hope you don't mind me dropping by unexpectedly. I was in the area on business.\n\nMy people procured what look to be some rather nice armaments for the cause. I'm sure that you know best how to distribute them.\n\nDo not doubt that our continued cooperation, even if it is a bit cloak and dagger, is making a huge difference in the war against the Burning Legion." }
WordHunterWoW_QuestEN[44203] = { title = "For the Cause", description = "", objectives = "Shadowblade <name>, always a pleasure. I was in the area on Alliance business and decided to drop in. It looks like our operations are faring well.\n\nMy people procured what look to be some rather nice armaments for the cause. I'm sure that you know best how to distribute them.\n\nThough we must continue to cooperate through back channels and behind closed doors, know that for the duration of the war against the Burning Legion, you can count on my support and that of SI:7." }
WordHunterWoW_QuestEN[44204] = { title = "Seal their Fates", description = "Ever feel like luck just isn't on your side?  Well maybe I can help you with that.  \n\nThere are some interesting items I've come across in my travels which can be used to swing the dice in your favor, or at least give you another shot at it.  It takes some time, and supplies are hard to come by, but I can get you one of them... for a price?", objectives = "Place a work order for a Seal of Broken Fate.", completion = "The order has been sent. Once my people have procured the item, it will be here for you to collect.\n\nGood... luck." }
WordHunterWoW_QuestEN[44205] = { title = "Shape Your Fate", description = "The whims of the spirits can be guided, I have seen it.\n\nThere were whispers of an item, a way to change the path of destiny.  I heard dem, and I went looking.  For many years I listened to those whispers on the wind until one day they showed me the way.  This is what I offer you.  It will take some time, and some valuable resources, but I can perform the ritual to allow you to control this power.\n\nWell?  Are you ready?", objectives = "Place a work order for a Seal of Broken Fate.", progress = "Place a work order  for a Seal of Broken Fate.", completion = "The ritual has begun. This will take some time. Return later." }
WordHunterWoW_QuestEN[44206] = { title = "The Ascended", description = "These shaman have spent their lives dedicated to the path of Air, Water or Fire.  On your request, we will beseech the elements to Ascend them, becoming a powerful, if short lived, force to deploy in this war against the Legion.\n\nThe ritual of ascension is not to be requested lightly.", objectives = "Place a request to recruit Ascendants.", completion = "The ritual has begun, they will Rise.  Return here when the ritual is complete." }
WordHunterWoW_QuestEN[44207] = { title = "Portal Full of Shiny Things", description = "When I heard the Hall of the Guardian was open again, I said to myself \"Minuette, this is your chance!\" I rushed over here thinking I'd be hurled into the front lines.  Imagine it, me, little old me, assaulting Demons with missiles, blinking away from Fel Meteors.  That would be brilliant!\n\nInstead, they send me over here and say \"Hey, open up some portals so we can throw things through, would you?\" At least I get to charge something for it.", objectives = "Place a work order for Champion armaments and equipment.", completion = "All those years of study are really paying off...\n\nOnce they've sent the shipment through, it will be waiting here for you." }
WordHunterWoW_QuestEN[44208] = { title = "Fate and Time", description = "For years we wondered, we conjectured, that it was possible to control the twisting, slipping, streaming threads of fate and destiny.  These books tell of powerful mages who embraced the manipulation of time.  No no, not like Time Warp, they would laugh at us, think us silly amateurs.  No, they were true Chronomancers.\n\nThe only spell we've been able to determine is a conjuration.  It calls forth what they termed  a \"Seal of Fate\".  This allowed them to repeat their actions.  Let us try it out shall we?", objectives = "Place a work order for a Seal of Broken Fate.", completion = "The spell has begun. Return to me when it is complete. Fate is in the hands of time now." }
WordHunterWoW_QuestEN[44209] = { title = "The Might of Dalaran", description = "In times of great need, the mages of Dalaran can focus their power into one pure, destructive form.  This is such a time.\n\nOn request, these mages will channel that power into a focusing crystal, which we will impart to you.  Use it to unleash that power, completing a quest of great value.", objectives = "Channel the power of Dalaran into the focusing crystal, then unleash it to complete a World Quest.", progress = "Channel the power of Dalaran into the focusing crystal, then unleash it to complete a World Quest.", completion = "Well done, though that certainly takes all of our efforts.  It will be some time before we can do that again." }
WordHunterWoW_QuestEN[44210] = { title = "The Might of Dalaran pt2", description = "Yes, now once the crystal has been empowered, collect it here, and use it to unleash the power of our mages on a world quest.", objectives = "Collect the Focusing Crystal and use it to complete a world quest." }
WordHunterWoW_QuestEN[44211] = { title = "Unseen Armaments", description = "If we gonna win dis war, we need to get these Champions of ours better equipment.  \n\nIt won't be cheap, or easy, but I can get dem for you.", objectives = "Place a work order for Champion armaments and equipment.", completion = "The order has been issued. Once the shipment arrives it will be here for you to collect." }
WordHunterWoW_QuestEN[44212] = { title = "Unseen Fate", description = "Our path is a winding, twisting road full of peril.  Yet did you know it can be walked many times?  There is an item of great power available to us.  It allows us another opportunity, a second chance.\n\nDo you wish to acquire one?", objectives = "Place a work order for a Seal of Broken Fate.", completion = "Word has been sent. The Seal will arrive soon." }
WordHunterWoW_QuestEN[44213] = { title = "You Will Be Prepared!", description = "{name}, your strength and leadership inspires awe in all of us!\n\nThe Illidari are prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", objectives = "Accept a gift from the Illidari.", completion = "Our glaives are yours, <name>." }
WordHunterWoW_QuestEN[44214] = { title = "One More Thing...", description = "Well done, Slayer. You are truly now the leader of the Illidari. But there's one more thing.\n\nMeet me down at the forge.", objectives = "Head down to the chamber of the Cursed Forge of the Nathrezim on the lower level of the Fel Hammer.", completion = "Excellent. You're going to like this." }
WordHunterWoW_QuestEN[44215] = { title = "One More Thing...", description = "Firstly, allow me to congratulate you. I know of no one more deserving of the title of Shadowblade. But there's one more thing.\n\nMeet me over near the forge.", objectives = "Meet Lord Ravenholdt in the Uncrowned Vault.", completion = "I think you will appreciate this. I must admit to a certain level of envy." }
WordHunterWoW_QuestEN[44217] = { title = "Armor Fit For A Deathlord", description = "{name} is strong! {name} is great leader!\n\nEbon Blade want to give you full set of armor to help with the little demon killing. Get stronger, make demons more dead!", objectives = "Accept a gift from the Knights of the Ebon Blade.", completion = "We is with you, <name>!" }
WordHunterWoW_QuestEN[44218] = { title = "Champion Armaments", description = "This war against the Legion won't be won easily.  We will need armaments and equipment for our Champions.  \n\nGive the order sir, I'll get the word out and have a shipment brought in.", objectives = "Place a work order for Champion armaments and equipment.", completion = "Aye, sir, the men have their orders.  Once the shipment arrives it will be here for you to collect." }
WordHunterWoW_QuestEN[44219] = { title = "Fate's Blessing", description = "The Light's blessing is powerful. We use it to mend, to defeat our enemies... we even use it to resurrect our allies. Did you know it can also be used to alter your destiny?  \n\nThe Silver Hand is able to procure a valuable item to help you in our war against the Legion. This Seal can be used at the most opportune moments to grant another chance at destiny.  \n\nShall we procure one for you?", objectives = "Place a work order for a Seal of Broken Fate.", completion = "Word has been sent. The Seal will arrive soon." }
WordHunterWoW_QuestEN[44220] = { title = "Blessing of the Order", description = "In times of great need, the Order can rally its mightiest forces into one pure, destructive form.  This is such a time.\n\nOn request, we will channel our power into a Libram, which we will impart to you.  Use it to unleash that power, completing a quest of great value.", objectives = "Send out the call to bring together the Vanguard, then unleash it to complete a World Quest.", progress = "Send out the call to bring together the Vanguard, then unleash it to complete a World Quest.", completion = "Well done, though that certainly takes all of our efforts." }
WordHunterWoW_QuestEN[44221] = { title = "Champion Armaments", description = "A warrior lives and dies by his weapons and armor.  For a price, we can provide you with a shipment for armaments to equip your Champions with.\n\nDo we have a deal?", objectives = "Place a workorder for Champion armaments and equipment.", completion = "The order has been placed.  Once the shipment arrives it will be here for you to collect." }
WordHunterWoW_QuestEN[44222] = { title = "The Might of the Val'kyr", description = "In times of great need, the Val'kyr can rally its mightiest forces into one pure, destructive form.  This is such a time.\n\nOn request, these we will channel our power into a Horn, which we will impart to you.  Use it to unleash that power, completing a quest of great value.", objectives = "Rise the power of the Val'kyr, then unleash it to complete a World Quest.", progress = "Rise the power of the Val'kyr, then unleash it to complete a World Quest.", completion = "Well done, though that certainly takes all of our efforts." }
WordHunterWoW_QuestEN[44223] = { title = "Champion Armaments", description = "We will need armaments and equipment for our Champions.", objectives = "Place a workorder for Champion armaments and equipment.", completion = "The order has been placed.  Once the shipment arrives it will be here for you to collect." }
WordHunterWoW_QuestEN[44224] = { title = "Unleashing our Wrath", description = "In times of great need, we can rally our  mightiest forces into one pure, destructive form.  This is such a time.\n\nOn request, these we will channel our power into an item, which we will impart to you.  Use it to unleash that power, completing a quest of great value.", objectives = "Channel the power of the Hammer, then unleash it to complete a World Quest.", completion = "Well done, though that certainly takes all of our efforts." }
WordHunterWoW_QuestEN[44226] = { title = "Fate Favors Us", description = "We are able to procure a valuable item to help you in our war against the Legion. This Seal can be used at the most opportune moments to grant another chance at destiny.  \n\nShall we procure one for you?", objectives = "Place a work order for a Seal of Broken Fate.", completion = "Word has been sent. The Seal will arrive soon." }
WordHunterWoW_QuestEN[44227] = { title = "Unleashing our Wrath", description = "In times of great need, we can rally our mightiest forces into one pure, destructive form.  This is such a time.\n\nOn request, these we will begin the ritual to enslave a powerful Infernal in a Demonic Phylactery, which we will impart to you.  Use it to unleash that power, completing a quest of great value.", objectives = "Begin the ritual to enslave the infernal, then unleash it to complete a World Quest.", progress = "Begin the ritual to enslave the infernal, then unleash it to complete a World Quest.", completion = "Well done, though that certainly takes all of our efforts." }
WordHunterWoW_QuestEN[44228] = { title = "Champion Armaments", description = "See Lurr?  He big and strong, but not so smart, not like Murr.  Murr can make Lurr build good things for you, things for your Champions to wear and be smashier.  \n\nFirst, you give Murr something?", objectives = "Place a work order for Champion armaments and equipment.", completion = "Murr will make Lurr smash fast!  When he done smashing, we put it in box.  Box here for you later." }
WordHunterWoW_QuestEN[44229] = { title = "Champion Armaments", description = "We will need armaments and equipment for our Champions.", objectives = "Place a work order for Champion armaments and equipment.", completion = "The order has been placed.  Once the shipment arrives it will be here for you to collect." }
WordHunterWoW_QuestEN[44230] = { title = "The Fates Bless Us", description = "We are able to procure a valuable item to help you in our war against the Legion. This Seal can be used at the most opportune moments to grant another chance at destiny.  \n\nShall we procure one for you?", objectives = "Place a work order for a Seal of Broken Fate.", completion = "Word has been sent. The Seal will arrive soon." }
WordHunterWoW_QuestEN[44231] = { title = "Champion Armaments", description = "People today see a dead body and they just think its a smelly pile of goo, not me I tell ya. I see it as a little present holding wonderful secrets.  \n\nFor a price, Ill share those secrets with you too.", objectives = "Place a workorder for Champion armaments and equipment.", completion = "The order has been placed.  Once the shipment arrives it will be here for you to collect." }
WordHunterWoW_QuestEN[44232] = { title = "The Grove Provides", description = "{name}, your wisdom and leadership inspires awe in all of us!\n\nThe Dreamweavers are prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", objectives = "Accept a gift from the Dreamweavers.", completion = "We are with you, <name>." }
