WordHunterWoW_QuestEN[44239] = { title = "Echo of a Celestial", description = "Tianili is clearly excited and wants your attention.  Perhaps you should help him?", objectives = "Start recruiting an Echo of a Celestial", completion = "Tianili seems distracted.  Perhaps you should return later." }
WordHunterWoW_QuestEN[44240] = { title = "Orange is the New Purple", description = "{name}, your intelligence and leadership inspires awe in all of us!\n\nTirisgarde is prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", objectives = "Accept a gift from the magi of Tirisgarde.", completion = "Our hearts and minds are with you, <name>." }
WordHunterWoW_QuestEN[44241] = { title = "Champion: Thassarian", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[44242] = { title = "Champion: Nazgrim", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[44243] = { title = "Champion: Thoras Trollbane", description = "", objectives = "These Knights of the Ebon Blade are a powerful order, Deathlord.\n\nThat you command such respect amongst their ranks speaks to your strength and leadership.\n\nDuring my life, I always fought to preserve my kingdom and people. But for my failure as a father, their blood now stains my hands.\n\nSo, I will wash the failure from my hands with the blood of demons. The time has come for me to return to the fray. My sword is yours to command." }
WordHunterWoW_QuestEN[44244] = { title = "Champion: Koltira Deathweaver", description = "", objectives = "Words cannot fully express my gratitude for rescuing me, <name>. In truth, I always knew that the Ebon Blade would not forsake me.\n\nI do not wish to elaborate on my years in captivity. That time has passed and we are now presented with an imminent danger in the Burning Legion.\n\nMy blade is yours, Deathlord. My life and my allegiance are yours to command." }
WordHunterWoW_QuestEN[44245] = { title = "Champion: High Inquisitor Whitemane", description = "", objectives = "There is no greater hatred and scorn in this world than that which exists in my heart.\n\nThe Burning Legion will pay for all that they have taken from me.\n\nThe day of my judgment awaits, but theirs is at hand and I will be the executioner's blade. I will not rest until every demon lays dead, their corpses paving the very ground I walk!\n\nCommand me to the front, Deathlord and I will rain terror upon the armies of the Burning Legion!" }
WordHunterWoW_QuestEN[44246] = { title = "Champion: Rottgut", description = "", objectives = "<Rottgut motions in your direction, gurgling and belching the words from its gaping mouth.>\n\nRottgut!!\n\nROTT. GUTT. ROTT! RottgutRottgutRottgut!!!\n\nGUT? ROTTGUTT, GUT. ROTT... GUT!\n\nRottgut??" }
WordHunterWoW_QuestEN[44247] = { title = "Champion: Amal'thazad", description = "", objectives = "Deathlord, I have been your humble tutor in the dark arts for some years now. From your birth at the hands of the Lich King, to your ascension as leader of our order, I have taken pride in watching you grow in power and undeath.\n\nI believe the time has passed in which my services as a teacher are necessary. Perhaps I would be of more use to you on the battlefield?\n\nThe time has come for me to warm these frozen bones of mine in the blood my enemies. Please, allow me to be of service on the battlefield." }
WordHunterWoW_QuestEN[44248] = { title = "Champion: Darion Mograine", description = "", objectives = "The Four Horsemen of the Ebon Blade are gathered together, but our work has only just begun.\n\nThe Burning Legion has come to our world hungering for destruction, but we will feed them their own demise. Apocalypse awaits the demon invaders and we shall bring it to them!\n\nDeathlord, you have triumphed where no others could have succeeded. I shall lead the Four Horsemen like my father before me, and so long as I lead them our loyalty is yours!\n\nThe return of the Four Horsemen is at hand!" }
WordHunterWoW_QuestEN[44249] = { title = "Inner Sanctuary", description = "{name}, your wisdom and leadership inspires awe in all of us!\n\nThe Order of the Broken Temple is prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", objectives = "Accept a gift from the Order of the Broken Temple.", completion = "In this fight, our spirits are as one, <name>." }
WordHunterWoW_QuestEN[44250] = { title = "Champion of the Light", description = "{name}, your strength and leadership inspires awe in all of us!\n\nThe Silver Hand is prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", objectives = "Accept a gift from the Silver Hand.", completion = "We stand with you, <name>." }
WordHunterWoW_QuestEN[44251] = { title = "Power Word: Armor", description = "{name}, your wisdom and leadership inspires awe in all of us!\n\nThe Conclave is prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", objectives = "Accept a gift from the Conclave.", completion = "We are with you, <name>." }
WordHunterWoW_QuestEN[44252] = { title = "A Sheath For Every Blade", description = "{name}, your cunning and leadership inspires awe in all of us!\n\nThe Uncrowned are prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", objectives = "Accept a gift from the Uncrowned.", completion = "Our blades are yours, <name>." }
WordHunterWoW_QuestEN[44253] = { title = "A Vision of Triumph", description = "{name}, your strength and leadership inspires awe in all of us!\n\nThe Earthen Ring is prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", objectives = "Accept a gift from the Earthen Ring.", completion = "We stand with you, <name>." }
WordHunterWoW_QuestEN[44254] = { title = "Gazing Into Oblivion", description = "{name}, your wisdom and leadership inspires awe in all of us!\n\nThe Council of the Black Harvest is prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", objectives = "Accept a gift from the Council of the Black Harvest.", completion = "The Council admires your power, <name>." }
WordHunterWoW_QuestEN[44255] = { title = "Axe and You Shall Receive", description = "{name}, your strength and leadership inspires awe in all of us!\n\nThe Valarjar are prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", objectives = "Accept a gift from the Valarjar.", completion = "The might of the Valarjar stands with you, <name>." }
WordHunterWoW_QuestEN[44257] = { title = "A Falling Star", description = "<Khadgar ponders the information that you brought to him.>\n\nYou say that it cut a swath through the Felstorm and was emanating power enough that your scout could feel it coursing through their body?\n\nSomething that powerful could prove to be a potent weapon against the Burning Legion!\n\nI will inform the other order leaders of your discovery while you investigate the matter further! A gryphon awaits your command at Krasus' Landing! Light guide you.", objectives = "Find the Mysterious Lightbound Object.", progress = "Show me what you've found.", completion = "Most curious indeed! This is no object of the Legion's making. Let me have a closer look." }
WordHunterWoW_QuestEN[44258] = { title = "Assault on Violet Hold: Into the Violet Hold", description = "The Violet Hold contains some of the Lich King's most powerful servants, and is at risk of being overrun by Legion agents. We must go there and thwart the demons before any of the prisoners can be set free.", objectives = "Defeat the leader of the Assault on Violet Hold.", progress = "How are you finding the Violet Hold?", completion = "Were you able to overcome Violet Hold?" }
WordHunterWoW_QuestEN[44259] = { title = "Assault on Violet Hold: Into the Violet Hold", description = "The Violet Hold contains some of the Lich King's most powerful servants, and is at risk of being overrun by Legion agents. We must go there and thwart the demons before any of the prisoners can be set free.", objectives = "Defeat the leader of the Assault on Violet Hold.", progress = "How are you finding the Violet Hold?", completion = "Were you able to overcome Violet Hold?" }
WordHunterWoW_QuestEN[44260] = { title = "Vault of the Wardens: Into the Vault of the Wardens", description = "It's worse than we thought within the Vault of the Wardens. The prisoners have become the jailers, and have completely taken over the vault. However, our intelligence reports that Cordana Felsong herself may be there.\n\nEnter the Vault of the Wardens and cleanse the place of evil.", objectives = "Defeat Cordana Felsong in Vault of the Wardens.", progress = "How are you finding the Vault of the Wardens?", completion = "Were you able to overcome Vault of the Wardens?" }
WordHunterWoW_QuestEN[44261] = { title = "Vault of the Wardens: Into the Vault of the Wardens", description = "It's worse than we thought within the Vault of the Wardens. The prisoners have become the jailers, and have completely taken over the vault. However, our intelligence reports that Cordana Felsong herself may be there.\n\nEnter the Vault of the Wardens and cleanse the place of evil.", objectives = "Defeat Cordana Felsong in Vault of the Wardens.", progress = "How are you finding the Vault of the Wardens?", completion = "Were you able to overcome Vault of the Wardens?" }
WordHunterWoW_QuestEN[44262] = { title = "The Arcway: Into the Arcway", description = "The Arcway is even more vast than we thought, and holds many dangers. If we have any hope of taking the city, we must first see to the underground.\n\nEnter The Arcway and clear out any, and all enemies.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Defeat Advisor Vandros in The Arcway." }
WordHunterWoW_QuestEN[44263] = { title = "The Arcway: Into the Arcway", description = "The Arcway is even more vast than we thought, and holds many dangers. If we have any hope of taking the city, we must first see to the underground.\n\nEnter The Arcway and clear out any, and all enemies.", objectives = "Defeat Advisor Vandros in The Arcway.", progress = "How are you finding the The Arcway?", completion = "Were you able to overcome The Arcway?" }
WordHunterWoW_QuestEN[44264] = { title = "Neltharion's Lair: Into Neltharion's Lair", description = "Our scouts found that not only have the drogbar obtained a Titan relic, but also they've amassed an army large enough to threaten the overworld.\n\nDelve underground and stop the Underking before he can unleash the might of his drogbar army.", objectives = "Defeat Dargrul in Neltharion's Lair.", progress = "How are you finding the challenges within the Neltharion's Lair?", completion = "Were you able to overcome Neltharion's Lair?" }
WordHunterWoW_QuestEN[44265] = { title = "Neltharion's Lair: Into Neltharion's Lair", description = "Our scouts found that not only have the drogbar obtained a Titan relic, but also they've amassed an army large enough to threaten the overworld.\n\nDelve underground and stop the Underking before he can unleash the might of his drogbar army.", objectives = "Defeat Dargrul in Neltharion's Lair.", progress = "How are you finding the challenges within the Neltharion's Lair?", completion = "Were you able to overcome Neltharion's Lair?" }
WordHunterWoW_QuestEN[44266] = { title = "Maw of Souls: Into the Maw of Souls", description = "Our scouts report that the vrykul damned are forced to sail aboard the Naglfar, a ship built of death.\n\nTravel to the Maw of Souls and confront Helya, before she collects any more poor, unfortunate souls.", objectives = "Defeat Helya in Maw of Souls.", progress = "How are you finding the challenges within the Maw of Souls?", completion = "Were you able to overcome Maw of Souls?" }
WordHunterWoW_QuestEN[44267] = { title = "Maw of Souls: Into the Maw of Souls", description = "Our scouts report that the vrykul damned are forced to sail aboard the Naglfar, a ship built of death.\n\nTravel to the Maw of Souls and confront Helya, before she collects any more poor, unfortunate souls.", objectives = "Defeat Helya in Maw of Souls.", progress = "How are you finding the challenges within the Maw of Souls?", completion = "Were you able to overcome Maw of Souls" }
WordHunterWoW_QuestEN[44268] = { title = "Halls of Valor: Odyn's Challenge", description = "Odyn himself sends a message. He and his warriors await worthy contenders within the Halls of Valor.\n\nDefeat the champions of the Halls of Valor, and claim glory.", objectives = "Defeat Odyn in the Halls of Valor.", progress = "How are you finding the Halls of Valor?", completion = "Were you able to overcome Odyn's challenge?" }
WordHunterWoW_QuestEN[44269] = { title = "Halls of Valor: Odyn's Challenge", description = "Odyn himself sends a message. He and his warriors await worthy contenders within the Halls of Valor.\n\nDefeat the champions of the Halls of Valor, and claim glory.", objectives = "Defeat Odyn in the Halls of Valor.", progress = "How are you finding the Halls of Valor?", completion = "Were you able to overcome Odyn's challenge?" }
WordHunterWoW_QuestEN[44270] = { title = "Eye of Azshara: Into the Eye of Azshara", description = "Our investigation found that the naga, under the orders of Queen Azshara herself, are preparing to summon a powerful entity to unleash Azshara's power across the Broken Isles.\n\nTravel to the Eye of Azshara, and put a stop to the ritual.", objectives = "Defeat the Wrath of Azshara in Eye of Azshara.", progress = "How are you finding the Eye of Azshara?", completion = "Were you able to overcome Eye of Azshara" }
WordHunterWoW_QuestEN[44271] = { title = "Eye of Azshara: Into the Eye of Azshara", description = "Our investigation found that the naga, under the orders of Queen Azshara herself, are preparing to summon a powerful entity to unleash Azshara's power across the Broken Isles.\n\nTravel to the Eye of Azshara, and put a stop to the ritual.", objectives = "Defeat the Wrath of Azshara in Eye of Azshara.", progress = "How are you finding the Eye of Azshara?", completion = "Were you able to overcome Eye of Azshara" }
WordHunterWoW_QuestEN[44272] = { title = "Darkheart Thicket: Into Darkheart Thicket", description = "Beneath the boughs of Shaladrassil, Xavius extends his power to twist and torment the once-pure druid grove. \n\nNot only this, but Xavius has taken a prize from among the druids, and his revenge will be slow and painful. We should go to Darkheart Thicket and stop his wicked plans.", objectives = "Defeat the Shade of Xavius in Darkheart Thicket.", progress = "How are you finding the Darkheart Thicket?", completion = "Were you able to overcome Darkheart Thicket?" }
WordHunterWoW_QuestEN[44273] = { title = "Darkheart Thicket: Into Darkheart Thicket", description = "Beneath the boughs of Shaladrassil, Xavius extends his power to twist and torment the once-pure druid grove. \n\nNot only this, but Xavius has taken a prize from among the druids, and his revenge will be slow and painful. We should go to Darkheart Thicket and stop his wicked plans.", objectives = "Defeat the Shade of Xavius in Darkheart Thicket.", progress = "How are you finding the Darkheart Thicket?", completion = "Were you able to overcome Darkheart Thicket?" }
WordHunterWoW_QuestEN[44274] = { title = "Court of Stars: Into the Court of Stars", description = "The weather is perfect for a party, isn't it?\n\nTravel to the Court of Stars, where the Grand Magistrix herself may appear among her nobles to reassure them of the need for all the Legion patrols.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Defeat Advisor Melandrus in Court of Stars." }
