WordHunterWoW_QuestEN[44276] = { title = "Black Rook Hold: The Lord of Black Rook Hold", description = "While investigating the remains of Black Rook Hold, our Champions were ambushed!  The Lord of the Rook appears to have allied himself with the Legion.\n\nWe need your assistance to defeat his growing army, and bring him down.", objectives = "Defeat Lord Kur'talos Ravencrest in Black Rook Hold.", progress = "Have you been to Black Rook Hold?", completion = "Were you able to defeat Lord Ravencrest?" }
WordHunterWoW_QuestEN[44277] = { title = "Black Rook Hold: The Lord of Black Rook Hold", description = "While investigating the remains of Black Rook Hold, our Champions were ambushed!  The Lord of the Rook appears to have allied himself with the Legion.\n\nWe need your assistance to defeat his growing army, and bring him down.", objectives = "Defeat Lord Kur'talos Ravencrest in Black Rook Hold.", progress = "Have you been to Black Rook Hold?", completion = "Were you able to defeat Lord Ravencrest?" }
WordHunterWoW_QuestEN[44278] = { title = "Illidari Freedom", description = "<Arduen Soulblade is bleeding from several ghastly wounds. It appears he was left here to die.>\n\nWithin the prison are three of our... <cough>... comrades.\n\nWe were taken by surprise while scouting the area.\n\nI am not long for this world, {name}, but please... you can still save them.", objectives = "Free Sirius Ebonwing, Cassiel Nightthorn, and Asha Ravensong.", completion = "We mourn together brother over the loss of Arduen, Cassiel, and Sirius. But, I owe you my life... again.\n\nThere is one thing I learned during my time in the prisons: the demons within Black Rook Hold must die." }
WordHunterWoW_QuestEN[44279] = { title = "7.0 Highmountain - Treasure 0xx - Bloodhunt Highland - S (RKS)", description = "", objectives = "" }
WordHunterWoW_QuestEN[44280] = { title = "7.0 Highmountain - Treasure 0x2 - Bloodhunt Highland - S (RKS)", description = "", objectives = "" }
WordHunterWoW_QuestEN[44281] = { title = "To Be Prepared", description = "Our allies have made the journey to Orgrimmar to support our war efforts.\n\nStop and visit with them, {name}. Their assistance will secure our victory today.", objectives = "Visit Horde forces in Dranosh'ar Blockade.", progress = "Blood and thunder, friend.", completion = "You look quite prepared for battle. Do not let the bloodlust overtake you out there.\n\nThe Warchief wishes to present you with this ring before you head to war. May you return with the heads of many demons." }
WordHunterWoW_QuestEN[44282] = { title = "Eye of Azshara: The Frozen Soul", description = "Ah, Deathlord. It is good to see you. I happen to have a fascinating task for you, should you be in the mood for adventure.\n\nI recently came across an obscure reference to an ancient amulet that was created by Queen Azshara herself! It is called the Frozen Soul Pendant and it offers tremendous power to those who channel the power of frost.\n\nI have reason to believe that it may be found somewhere within the Eye of Azshara.\n\nRetrieve the pendant for me, and it will prove most useful in my studies.", objectives = "Retrieve the Frozen Soul Pendant from the Wrath of Azshara.", progress = "Have you retrieved the pendant?", completion = "So this is the legendary Frozen Soul Pendant! I sense a great power in this item...\n\nI will begin my study of it at once. You have my gratitude, Deathlord." }
WordHunterWoW_QuestEN[44283] = { title = "The Emerald Nightmare: Piercing the Veil", description = "The darkness of the Nightmare is like a heavy shroud, warping reality and altering the perception of all living things. As areas of the Dream are cleansed, Xavius's hold weakens, and the way to the heart of the Nightmare will be revealed. But there might be a more direct way... my teacher once spoke of a pure power that could illuminate the darkness of the Nightmare, and allow all paths to become clear. But alas, Cenarius is lost....", objectives = "Collect 4 Essences of Clarity from Cenarius in The Emerald Nightmare on Normal difficulty.", progress = "If only Cenarius were with us, we could confront Xavius at once.", completion = "Incredible... where did you find these? With these Essences, I will be able to open the way directly to the heart of the Nightmare. Let us make haste!" }
WordHunterWoW_QuestEN[44284] = { title = "The Emerald Nightmare: Piercing the Veil", description = "The darkness of the Nightmare is like a heavy shroud, warping reality and altering the perception of all living things. As areas of the Dream are cleansed, Xavius's hold weakens, and the way to the heart of the Nightmare will be revealed. But there might be a more direct way... my teacher once spoke of a pure power that could illuminate the darkness of the Nightmare, and allow all paths to become clear. But alas, Cenarius is lost....", objectives = "Collect 4 Essences of Clarity from Cenarius in The Emerald Nightmare on Heroic difficulty.", progress = "If only Cenarius were with us, we could confront Xavius at once.", completion = "Incredible... where did you find these? With these Essences, I will be able to open the way directly to the heart of the Nightmare. Let us make haste!" }
WordHunterWoW_QuestEN[44285] = { title = "The Emerald Nightmare: Piercing the Veil", description = "The darkness of the Nightmare is like a heavy shroud, warping reality and altering the perception of all living things. As areas of the Dream are cleansed, Xavius's hold weakens, and the way to the heart of the Nightmare will be revealed. But there might be a more direct way... my teacher once spoke of a pure power that could illuminate the darkness of the Nightmare, and allow all paths to become clear. But alas, Cenarius is lost....", objectives = "Collect 4 Essences of Clarity from Cenarius in The Emerald Nightmare on Mythic difficulty.", progress = "If only Cenarius were with us, we could confront Xavius at once.", completion = "Incredible... where did you find these? With these Essences, I will be able to open the way directly to the heart of the Nightmare. Let us make haste!" }
WordHunterWoW_QuestEN[44286] = { title = "Vault of the Wardens: A Masterpiece of Flesh", description = "Ah, Deathlord! What a pleasant surprise! It is not often that you visit my workshop of blood and flesh.\n\nActually, I have something quite special to show you. I have been developing a new type of abomination that mixes the flesh of demons with that of humans.\n\nMy first prototype, Rottgut, is nearly complete! However I am still missing some of the more difficult-to-find body items.\n\nThe prisoners in the Vault of the Wardens should make fine donors for the parts I require.", objectives = "Retrieve the Beating Fel-Heart and Demonic Entrails from Vault of the Wardens.", progress = "Have you retrieved the parts?", completion = "Yes, these parts shall do nicely!\n\nNow go on and introduce yourself to Rottgut! I'm sure the two of you will get along... infamously!" }
