WordHunterWoW_QuestEN[44337] = { title = "Goddess Watch Over You", description = "I may have found a \"key\" to unlock Light's Heart, {name}.\n\nI was going through some ancient cosmology tomes when I stumbled upon a passage indicating that the prime naaru may have been created by Elune during the great ordering of Light and Shadow.\n\nIf Elune did create Xe'ra, then it stands to reason that we could use the Tears of Elune to unlock the secrets of Light's Heart.\n\nIt's a long shot, but we've got nothing left to lose.\n\nMeet me in Dalaran. I will ready the Tears of Elune for you.", objectives = "Meet Archmage Khadgar in Dalaran.", completion = "If this works, then perhaps there is still hope for Turalyon and the Army of the Light." }
WordHunterWoW_QuestEN[44338] = { title = "Goddess Watch Over You", description = "I may have found a \"key\" to unlock Light's Heart, {name}.\n\nI was going through some ancient cosmology tomes when I stumbled upon a passage indicating that the prime naaru may have been created by Elune during the great ordering of Light and Shadow.\n\nIf Elune did create Xe'ra, then it stands to reason that we could use the Tears of Elune to unlock the secrets of Light's Heart.\n\nNow it falls upon you to recover the Tears of Elune from Val'sharah.", objectives = "Recover the Tears of Elune from Val'sharah.", completion = "If this works, then perhaps there is still hope for Turalyon and the Army of the Light." }
