WordHunterWoW_QuestEN[44400] = { title = "Assault on Violet Hold: Purple Pain", description = "Again! It happened again!\n\nSure, it's the Legion that staged the prison breakout this time, but I *told* them it was a bad idea to keep some of the most dangerous beings on Azeroth in a prison inside our city!\n\nWe can talk about relocating later, I suppose. Right now, we've got some... pacification to tend to.\n\nCan you help?", objectives = "Repel the Assault on Violet Hold.", progress = "Oh, no. Don't tell me something ELSE has gone wrong?!", completion = "Whew. That's a SECOND invasion dealt with. Well done.\n\nNow, who do I talk to about getting this place shut down?" }
