WordHunterWoW_QuestEN[44406] = { title = "Aggra's Guidance", description = "{class}t, have you met the shaman Aggra? Born of a shattered world, she learned the ways of the elements among the Mag'har orcs of Outland. On the eve of the Cataclysm she took it upon herself to complete Thrall's shamanistic training. Our younger initiates are fortunate to have her among us to guide them.\n\nIf you wish to seek out a second artifact, Aggra can assist you. She is training new recruits above us on the Storm's Eye Overlook.", objectives = "Seek out Aggra at the Storm's Eye Overlook within the Heart of Azeroth.", completion = "I have been waiting for you, Farseer." }
WordHunterWoW_QuestEN[44407] = { title = "The Third Legend", description = "You have not one but TWO powerful artifacts to use against the Legion. But can you imagine a world where you have three? Think of what you could do in such a world!\n\nShall we look at the possibilities?", objectives = "Speak with Alonsus Faol to pursue a third artifact.", completion = "That was probably the easiest decision you've had to make! Let's get started." }
