WordHunterWoW_QuestEN[44411] = { title = "Strange Humming Crystal", description = "<You place the crystal to your ear and hear the disharmonious din of hundreds of voices speaking at once. Perhaps Khadgar might know more about this strange gem.>", objectives = "Take the Strange Humming Crystal to Khadgar in Dalaran.", completion = "Such a cacophony! I could hear it before you pulled it from your pack.\n\nWhat you've got there is a highborne memory crystal, somehow still intact. Created by ancient sorcery, they were used to store memories, stories, music, history, and whatnot.\n\nQuite rare! With a little... tinkering... I should be able to create something useful with it." }
WordHunterWoW_QuestEN[44412] = { title = "Enemies Everywhere", description = "Hold a moment, {name}. While I look into this orb of yours, why don't you look into something for me?\n\nI have long suspected an infiltration of Dalaran but after an embarrassing encounter with a local florist I've withheld my accusations until I'm absolutely certain.\n\nHave you noticed citizens among us that seem just too mundane? Almost inhumanly so? Spies, serving dark masters, watch and wait until our backs are turned. Root them out, but try and keep it quiet.", objectives = "Defeat the hidden infiltrators in Dalaran.", progress = "Have you disposed of our friends?", completion = "I appreciate your discretion, <name>.\n\nNow, look here! I have imparted all of my substantial worldly wisdom into this globe, in addition to my ruggedly handsome features. No doubt you will find my counsel invaluable in your travels.\n\nI could only get it to say a handful of phrases, however, so be VERY SPECIFIC in your questions." }
WordHunterWoW_QuestEN[44414] = { title = "Felspawns of Lothros", description = "These Felspawns are endless! I can't cut them down quickly enough to get to the dreadlord within the mausoleum.\n\nMaster Illidan, will you come with me so we can take down Lothros together?", objectives = "Defeat Lothros.", progress = "A dreadlord poses little danger to you, eh?", completion = "We've done it! Without you, I fear I would have eventually succumbed to the onslaught." }
WordHunterWoW_QuestEN[44415] = { title = "The Red Axe", description = "Broxigar the Red is cornered on the bridge. I am not sure he would ever admit that he needs our help, but I feel it only proper to lend him our aid.\n\nIf you wish to assist our ally, I would be humbled to accompany you in this endeavor.", objectives = "Close the Unstable Portals and make your way to Broxigar the Red.", progress = "Our allies are strong, but our enemy is Legion!", completion = "A wise warrior welcomes all allies. You fight with the strength of an orc." }
WordHunterWoW_QuestEN[44416] = { title = "Hunter of Night", description = "A glorious battle indeed!\n\nIf I am correct, we can expect something a bit more deadly at any moment.\n\nThe Legion often uses fodder such as these to prepare the way for a more worthy foe.\n\nMy axe is sharp and ready.", objectives = "Defeat Malvingeroth", progress = "Are you sure you are a night elf? You wage battle with the ferocity of an orc!", completion = "The spirits honor us with a day of glorious combat! You have my well-earned respect, Illidan Stormrage. I will gladly follow you into any battle." }
WordHunterWoW_QuestEN[44417] = { title = "One More Legend", description = "Two is good, but three would be better. You should pursue another artifact to add to your armory.\n\nWhat say you?", objectives = "Speak with Odyn to pursue another artifact.", completion = "That will definitely increase your power greatly." }
WordHunterWoW_QuestEN[44418] = { title = "Fury Chosen", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[44419] = { title = "Arms Chosen", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[44420] = { title = "Prot Chosen", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[44421] = { title = "Anomalous Anomalies", description = "Dalaran's move to this location was intended to be a temporary measure, but we may need to depart sooner than expected.\n\nBlinking a city across the world is no mean feat. The magnitude of energies involved can lead to... unexpected side effects.\n\nArcane anomalies are causing mischief throughout the city. Their presence could destabilize any attempt to blink again.\n\nWe don't have time to let them dissipate on their own, {name}. I have a device that will help speed things along.", objectives = "Use Khadgar's crystal to neutralize anomalies in Dalaran.", completion = "Good work. There are still some stray anomalies floating about, but you've negated enough interference that we should no longer be prevented from relocating the city.\n\nNow we just need to determine our destination." }
WordHunterWoW_QuestEN[44424] = { title = "Three Paths, Three Weapons", description = "We've searched and found a lead upon another artifact that you might find helpful.\n\nHere, let me show you what I've found. If it interests you then simply let me know.", objectives = "Choose a third artifact to pursue.", completion = "A wise choice." }
WordHunterWoW_QuestEN[44426] = { title = "Talking Pair Flavor Heard", description = "", objectives = "" }
