WordHunterWoW_QuestEN[44431] = { title = "More Weapons of Old", description = "You've had great success against our foes, but you should be ready for any challenge they send your way.\n\nYou would be wise to consider obtaining yet another of the weapons of old to aid in our conflict.\n\nLet me know how you'd like to proceed.", objectives = "Choose a third artifact to pursue.", completion = "A sound choice." }
