WordHunterWoW_QuestEN[44443] = { title = "Weapons of the Ancients", description = "You've proven yourself to be a druid without equal, but if we are to succeed in our battles against the Burning Legion you need you to take advantage of every opportunity to stay ahead of our foes.\n\nYou should consider obtaining one final weapon of the Ancients. Its powers will maximize your ability to adapt to whatever the Legion can throw our way.\n\nLet me know how you'd like to proceed.", objectives = "Choose a fourth artifact to pursue.", completion = "A sound choice." }
