WordHunterWoW_QuestEN[44448] = { title = "In the House of Light and Shadow", description = "The Tears of Elune are ready for you, {name}. I am uncertain what to do from here. Take the relic back to your order hall and try to use it on Light's Heart.\n\nMaybe make them touch? Honestly your guess is as good as mine.\n\nLet's hope this works!", objectives = "Take the Tears of Elune to Light's Heart in your Order Hall.", progress = "Any news?", completion = "Dead? The titans are dead?\n\n<Khadgar ponders the news for a minute.>\n\nIt explains so much, yet I cannot help but feel an overwhelming sense of sadness. We have been on our own all along. Our gods killed before we were born.\n\nAs for the Army of the Light and Illidan, I am at a loss. I have never felt so powerless.\n\nIllidan is dead and the Golden Army fights an endless war in our name from across the cosmos.\n\nI need a moment, <name>. This is too much bad news for an old man to bear." }
WordHunterWoW_QuestEN[44449] = { title = "Advanced Quenching", description = "Now that we have a frost mage at our disposal, testing this method out should be a cinch.\n\nHere are the plans for what I'd like you to make. Get to work and give me the armguards when you're finished.", objectives = "Craft a pair of Hard Leystone Armguards for Alard.", progress = "How's that technique coming along?", completion = "Look at that shine!" }
WordHunterWoW_QuestEN[44455] = { title = "Downfall Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[44457] = { title = "Brotherly Love", description = "Maiev will be somewhere in the prison. I found her discarded armor on my way here.\n\nI know the two of you have a history. I trust that will not be a problem.\n\nLet's split up to search the cells more quickly. We must find her.", objectives = "Find Maiev Shadowsong in Black Rook Prison.\n\nProvided item:", completion = "<Maiev's face is bruised, her lips cracked, and her body covered in scars. She looks thin and ragged, but she moves with purpose.>\n\nFor weeks they tried to break me. Amateurs!\n\nI kept my silence. I counted the minutes, measured their steps, and listened to the voices beyond my cell.\n\nI have been waiting for my chance to escape, and to strike back at my captors.\n\nNow, you bring my armor AND my blade. It's your turn to set me free, <class>. Let us destroy the Legion together." }
WordHunterWoW_QuestEN[44458] = { title = "Tracking Quest: Blood of Our Enemy 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[44459] = { title = "Tracking Quest: Blood of Our Enemy 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[44460] = { title = "Tracking Quest: Blood of Our Enemy 3", description = "", objectives = "" }
WordHunterWoW_QuestEN[44461] = { title = "Tracking Quest: Blood of Our Enemy 4", description = "", objectives = "" }
WordHunterWoW_QuestEN[44462] = { title = "Tracking Quest: Blood of Our Enemy 5", description = "", objectives = "" }
WordHunterWoW_QuestEN[44463] = { title = "Demons Among Them", description = "It is just as we suspected, {name}! The demons thought they could take us by surprise.\n\nQuickly, to arms! Warn the King!", objectives = "Protect the King.", progress = "Now is not a good time.", completion = "I must admit, you saved us from what might have been a terrible tragedy. You have my gratitude, <class>." }
WordHunterWoW_QuestEN[44464] = { title = "Awakenings", description = "Light's Heart is to serve as the vessel for Illidan Stormrage's rebirth: my last act of service to the Light.\n\nBut Illidan is dead and his soul is lost in the Nether. Before we may attempt to recover his soul, we must prepare the vessel for his return.\n\nAcross two worlds exist echoes of Illidan's past. You must venture out and find the echoes.\n\nStart where all life begins, {name}: birth. Find Illidan's birthplace in Val'sharah. Awaken the memory.", objectives = "Witness the Awakening of Illidan Stormrage in Val'sharah.", progress = "When our work is complete, I will be lost to the Great Dark.", completion = "An auspicious start to a life of tragedy. Perhaps one of the few joyous memories Illidan would have in his life. While the years that followed tested the prophesied child, they would never break him. You must remember that, despite what you may see as our journey continues.\n\nThere is much more to be done, but I am not yet ready. I will call for you when it is time." }
WordHunterWoW_QuestEN[44465] = { title = "Recruiting Earthcallers", description = "Felinda Frye has recently joined us at the Heart of Azeroth. She oversees the recruitment and training of our Earthcallers.\n\nI recommend that you speak with her at your soonest convenience, Farseer {name}. The Earthcallers are powerful shaman and will greatly bolster our ranks.", objectives = "Speak to Felinda Frye.", completion = "Greetings, Farseer <name>. I have been waiting for you.\n\nThe Earthcallers are ready and at your command!" }
WordHunterWoW_QuestEN[44466] = { title = "An Unclear Path", description = "Much of Illidan's formative years were spent in Val'sharah, alongside his twin brother, Malfurion.\n\nAs young night elves, the twins vied for the affection of the young priestess, Tyrande, as they underwent the trials of the demi-god, Cenarius.\n\nWe must travel to the Dreamgrove now, where Illidan's true path would be forged.", objectives = "Witness Illidan's Resilience at the Dreamgrove in Val'sharah.", progress = "You mustn't lose hope.", completion = "Failure. Rejection. From that day, Illidan would be haunted by both. Ever undaunted, he would continue the search for his destiny. Another path would be found." }
WordHunterWoW_QuestEN[44467] = { title = "Tracking Quest: When There's a Will, There's a Way 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[44468] = { title = "Tracking Quest: When There's a Will, There's a Way 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[44469] = { title = "Tracking Quest: When There's a Will, There's a Way 3", description = "", objectives = "" }
WordHunterWoW_QuestEN[44470] = { title = "Tracking Quest: When There's a Will, There's a Way 4", description = "", objectives = "" }
WordHunterWoW_QuestEN[44471] = { title = "Second Sight", description = "Though young King Anduin is a noble soul, he may lack the conviction of his father. The Alliance needs a leader who will do what needs to be done. The Legion will strike at the first hint of weakness.\n\nEven now, I sense something amiss, {name}. I fear that not all is as it seems.\n\nQuickly, use your Spectral Sight. We must know if there are foes among us!", objectives = "Use your Spectral Sight.", progress = "Time is precious.", completion = "Of course the Legion would try to infiltrate this funeral. Having all the leaders of the Alliance gathered in one place at one time... it is too tasty a target for the demons to resist!" }
WordHunterWoW_QuestEN[44472] = { title = "Tracking Quest: When There's a Will, There's a Way 5", description = "", objectives = "" }
WordHunterWoW_QuestEN[44473] = { title = "A Weapon of the Alliance", description = "At first I was unsure whether it was wise to allow the Illidari inside the city. But you may have just saved all our lives.\n\nYou may establish a camp in the Mage Quarter. The Alliance will have need of your skills if we are to face the Legion.\n\nMake no mistake though. Should your kind give in to the fel energies you toy with, we will treat you like the demons you are becoming.", objectives = "Meet with the Illidari in the Mage Quarter of Stormwind.", completion = "I trust the young king is safe.\n\nWe have more work ahead of us, <class>. Much more." }
WordHunterWoW_QuestEN[44474] = { title = "Tracking Quest: Following In His Footsteps 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[44475] = { title = "Tracking Quest: Following In His Footsteps 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[44476] = { title = "Tracking Quest: Following In His Footsteps 3", description = "", objectives = "" }
WordHunterWoW_QuestEN[44477] = { title = "Tracking Quest: Following In His Footsteps 4", description = "", objectives = "" }
WordHunterWoW_QuestEN[44478] = { title = "Tracking Quest: Following In His Footsteps 5", description = "", objectives = "" }
WordHunterWoW_QuestEN[44479] = { title = "Ravencrest's Legacy", description = "Years later, as the War of the Ancients raged on and the Burning Legion's grip upon this world took hold, Illidan would meet a military leader known as Kur'talos Ravencrest. He too would see the potential within Illidan, eventually promoting him to captain of the Moon Guard: a powerful group of night elf sorcerers.\n\nWe must experience this memory in Black Rook Hold, located on the western shores of Val'sharah.", objectives = "Experience Ravencrest's Legacy at Black Rook Hold in Val'sharah.", progress = "Without Light, the darkness cannot exist.", completion = "The line between good and evil is thin, and resides in a place where intention means little.\n\nIllidan wondered how those around him could be so blind to the threat of the Burning Legion. Fate is not without a sense of irony." }
WordHunterWoW_QuestEN[44480] = { title = "In My Father's House", description = "Most mortals cannot comprehend the truth of the Legion. Those that recognize it, often refuse to accept its meaning. Such knowledge carries a weight that the mortal frame cannot bear. To sacrifice that much of ones self changes the soul.\n\nAmong your greatest heroes, a rare few understood that type of sacrifice. Let us witness it through Illidan's eyes.\n\nWe must go to Azshara, on the continent of Kalimdor.", objectives = "Witness Illidan's Sacrifice in Azshara on the continent of Kalimdor.", progress = "The vessel is nearly ready to take on the soul.", completion = "Illidan sought out the truth and was blinded by what he saw. He was beginning to understand his destiny, but there was one final sacrifice that he had yet to make." }
WordHunterWoW_QuestEN[44481] = { title = "Destiny Unfulfilled", description = "Hardly recognizable from the golden eyed child of prophecy, and living as an outcast on the fringes of a shattered world, his motivation remained unchanged. His assaults on the Legion and his attempts to end their march were his only focus.\n\nYet, in a strange twist of fate, it was not the Burning Legion who came for him in the end.\n\nWe must travel to Outland to experience Illidan's last memory.", objectives = "Witness True Betrayal in Shadowmoon Valley on the fringes of Outland.", progress = "When the vessel is prepared, we will seek out his soul.", completion = "I wept when I touched your consciousness in the Great Dark, mortal. For I saw his fall, and I saw you, your shadow casting a dark pall over his body. I felt hatred in your heart as it corrupted your mind.\n\nIt was not Light's Heart, but you, that needed preparation. Now you know truth. Are you prepared to do what must be done to save your world and all others?\n\nWhen the time is right, I will call upon you to begin the hunt for Illidan's soul.\n\nHis rebirth will be the story of your redemption." }
WordHunterWoW_QuestEN[44482] = { title = "Recruiting Ebon Knights", description = "Korgaz Deadaxe has been hard at work training a new generation of death knights.\n\nHe has done an excellent job culling the ranks of weakness. Those who have survived the trials of death knight training are ready to join the ranks of the Ebon Blade.\n\nKorgaz is waiting for you on the upper level. I suggest you speak with him at your soonest convenience.\n\nNew death knights will bolster our ranks and aid is in the war against the Burning Legion.", objectives = "Speak to Korgaz Deadaxe.Korgaz Deadaxe has been hard at work training a new generation of death knights.\n\nHe has done an excellent job culling the ranks of weakness. Those who have survived the trials of death knight training are ready to join the ranks of the Ebon Blade.\n\nKorgaz is waiting for you on the upper level. I suggest you speak with him at your soonest convenience.\n\nNew death knights will bolster our ranks and aid is in the war against the Burning Legion.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[44483] = { title = "Vendor Beckon Trigger - Druid", description = "", objectives = "" }
WordHunterWoW_QuestEN[44484] = { title = "Vendor Beckon Trigger - Druid", description = "", objectives = "" }
WordHunterWoW_QuestEN[44486] = { title = "Fel-Ravaged Tome", description = "Much of the elven writing in the tome has been singed by fel fire.\n\nThe head of the curators in Dalaran is renowned for his restoration skills.  Perhaps he can treat the tome to bring it back to legibility.", objectives = "Bring the Fel-Ravaged Tome to Robert Newhearth in Dalaran.", progress = "Oh, what's this one now?", completion = "Ah, the burns can be reversed with the right alchemic tinctures.\n\nHow interesting.  A formal Darnassian writing style with... demonic affectations.\n\nI suspect I know who penned this." }
WordHunterWoW_QuestEN[44487] = { title = "Waterlogged Tome", description = "In spite of its magical nature, the book has been damaged by water.\n\nThe head of the curators in Dalaran is renowned for his abilities.  Perhaps he can restore it.", objectives = "Bring the Waterlogged Tome to Robert Newhearth in Dalaran.", progress = "What have we here?", completion = "I would recognize that handwriting anywhere.  This is our own Khadgar's journal!" }
WordHunterWoW_QuestEN[44488] = { title = "Cursed Tome", description = "Much of the elven writing in the tome has been singed by fel fire.\n\nThe head of the curators in Dalaran is renowned for his restoration skills.  Perhaps he can treat the tome to bring it back to legibility.", objectives = "Bring the Fel-Ravaged Tome to Robert Newhearth in Dalaran.", progress = "Oh, what's this one now?", completion = "Foul magic wards these texts.\n\nMuch stronger than anything I've seen before, but nothing that can't be undone by our mages!" }
WordHunterWoW_QuestEN[44489] = { title = "Lyana Darksorrow", description = "<Your fellow Illidari, Lyana Darksorrow, floats captive in stasis in front of you; her soul slowly draining into the harvester crystal.>\n\n<In order to release her from stasis, you will need to destroy the soul harvester.>", objectives = "Destroy the Soul Harvester.", completion = "<name>, you are a sight for sore eyes. You have my gratitude for releasing me.\n\nI do not know how long I have been held captive... but I sense an overwhelming number of demons nearby.\n\nI have much to do here. Care to join me?" }
WordHunterWoW_QuestEN[44490] = { title = "Grimwing the Devourer", description = "You have my thanks for rescuing me from captivity, {name}.\n\nHowever, Azoran is no mere demon. He is a powerful eredar who commands great rank within the Burning Legion.\n\nBefore we can get to him, there is another that must be destroyed.\n\nGrimwing the Devourer is the strongest of the felbats. Place the basilisk flesh upon the altar to the north and slay Grimwing when she appears.\n\nThen, return to me with her head. My thirst for vengeance must be quenched.", objectives = "Slay Grimwing the Devourer.", progress = "What news do you bring of Grimwing the Devourer?", completion = "Grimwing was a formidable demon... I must say I am always impressed with your skill, <name>.\n\nThere are many more demons here to kill. It is good to be at your side once more." }
WordHunterWoW_QuestEN[44491] = { title = "7.0 Suramar Collapse Scenario - Run Once", description = "", objectives = "" }
WordHunterWoW_QuestEN[44492] = { title = "Leyline Apprentice", description = "Good work finding those additional leyline feeds.\n\nYou seem rather competent - for an outlander.\n\nAllow me to share with you a few secrets about the power of the leylines. This should help you in scavenging more ancient mana from the creatures around Suramar. A grisly task, I know - which is why I leave it to you!", objectives = "Speak with Arcanist Valtrois.", completion = "Now listen closely." }
WordHunterWoW_QuestEN[44493] = { title = "Leyline Proficiency", description = "Our leyline feed grows stronger.\n\nThe more powerful our feed becomes, the more I learn about ancient mana itself.\n\nOf course, as my apprentice, you may reap the benefits of my discoveries. Listen well, and I will teach you how to extract power from your enemies more reliably.", objectives = "Speak with Arcanist Valtrois.", completion = "Do your best to pick this up the first time - I do hate repeating myself." }
WordHunterWoW_QuestEN[44495] = { title = "Leyline Master", description = "You surprise me, outlander. During our first lesson about the ancient leylines, I half-expected you to be lost in daydreams of adventure, or treasure or... some such nonsense.\n\nBut you have proven an apt student.\n\nOur leyline feed has grown extremely powerful. Watching it grow has taught me a great deal about the arcane, and the nature of mana.\n\nI have one final lesson that will help you find even more ancient mana.", objectives = "Speak with Arcanist Valtrois.", completion = "Perhaps there is hope for outlanders after all." }
WordHunterWoW_QuestEN[44496] = { title = "Destiny Unfulfilled", description = "Hardly recognizable from the golden eyed child of prophecy, and living as an outcast on the fringes of a shattered world, his motivation remained unchanged. His assaults on the Legion and his attempts to end their march were his only focus.\n\nYet, in a strange twist of fate, it was not the Burning Legion who came for him in the end.\n\nWe must travel to Outland to experience Illidan's last memory.", objectives = "Witness True Betrayal in Shadowmoon Valley on the fringes of Outland.", progress = "When the vessel is prepared, we will seek out his soul.", completion = "In the end, the denizens of Azeroth and Outland came to exact their vengeance upon Illidan. Though you did not strike a blow against him, you were complicit in his fall.\n\nI showed you Illidan's life so that you would understand why he fought and made the choices that he made. Yours was the vessel that needed preparation.\n\nIf the hatred and doubt in your heart has subsided, take your place at the side of the Light. Soon I will call upon you as we begin the hunt for Illidan's soul." }
WordHunterWoW_QuestEN[44497] = { title = "Destiny Unfulfilled", description = "Hardly recognizable from the golden eyed child of prophecy, and living as an outcast on the fringes of a shattered world, his motivation remained unchanged. His assaults on the Legion and his attempts to end their march were his only focus.\n\nYet, in a strange twist of fate, it was not the Burning Legion who came for him in the end.\n\nWe must travel to Outland to experience Illidan's last memory.", objectives = "Witness True Betrayal in Shadowmoon Valley on the fringes of Outland.", progress = "When the vessel is prepared, we will seek out his soul.", completion = "Forgive me, noble soul. I mislead you. Light's Heart was not the vessel that required preparation, it was yours.\n\nYou, who sacrificed everything for your world, and served your master dutifully until the end. These memories will serve to strengthen your resolve. Look to them when the dark temptation surrounds you and let them grant you the strength to resist and rise against the corrupters.\n\nWe will save Illidan and once more you will battle at the side of your master for the fate of all worlds." }
WordHunterWoW_QuestEN[44498] = { title = "Winterhoof Cleansing", description = "I have crafted the totem to cleanse the Winterhoof Water Well.  Now, you must take it to the well and perform a cleansing ritual.  The well is to the southeast, but be warned: whoever did this may still be there, laying in wait.\n\nThis may prove very dangerous, {name}.  Be careful...but do not let the defilers of our well escape.", objectives = "Use the Winterhoof Cleansing Totem at the Winterhoof Water Well." }
WordHunterWoW_QuestEN[44499] = { title = "Snowfang Tracking Quest", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[44500] = { title = "Author! Author!", description = "We've reviewed the tome recovered from Karazhan. Though we found references to the Pillars of Creation, one piece of crucial information was omitted from the book... where to find the artifacts.\n\nFortunately, we have access to an expert on the subject.\n\nThe author, Alodi, was the first Guardian of Tirisfal. His spirit is forever bound to the Forge of the Guardian, which has been hidden in our safekeeping. I think the time has come to call him forth.", objectives = "Tell Khadgar to begin the ritual to summon the spirit of Alodi, the first Guardian.", progress = "Alodi's knowledge of the Pillars of Creation is crucial to our campaign against the Legion.", completion = "We may not have the exact location of the Pillars of Creation, but at least we know where to start. We'll explore every corner of the Broken Isles until they're recovered.\n\nThe Legion's attack is intensifying. We must prepare to move Dalaran to the Broken Isles!" }
WordHunterWoW_QuestEN[44501] = { title = "Tracking Quest", description = "", objectives = "" }
