WordHunterWoW_QuestEN[44543] = { title = "The Battle for Broken Shore", description = "This wind rider will take you to Broken Shore, {name}. May your weapon bring you many kills today.\n\nThe Warchief has already made landfall, I will wager you will simply need to follow the trail of demon blood.", objectives = "Take the wind rider to the Broken Shore.", completion = "Glad to see you back on your feet, <name>. Many good soldiers who sailed for the Broken Shore were not so fortunate." }
WordHunterWoW_QuestEN[44544] = { title = "Call of the Earthen Ring", description = "At last, I've found you!\n\nI have a message from Advisor Sevel.\n\nThe Earthen Ring has need of you, Farseer. Please return to the Heart of Azeroth at your soonest convenience. Advisor Sevel is eagerly awaiting your return.", objectives = "Speak with Advisor Sevel.", completion = "It is good that you are here, Farseer <name>. We have much to discuss." }
WordHunterWoW_QuestEN[44545] = { title = "Pressing the Assault", description = "<With this Pillar of Creation safely secured, it is time to take advantage of your momentum and continue onward after the next.>\n\n<You recall that your order has gathered information that would aid you in your journey - looking it over once more before setting off would be wise.>", objectives = "Select your next assault point on the Broken Isles at the Command Map in your Order Hall.", completion = "<Your order's intel in hand, you are well-prepared for your next assault on the Broken Isles.>" }
WordHunterWoW_QuestEN[44546] = { title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just south of Shadowfang Keep in Silverpine Forest. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", objectives = "Kill 12 Crown Chemical Co. Employees and use Snagglebolt's Khorium Bomb to destroy a chemical wagon south of Shadowfang Keep in Silverpine Forest, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya." }
WordHunterWoW_QuestEN[44547] = { title = "Isle Hopping", description = "<Victory in hand, you know there are still Pillars of Creation that must be recovered if the Legion is to be defeated once and for all.>\n\n<Your order has identified uncharted regions of the Broken Isles that still house the remaining Pillars - looking over the information would help focus your next effort.>", objectives = "Select your next assault point on the Broken Isles at the Command Map in your Order Hall." }
WordHunterWoW_QuestEN[44548] = { title = "Scouring What Remains", description = "<Looking around the chamber, you know you are well on your way to gathering all of the Pillars of Creation, but your work is not yet complete.>\n\n<Your order has continued to scour the isles below for anything that might be useful - best to check in with them before embarking once more.>", objectives = "Select your next assault point on the Broken Isles at the Command Map in your Order Hall." }
WordHunterWoW_QuestEN[44549] = { title = "Master of the Isles", description = "<Only one region remains from your order's carefully laid plan to assault the Broken Isles and gather the Pillars of Creation.>\n\n<Victory feels close, but studying your order's intelligence one last time couldn't hurt.>", objectives = "Review your remaining assault point on the Broken Isles at the Command Map in your Order Hall." }
WordHunterWoW_QuestEN[44550] = { title = "Called to Acherus", description = "Deathlord, your presence has been requested on Acherus.\n\nThe war against the Burning Legion rages on and the Knights of the Ebon Blade await further orders.\n\nPlease return to Acherus at your soonest convenience. Siouxsie the Banshee is awaiting your return.", objectives = "Speak with Siouxsie the Banshee at Acherus: The Ebon Hold. You can use Death Gate to return there.", completion = "You have arrived at last, Deathlord. We have much to discuss." }
WordHunterWoW_QuestEN[44551] = { title = "Tracking Quest: Capturing the Gateway 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[44552] = { title = "Tracking Quest: Capturing the Gateway 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[44553] = { title = "Tracking Quest: Capturing the Gateway 3", description = "", objectives = "" }
WordHunterWoW_QuestEN[44554] = { title = "Mythic Keystone Weekly Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[44555] = { title = "Khadgar's Discovery", description = "Champion! Please come to the Violet Citadel immediately.\n\nI have made a discovery that I would like to share with you before the Council of Six.", objectives = "Speak with Archmage Khadgar in Dalaran.", completion = "Thank you for coming, <name>." }
WordHunterWoW_QuestEN[44556] = { title = "Return to Karazhan", description = "Karazhan is now in the hands of the Legion, <name>.\n\nThe fault is mine. In my haste to retrieve Alodi's book on the Pillars of Creation, the defenses I put in place to protect the tower were ramshackle at best. The Legion was quick to find a weakness.\n\nThanks to the time Sargeras spent controlling Medivh, he knows the tower's secrets as well as I do. Whatever the Dark Titan's plan is, we must do everything in our power to stop it.\n\nCome at once! I'll meet you outside Karazhan.", objectives = "Meet Khadgar outside Karazhan.", completion = "We have work to do!" }
WordHunterWoW_QuestEN[44557] = { title = "Finite Numbers", description = "It seems not all the protections I put in place have been defeated. The Legion isn't able to open portals inside or near the tower... at least, not yet.\n\nThey appear to be bringing reinforcements in through the catacombs running beneath Deadwind Pass. Disable them and you just might buy us the time we need to drive them out of Karazhan.", objectives = "Close 4 Portals and slay 20 Demons in Deadwind Pass.", completion = "Well done! At least now most of the remaining demons we have to deal with are currently inside the tower.\n\nCouldn't be more than a thousand or two, I'm sure." }
WordHunterWoW_QuestEN[44558] = { title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just south of Shadowfang Keep in Silverpine Forest. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", objectives = "Kill 12 Crown Chemical Co. Employees and use Snagglebolt's Khorium Bomb to destroy a chemical wagon south of Shadowfang Keep in Silverpine Forest, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya." }
WordHunterWoW_QuestEN[44559] = { title = "Follow the Recipe", description = "This seems to be part of a recipe for whatever concoction the Crown Chemical Company is cooking up. The other parts must be nearby.", objectives = "Collect the other parts of the Crown Chemical Company's recipe, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Aha! With this we can start on an antidote for this awful mixture. Thank you for bringing this to me." }
WordHunterWoW_QuestEN[44560] = { title = "Follow the Recipe", description = "This seems to be part of a recipe for whatever concoction the Crown Chemical Company is cooking up. The other parts must be nearby.", objectives = "Collect the other parts of the Crown Chemical Company's recipe, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Aha! With this we can start on an antidote for this awful mixture. Thank you for bringing this to me." }
WordHunterWoW_QuestEN[44561] = { title = "Seed of Hope", description = "Thalyssra was wise to send you in search of the arcan'dor, though she underestimates its power.\n\nShe will learn - as will the others.\n\nBut it will take time. And with hunger gnawing at their very souls, the Nightfallen will need your help to survive.", objectives = "Reach Honored with The Nightfallen.", progress = "The arcan'dor needs time.", completion = "In the changing of seasons, the truth will be revealed." }
WordHunterWoW_QuestEN[44562] = { title = "Growing Strong", description = "Magic has long been a vice of the elves. It shaped us, and lifted us out of the darkness - but without balance, it also threatens to unmake us.\n\nThe shal'dorei are too proud to admit it, but they are the product of indulgence. They live without harmony.\n\nBut I sense potential among the Nightfallen. Losing everything has humbled them. It has made them stronger.\n\nStay the course, {name}. Help the Nightfallen rise up.", objectives = "Reach Revered with The Nightfallen.", progress = "Have you felt it? Change is on the wind.", completion = "We shall help the shal'dorei find harmony." }
WordHunterWoW_QuestEN[44563] = { title = "Redemption for the Fallen", description = "Soon the change of seasons will be upon us, and the Nightfallen will take command of their fate.\n\nYou have given them hope, and set them on the path to redemption. They need you now more than ever.\n\nWe all do.", objectives = "Reach Exalted with The Nightfallen.", progress = "There is much to be done.", completion = "Finally, my long lost brethren can return to this world. Elves belong beneath a starry sky - not a conjured one.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[44569] = { title = "Inquisitor Volitix", description = "", objectives = "" }
WordHunterWoW_QuestEN[44570] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Midsummer Bonfire in Spires of Arak.", completion = "Honor the Spires of Arak flame." }
