WordHunterWoW_QuestEN[44616] = { title = "We'll Need Some Obliterum", description = "Loramus Thalipedes has offered to improve our armaments. He says that he pried a secret out of Razelikh. Apparently, the demon knows how to work a material known as Obliterum.\n\nI myself have coerced some information out of the demons. One of the souls trapped in my scythe has whispered the name, Camille Kleister. All I know is that she is somewhere in Dalaran. For the rest, you are on your own.", objectives = "Find Camille Kleister in the Magus Commerce Exchange district of Dalaran.", completion = "A <class>?" }
