WordHunterWoW_QuestEN[44663] = { title = "In the Blink of an Eye", description = "<The entity speaks with the familiar voice of Archmage Khadgar.>\n\nAzeroth needs you, {name}!\n\nAfter scouring Ulduar and Karazhan for answers, we know the key to defeating the Legion: five ancient artifacts called the Pillars of Creation.\n\nTo find them, Dalaran must be moved to the Broken Isles. As our leader Jaina is... absent, Kalecgos of the blue dragonflight has offered the Kirin Tor his aid.\n\nThe Legion is assaulting our current position over Deadwind Pass. Hurry!", objectives = "Witness the teleportation of Dalaran to the Broken Isles.", completion = "Ah, <name>, it's good to see you on your feet! The members of the Council of Six are recuperating from their ordeal.\n\nThe intensity of the teleportation spell can be disorienting. It seems you lost consciousness for a time, but at least you didn't awaken to find yourself stuck in a wall!\n\nDalaran has been relocated to the Broken Isles. From here, we will spearhead the effort to acquire the Pillars of Creation and drive the Legion from Azeroth once and for all!" }
WordHunterWoW_QuestEN[44667] = { title = "Will of the Valarjar", description = "As we prepare to launch an attack on the Legion's own world, it is important to not give reprieve to our enemies in this one.\n\nAs your armies seek to secure enemy gateways, you would do well to return to the Broken Isles and carry on the battle against those who stand against you.", objectives = "Complete 10 World Quests.", progress = "You've returned, <name>.", completion = "You've done well.  Our enemies tremble before you and your armies." }
