WordHunterWoW_QuestEN[44672] = { title = "Ancient Mana", description = "Without the Nightwell to feed upon, my comrades and I will have to live off the land itself.\n\nAncient mana from the underground leylines can reach the surface in many forms, most commonly as crystals or gems.\n\n<Thalyssra picks up a small stone and, whispering words of power, traces a rune upon it with her fingertip.>\n\nThis stone will glow when ancient mana is nearby. Please gather as much as possible! It will be a precious resource in the weeks to come.", objectives = "Gather from 3 Ancient Mana nodes.", progress = "We need all the ancient mana we can get. Make sure you know how to find it!", completion = "Keep a lookout for those crystal formations all over Suramar. We will need them." }
WordHunterWoW_QuestEN[44673] = { title = "Commander Soraax", description = "", objectives = "" }
WordHunterWoW_QuestEN[44675] = { title = "Lady Rivantas", description = "", objectives = "" }
WordHunterWoW_QuestEN[44676] = { title = "Llorian", description = "", objectives = "" }
WordHunterWoW_QuestEN[44677] = { title = "Ancient Mana Tutorial Chest A", description = "", objectives = "" }
WordHunterWoW_QuestEN[44678] = { title = "Ancient Mana Tutorial Chest B", description = "", objectives = "" }
WordHunterWoW_QuestEN[44679] = { title = "Ancient Mana Tutorial Chest C", description = "", objectives = "" }
WordHunterWoW_QuestEN[44680] = { title = "Leading by Example", description = "We cannot let our current situation overshadow the Unseen Path's mission to protect the people of Azeroth.\n\nThere are many in this world who could use our help.\n\nAs our leader, you can set the example by aiding those in need.", objectives = "Complete 10 World Quests.", completion = "You are an inspiration to us all, <name>." }
WordHunterWoW_QuestEN[44682] = { title = "Unparalleled Power", description = "Power is all around us, {name}, waiting to be harnessed.\n\nYou must venture out into the world and claim it for the council!\n\nWith our First wielding such unparalleled power, our enemies won't stand a chance.", objectives = "Complete 10 World Quests.", completion = "The power within you grows, <name>. You will serve the council well." }
WordHunterWoW_QuestEN[44683] = { title = "Holding the Lines", description = "Karazhan sits upon a confluence of ley lines. It's why this location was chosen for the tower in the first place... a fact that has not escaped the Legion's notice.\n\nIf the demons are tapping into these lines of power, they must need their energy for something particularly menacing. You must cut off their access to the ley lines if we're to have a chance of retaking the tower, {name}.", objectives = "Secure the Eastern Ley Line and Western Ley Line beneath Karazhan.", completion = "The Legion's hold wanes. Our time to strike grows nearer." }
WordHunterWoW_QuestEN[44684] = { title = "Corruption Runs Deep", description = "Everything the Legion touches is marred by fingerprints of their corruption. If I can study the traces of magic they leave behind, perhaps I can discern their plans for Karazhan.\n\nThis vial is specially reinforced to contain fel magic. If you bring me the essences of corrupted soil and water from near their portals, I believe we'll be closer to unraveling their scheme.", objectives = "Recover an Essence of Corrupted Soil and an Essence of Corrupted Water from the caverns beneath Deadwind Pass.", progress = "What have we here?", completion = "Every bit contains an essence of sorts - one we can study to learn things about the magic wielder and ways to manipulate their magic for... other purposes." }
WordHunterWoW_QuestEN[44685] = { title = "Reclaiming the Ramparts", description = "With the ley lines protected we must move to secure the tower's perimeter.\n\nAround the tower are several locations where corruption continues to run rampant. Seek out these locations and secure them with these wards.\n\nWith the progress we've made so far, bolstering our defenses should keep the remaining Legion's forces at bay just long enough for us to discover who's behind their efforts.", objectives = "Plant the Wards at the Eastern, Southern and Northern locations around the tower in Deadwind Pass.", progress = "Has the tower been secured?", completion = "You've bought us precious time." }
WordHunterWoW_QuestEN[44686] = { title = "Thought Collection", description = "While I examine these samples further, I ask that you seek out one of our patrols in the structure to the north. It appears they've captured one of the demons.\n\nGo, interrogate it. Find out anything you can. And hurry! I'm afraid time is no longer an ally.", objectives = "Interrogate the Captured Wyrmtongue in the structure just north of the tower in Deadwind Pass.", progress = "Has it been handled, <name>?", completion = "This information is just what we needed." }
WordHunterWoW_QuestEN[44689] = { title = "The Might of the Tirisgarde", description = "The Tirisgarde has received requests from across the Broken Isles for aid in fighting the Burning Legion. While we will continue pursuing Archmage Vargoth, we cannot forget that our primary mission is to repel the demons and protect Azeroth.", objectives = "Complete 10 World Quests.", progress = "Azeroth will burn without our help.", completion = "Well done, conjuror. With heroes like you at the helm, the Tirisgarde is a force to be reckoned with!" }
WordHunterWoW_QuestEN[44690] = { title = "A Thirst For Blood", description = "Blood is the fountain of life and the fuel of my creations. Unfortunately, Deathlord, my supply is running low and the quality as of late has been disappointing at best.\n\nIf my undead offspring are to reach their full potential, I will need pure blood of the highest quality. Bring me the Blood of Sargeras and I will use it to fuel my finest creations!", objectives = "Blood is the fountain of life and the fuel of my creations. Unfortunately, Deathlord, my supply is running low and the quality as of late has been disappointing at best.\n\nIf my undead offspring are to reach their full potential, I will need pure blood of the highest quality. Bring me the Blood of Sargeras and I will use it to fuel my finest creations!", progress = "Blood is the fountain of life and the fuel of my creations. Unfortunately, Deathlord, my supply is running low and the quality as of late has been disappointing at best.\n\nIf my undead offspring are to reach their full potential, I will need pure blood of the highest quality. Bring me the Blood of Sargeras and I will use it to fuel my finest creations!", completion = "At last, I have enough Blood of Sargeras to fuel my creations! You will see, Deathlord, what my genius is truly capable of creating...\n\nNow, I must ask that you leave me to my work... there is much to do, and we have little time to waste!" }
WordHunterWoW_QuestEN[44691] = { title = "Hungry Work", description = "We must get Chief Telemancer Oculeth back on his feet as soon as possible.\n\nFind ancient mana, any way you can, and feed it to him.", objectives = "Use Ancient Mana to feed Chief Telemancer Oculeth.", completion = "Ah, I am feeling much better. Thank you!\n\nNow let us get to work." }
WordHunterWoW_QuestEN[44694] = { title = "One Battle at a Time", description = "Before I  became a demon hunter, I practiced the arcane arts. I still retain some of that knowledge, though the fel makes it all but impossible to use.\n\nOne thing I can still manage is the occasional glimpse into faraway places. You've seen me use the nether crucible to do this. I'm afraid that things don't look too good.\n\nThe forces that are arrayed against us are not limited to the Burning Legion. You must act quickly to keep the Broken Isles from being overwhelmed.", objectives = "Complete 10 World Quests.", completion = "It would seem that you have done an excellent job of eliminating a great many threats on the Broken Isles.\n\nYou never fail to impress me, <name>." }
WordHunterWoW_QuestEN[44696] = { title = "Tracking Quest - Daily - Watcher Osu", description = "", objectives = "" }
WordHunterWoW_QuestEN[44697] = { title = "Tracking Quest - Prestige UI - Artifact", description = "", objectives = "" }
WordHunterWoW_QuestEN[44698] = { title = "Ritual Bit", description = "", objectives = "" }
WordHunterWoW_QuestEN[44700] = { title = "Stormheim", description = "It is good we found you, {name}!\n\nSky Admiral Rogers has sent word for you to meet her in Dalaran. It sounded important. She awaits your presence in the Violet Citadel.\n\nMake haste!", objectives = "Speak to Sky Admiral Rogers at the Violet Citadel in Dalaran.", completion = "It's an honor, <name>." }
WordHunterWoW_QuestEN[44701] = { title = "Stormheim", description = "It is good we found you, {name}!\n\nNathanos Blightcaller, Champion of the Banshee Queen herself, sent for you in Dalaran. He made it sound urgent. He should be waiting for you in the Violet Citadel.\n\nMake haste!", objectives = "Speak to Nathanos Blightcaller at the Violet Citadel in Dalaran.", completion = "<Nathanos glances over at you, pausing for a moment before acknowledging your presence.>\n\nYes?" }
WordHunterWoW_QuestEN[44702] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[44703] = { title = "Tracking Quest - 7.0 Special - iLevel 750 - 750 - Fox Mount 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[44704] = { title = "Tracking Quest - 7.0 Special - iLevel 750 - 750 - Fox Mount 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[44705] = { title = "Tracking Quest - 7.0 Special - iLevel 750 - 750 - Fox Mount 3", description = "", objectives = "" }
WordHunterWoW_QuestEN[44706] = { title = "Tracking Quest - 7.0 Special - iLevel 750 - 750 - Fox Mount 4", description = "", objectives = "" }
WordHunterWoW_QuestEN[44707] = { title = "Ritual of Doom", description = "", objectives = "" }
WordHunterWoW_QuestEN[44708] = { title = "Ritual of Doom", description = "", objectives = "" }
WordHunterWoW_QuestEN[44719] = { title = "Breaching the Sanctum", description = "It is time. Valtrois is ready to destroy the barrier guarding the breach in the Sanctum. I will teleport you to the breach, then it falls on you to secure the area.\n\nTake these telemancy orbs. If you find you need support, use them to summon Withered.\n\nWe must strike before the enemy can ready new defenses. Let me know when you are ready and we will begin.", objectives = "Speak with Oculeth to start the assault.", progress = "We've done it! Despite the initial failures, we are still in position to enter the Breach and free our comrades.", completion = "I must commend your knack for overcoming adversity. Take your time gathering your fellow champions, <name>, but don't take TOO long!" }
WordHunterWoW_QuestEN[44720] = { title = "A Call to Action", description = "<As the raven stares into your eyes, a familiar voice fills your mind.>\n\nChampion, I require your aid. It seems Helya has shown her hand.\n\nSteel yourself then come to me.", objectives = "Find Havi at Valdisdall.", completion = "It is good of you to come." }
WordHunterWoW_QuestEN[44721] = { title = "Helya's Conquest", description = "If Helya is making an advance on the Broken Isles, we will need to answer in turn.\n\nGo to Tideskorn Harbor and scout her forces. We will see if Helya is foolish enough to begin her campaign against me.", objectives = "Search Tideskorn Harbor for evidence of Helya's forces.", progress = "What is Helya planning?", completion = "She has forced my hand..." }
WordHunterWoW_QuestEN[44722] = { title = "Disillusioned Defector", description = "The atmosphere in the city has improved little, but we may find this to our advantage today.\n\nSilgryn asks for you at the Terrace. It seems even Elisande's forces are fleeing before her insanity.\n\nA defector has risen from the ranks and seeks to join our cause.\n\nSee that this individual is well received, {name}. We need all the friends we can get during these dark times.", objectives = "Meet Silgryn at Evermoon Terrace.", completion = "Glad you could make it." }
WordHunterWoW_QuestEN[44723] = { title = "More Like Me", description = "Greetings, Outlander.\n\nI am Victoire. I served Elisande while she maintained peace in the city. I fought beside demons and worse for the greater good.\n\nThe massacre at the Waning Crescent made it clear that she no longer serves the Nightborne. She serves only herself.\n\nThere are others who feel as I do. They simply need proof that there is another way.\n\nThe Dusk Lily is not unknown to us- try showing it to those now guarding Astravar Harbor. They have seen the worst of Elisande's cruelty.", objectives = "Use the Dusk Lily Sigil on Duskwatch Subjugators to identify 5 Deserters.", progress = "Did you find more like me?", completion = "Hopefully more will follow their example.\n\nThank you for showing them another way to serve the Nightborne." }
WordHunterWoW_QuestEN[44724] = { title = "Missing Persons", description = "Our new friend brings us some disturbing information.\n\nShe claims to have seen a large number of citizens dragged from Starcaller Retreat in chains. Their destination appears to be Astravar Harbor.\n\nThose taken to the harbor have yet to return, however. Worse yet, the area is now overrun with demons.\n\nI need you to find out where these people went. Infiltrate the harbor and gather any information you can.\n\nStart with the Legion filth- their corpses may point us in the right direction.", objectives = "Acquire a Legion Communicator from demons in Astravar Harbor.", progress = "Have you learned where the captives have been taken?", completion = "<Silgryn stares grimly at the communicator.>" }
WordHunterWoW_QuestEN[44725] = { title = "Hostage Situation", description = "Our own people, sacrificed to the Legion!\n\nWe need to intercept a transport if we intend to put an end to this trade. I'm afraid this does mean you will be playing the part of a captive, my friend.\n\nBefore voicing your concerns, try to have a little faith.\n\nWe will follow behind in one of Deline's boats and break you out once we know where they are going.\n\nGo to the harbor and find a group of captives. Stand among them. Allow yourself to be taken.\n\nWe will not be far.", objectives = "Go to Astravar Harbor and join a group of captives being taken to Felsoul Hold.", progress = "Please try to trust me. We will allow no harm to come to you.", completion = "Thank you for taking this risk. Let us put an end to this now!" }
WordHunterWoW_QuestEN[44726] = { title = "In the Business of Souls", description = "We will hold our position here while you find and slay the demon responsible for this camp.\n\nEnding Aargoss will not permanently stop this smuggling operation, but it may slow them down long enough for us to find another way to help these people.\n\nGo quickly. He is somewhere atop this ridge.", objectives = "Slay Aargoss in Felsoul Advance.", progress = "Have you dealt with Aargoss?", completion = "Well done. Let us leave before they call in reinforcements." }
WordHunterWoW_QuestEN[44727] = { title = "Smuggled!", description = "Please get me out of here!\n\nThe bars are brittle but I am so weak...\n\nThe others! There are so many others! Please help us!", objectives = "Release Maribeth and 5 captives in Felsoul Advance.", completion = "Thank you. We had no hope of rescue before you came along." }
WordHunterWoW_QuestEN[44728] = { title = "REUSE ME", description = "", objectives = "" }
WordHunterWoW_QuestEN[44729] = { title = "Trial of Valor: Odyn's Favor", description = "The time to deal with that treacherous witch has come. I suspect you may be the one to deal the final blow, but I must be certain.\n\nSee me in the Halls of Valor and we will test the strength of your will.", objectives = "Gain Odyn's favor within the Trial of Valor Raid.", completion = "Now a greater task awaits you." }
WordHunterWoW_QuestEN[44730] = { title = "Ravaged Dreams", description = "", objectives = "" }
WordHunterWoW_QuestEN[44731] = { title = "Whitewater Wash Treasure", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[44732] = { title = "Morgalash", description = "", objectives = "" }
WordHunterWoW_QuestEN[44733] = { title = "The Power of Corruption", description = "The time has come at last.\n\nDeep within the cavernous underbelly of Karazhan lies a long-forgotten chamber. Based on what you learned from our demon friend, I believe this is where its mistress dwells.\n\nThis demon's master must come from the highest ranks of the Burning Legion. This does not bode well for Karazhan.\n\nWe need to secure Deadwind Pass, {name}.\n\nYou must find this demon and destroy it.", objectives = "Use the disguise to gain access to the chamber, then slay Thar'zul and Elux'ara Darkscorn beneath Karazhan in Deadwind Pass.", progress = "The threat must be removed.", completion = "Our worst fears have been proven true, <name>. The Legion's presence is deeply rooted in the tower.\n\nThe time has come. We must take back Karazhan!" }
WordHunterWoW_QuestEN[44734] = { title = "Fragments of the Past", description = "Though your primary objective is to liberate the tower from the Legion's hold, I have... another request.\n\nKarazhan is a place where magic and history intertwine. Moments of the past have been known to take physical form, and these forms can possess great power.\n\nAs you journey through Karazhan, watch for places where memories coalesce. These fragments could provide valuable insight into what's really going on inside that tower.", objectives = "Collect the Soul Fragments from the Guest Chambers, Banquet Hall, Servant Quarters, Opera Hall and the Menagerie inside Karazhan.", progress = "Have you recovered the fragments?", completion = "For so long the secrets of the tower have remained hidden... I feel as if I have learned more about my former master.\n\nI am greatful we were able to see this journey through together, <name>." }
WordHunterWoW_QuestEN[44735] = { title = "Return to Karazhan: In the Eye of the Beholder", description = "The Legion's intentions are clear. They intend to harness the tower's magical energy to communicate with other Legion worlds!\n\nI'm afraid we haven't much time, {name}. You must ascend the tower and destroy this monstrosity before it is too late!", objectives = "Defeat Viz'aduum the Watcher in Karazhan.", progress = "The tower must be restored.", completion = "Your efforts today will not be forgotten, <name>.\n\nThough the Legion's presence has left its mark on the Karazhan we once knew, I am certain the fate of the tower will not disappoint." }
WordHunterWoW_QuestEN[44736] = { title = "Gates of the Nighthold", description = "Our combined armies are arrayed in front of the palace, ready to strike! I cannot believe the time has come.\n\nYour allied commanders are already there and we will join you. Make your way to Astravar Harbor and speak with Khadgar. He is coordinating the attack, or at least I think he is.\n\nSee you there... and thanks for everything.", objectives = "Go to Astravar Harbor and begin the siege of Nighthold with the elves.", progress = "Well, that was... unexpected.", completion = "Thank you for saving me. It seems we underestimated Elisande's power." }
WordHunterWoW_QuestEN[44737] = { title = "Helarjar Landing: Grey Shoals", description = "", objectives = "" }
WordHunterWoW_QuestEN[44738] = { title = "Full Might of the Elves", description = "Thalyssra managed to get all 3 to agree to the same thing? I am impressed with her skills of negotiation.\n\nAlright hero, Liadrin is already marching on Suramar. Join her forces.\n\nTyrande will flank the city defenders and meet you deeper in.\n\nThe Nightborne will bring up the rear and hold the territory for us.\n\nOculeth and I will move the Kirin Tor forces to Astravar Harbor. With luck, we shall see you on the other side.", objectives = "Lead the elven army to Astravar Harbor.", progress = "All this running is exhausting.", completion = "The telemancy traps you placed prior to the battle are doing wonders for reducing our losses." }
WordHunterWoW_QuestEN[44739] = { title = "Ready for Battle", description = "Thanks to your efforts and a lot of effort on the part of our new army, the Nightfallen are prepared for battle.\n\nWhat is more, we have managed to evacuate nearly all of the civilians between here and Astravar Harbor.\n\nI have drafted plans that can lead our combined forces through the city and take the harbor.\n\nCan you deliver these plans to Vereesa, Tyrande and Liadrin?", objectives = "Deliver plans to Vereesa Windrunner, Lady Liadrin and Tyrande Whisperwind.", progress = "So many different types of elves. Each of us changed in some way by the magic we wield. It is very, enlightening.", completion = "Well, with these plans and a little luck, we might be able to get through this with far less collateral damage than I would have expected." }
WordHunterWoW_QuestEN[44740] = { title = "Staging Point", description = "That is quite a corridor you and our allies have punched through the city. It will be difficult to hold but it will cut a wedge in Elisande's forces.\n\nOculeth has been busy redirecting a telemancy beacon to this location but wanted to give you the honor of activating it.", objectives = "Activate the Astravar Beacon.", progress = "Has the beacon been activated.", completion = "Well done, hero. With this as our staging ground, our forces have a clear shot at the city gates.\n\nThalyssra has ordered her rebels to secure our location and cover our rear flank.\n\nOnce we have our siege vehicles in place we should be ready to assault the city." }
WordHunterWoW_QuestEN[44741] = { title = "Return to Karazhan: The Big Bag Theory", description = "I'm sure you've heard, {name}, that a bigger bag is always better. I disagree. I believe it's the quality of the bag that makes all the difference.\n\nJust look at those tattered things around your person. They make you look... well, quite plain.\n\nI'll prove it to you. Allegedly there are some bags in Karazhan that hold an almost infinite amount of items, but the materials required to make such bags are... well, you'll see.", objectives = "Recover a Bag of a Thousand Pockets and a Fel Sinew Bag from Karazhan.", progress = "After this lesson, I trust I won't have to prove anything further to you.", completion = "Now, look closely.\n\n<Tytallo goes into a lengthy explanation concerning the thread count, weaving techniques, and other miscellaneous details that, to a tailor, are fascinating.>\n\nYou still seem confused. Here, take the pattern and see for yourself. Perhaps then you'll learn a thing or two." }
WordHunterWoW_QuestEN[44742] = { title = "Tavernkeeper's Fate", description = "I have finished unraveling Ly'leth's message.\n\nI want you to come with me to her estate. It is long past time I returned to the city.", objectives = "Follow Thalyssra to the Lunastre Estate and learn of Vanthir's fate.", progress = "Dire news like this cannot wait.", completion = "We need to take action immediately!" }
WordHunterWoW_QuestEN[44743] = { title = "Tyrande's Command", description = "Shal'aran is bursting at the seams with refugees and rebels. We practically have an army now but not enough weapons or mana to keep everyone armed and un-withered.\n\nAnd in all of this, Tyrande has a battery of requests I simply do not have the time to deal with.\n\nWill you go to her? Her growing army is hard to miss in Meredil.", objectives = "Speak with Tyrande Whisperwind in Meredil.", completion = "The Nightfallen insisted on being a part in this conflict. There is more work to be done than people we have." }
WordHunterWoW_QuestEN[44744] = { title = "Lifelines", description = "", objectives = "" }
WordHunterWoW_QuestEN[44746] = { title = "Helarjar Landing: Rockaway Coast", description = "", objectives = "" }
WordHunterWoW_QuestEN[44747] = { title = "War Cargo", description = "Lord Illidan will be arriving shortly, and my orders are to establish a base camp before he arrives.\n\nHowever, the war effort has taken its toll and I have been given little in the way of equipment and supplies.\n\nThe wreckage of the previous assault on Broken Shore lays nearby. Scavenge the beach for any supplies you can find and bring them to me.\n\nOur hope of survival will rest upon the strength of our stronghold, so we will need all the help we can find.", objectives = "" }
WordHunterWoW_QuestEN[44748] = { title = "Winged Terrors", description = "", objectives = "" }
WordHunterWoW_QuestEN[44749] = { title = "Names of the Fallen", description = "The Battle of Broken Shore was bloody and our losses were great. Many lives were lost in the defense of Azeroth.\n\nThe fallen soldiers of the Alliance and Horde deserve to have their names known.\n\nFind those valiant soldiers lost in the shipwreck and bring their insignias to me. I will ensure sure that the fallen are given a proper memorial.\n\nAzeroth will survive, and their sacrifice shall be recorded in the annals of history.", objectives = "" }
WordHunterWoW_QuestEN[44750] = { title = "Names of the Fallen", description = "The Battle of Broken Shore was bloody and our losses were great. Many lives were lost in the defense of Azeroth.\n\nThe fallen warriors of the Alliance and Horde deserve to have their names known.\n\nFind the fallen warriors lost in the shipwreck and bring their insignias to me. I will ensure sure that our honored dead are given a proper memorial.\n\nAzeroth will survive, and their sacrifice shall be recorded in the annals of history.", objectives = "" }
WordHunterWoW_QuestEN[44751] = { title = "No Soldier Left Behind", description = "", objectives = "" }
WordHunterWoW_QuestEN[44752] = { title = "Essence Triangulation", description = "Vanthir... an example! That certainly explains why Elisande chose to hold him this long.\n\nWe need to move quickly. I can track him, but I will need to find places where his Arcane Essence is strongest.\n\nThis will not be an easy feat, not in a city this old, but with any luck there are a few places important enough to him that he left a little bit of himself behind.\n\nWe should start in the promenade- he often visited it for business.", objectives = "Help Thalyssra collect 3 of Vanthir's Arcane Essences.", progress = "Did you find them?", completion = "All that remains is to focus on his essence to isolate his location. Good work." }
WordHunterWoW_QuestEN[44753] = { title = "On Public Display", description = "Now that I have identified Vanthir's essence from the multitude of Suramar's citizens, it may be that I can find his exact location.\n\nI believe you'll recall a similar ritual with our friend Theryn. Do not worry- there will be less screaming this time. Hopefully.\n\nCome. Let us find our missing tavernkeeper.", objectives = "Help Thalyssra complete the Scrying Ritual.", progress = "I need to maintain complete focus.", completion = "That was... difficult... but I am glad we succeeded." }
WordHunterWoW_QuestEN[44754] = { title = "Waxing Crescent", description = "His captor is familiar to me. He is one of Aluriel's lieutenants and a skilled spell-fencer at that. You will need Silgryn's help to retrieve the key to Vanthir's prison.\n\nOur friend's life hangs in the balance. Even if we manage to wrestle him from the executioner's grasp, he may well Wither before we can act.\n\nI need you to take an Arcan'dor fruit to him. They are precious, and few, but for Vanthir this is the only chance he has.\n\nGo quickly, and good luck.", objectives = "Rescue Vanthir and give him an Arcan'dor fruit.", progress = "<Vanthir shudders violently and stares blankly ahead. He does not seem to be aware of your presence.>", completion = "<Vanthir's hands dart up to snatch the fruit from your grasp.>" }
WordHunterWoW_QuestEN[44756] = { title = "Sign of the Dusk Lily", description = "Simply... astounding.\n\nI have not felt this clear of mind in so long.\n\nI am still weak... I need to rest. But first...\n\n<Vanthir gestures to the top of his cage with a trembling hand.>\n\nShow them that the Dusk Lily triumphs this day.", objectives = "Place a Dusk Lily Sigil above Vanthir's Cage.", completion = "I will see that he is made comfortable next chance I get. We made a great stride forward today, <name>.\n\nElisande will not soon forget that we do not simply abandon our own." }
WordHunterWoW_QuestEN[44758] = { title = "What's the Cache?", description = "We're here for a cache of gunpowder. It seems to have been infused with some sort of fel power... it's extremely reactive. One of the leaders of the pirate forces here currently has it.\n\nMaster Gunner Prix should be toward the back of the cove, near the water. Take what we need from her.", objectives = "Kill Master Gunner Prix and obtain the Fel-Infused Gunpowder Cache.", progress = "Did you get the gunpowder?", completion = "This gunpowder is the key to my plan. Right good work retrieving it." }
WordHunterWoW_QuestEN[44759] = { title = "The Vale of Dread", description = "", objectives = "" }
WordHunterWoW_QuestEN[44760] = { title = "Blood On Your Hands", description = "", objectives = "Around the isles, the very blood of our enemy attempts to corrupt all things. But as you may already know, this blood can be extracted.\n\nWe demon hunters use this blood for our own rituals, fueling us to fight back the demon invasion.\n\nBring me any Blood of Sargeras you find and I will trade with you what I can." }
WordHunterWoW_QuestEN[44761] = { title = "Mysterious Runebound Scroll", description = "", objectives = "" }
WordHunterWoW_QuestEN[44764] = { title = "Demon in Disguise", description = "While you were... working your magic on that demon, I was able to make headway in distilling the corrupted essences down to a simpler, more manageable form.\n\nI've asked Khadgar to provide you with the concoction once he's had a look, but I must remind you - these essences are quite potent, often dangerous if not handled with the utmost of care.\n\nSpeak with Khadgar when you are ready to begin.", objectives = "Speak with Archmage Khadgar in Deadwind Pass.", completion = "The samples have proven to be quite helpful along with your... influence." }
WordHunterWoW_QuestEN[44765] = { title = "Stranglethorn Fishing Extravaganza", description = "", objectives = "Any bites?", progress = "Any bites?", completion = "You'd better hurry up and hand over the fish if you want to win!" }
WordHunterWoW_QuestEN[44766] = { title = "Backup Plan", description = "Dalaran may appear to be just a floating city, but it is actually our most powerful magical weapon. It will take time to repair the arcane defenses - time the Legion will use to their great advantage.\n\nIt is imperative to come up with an interim plan, and quickly! \n\nArchmage Kalec is very knowledgeable about this sort of thing. Perhaps you should consult with him?", objectives = "Speak with Archmage Kalec.", completion = "Hmm. An interesting challenge!" }
WordHunterWoW_QuestEN[44767] = { title = "A Celestial Invitation", description = "Greetings, mortal.\n\nFor many years I have continued my observation of this planet. The halls of Ulduar have been hollow and silent, save for the occasional clattering whisper from the darkness. I grew so very bored of it!\n\nThus, I have taken up this \"pet battling\" you seem so fond of. Truly, an amusing pastime that will sustain my mind for many centuries!\n\nI have been amassing my collection, scouring the stars for tiny beings of cosmic power. Come, let us do battle once more!", objectives = "Defeat Algalon the Observer in a pet battle.", progress = "Greetings, mortal. Do you wish to engage in a battle of the tiny minions?", completion = "Ah, quite the breath of fresh solar winds. Take this, my favorite constellation, may it remind you of the watchers that watch over us all." }
WordHunterWoW_QuestEN[44768] = { title = "Nyell's Workshop", description = "From what I've overheard, this is Master Artificer Nyell's workshop. His skills in construct creation are unparalleled! \n\nWhat a shame that he swore fealty to the Legion. I hate to destroy such a renowned craftsman, but we have no choice.\n\nIf you are lucky, he might even have a spare shield generator sitting around.", objectives = "Kill Master Artificer Nyell.", progress = "Were you successful?", completion = "That is one less Legion supporter we need to worry about. Oh, and you found a shield generator too? Wonderful!" }
WordHunterWoW_QuestEN[44769] = { title = "Arming the Populace", description = "", objectives = "" }
WordHunterWoW_QuestEN[44770] = { title = "Secrets of the Shal'dorei", description = "This workshop includes an extensive library of rare scrolls written by my people. We all benefit by sharing information, do you not agree? \n\nPerhaps if we bring back such a treasure trove the Tirisgarde will be more welcoming towards me and my kind...\n\nPlease gather whatever you can.", objectives = "Gather 8 Ancient Shal'dorei Scrolls.", progress = "Have you found some scrolls?", completion = "Few texts written by the ancient shal'dorei remain. I am sure the Tirisgarde's librarians will be thrilled with these!" }
WordHunterWoW_QuestEN[44771] = { title = "A Threat Rises", description = "It is time I told you another tale. While you listen, would you be so kind as to pour me some grog? I've grown a terrible thirst.\n\nThe keg is very old and the tap is a bit slow.", objectives = "Pour Havi some grog.", progress = "I've told you my tale, but did you bring the grog?", completion = "Delicious, thank you.\n\nBefore we act, we must gather more information onto what Helya is planning." }
WordHunterWoW_QuestEN[44772] = { title = "Ch 5 Available Tracking Quest", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[44775] = { title = "The Peak of Bones", description = "While you were gone, we strategized what to do with the harness. We can utilize its power to bind the spirits of deceased drakes to you, raising them under your will as loyal soldiers.\n\nI sent Minerva to Thorim's Peak in Stormheim, where she has found a brood of deceased Thorignir. They will be prime targets.\n\nSpeak to Grimwing for a flight to the mountain, then Minerva will fill you in.", objectives = "Speak to Grimwing for a flight to Thorim's Peak, then meet Minerva.", completion = "Finally you're here, Deathlord. I've been waiting so long I could've died again." }
WordHunterWoW_QuestEN[44777] = { title = "REUSE ME", description = "", objectives = "" }
WordHunterWoW_QuestEN[44780] = { title = "Backlash", description = "", objectives = "" }
WordHunterWoW_QuestEN[44781] = { title = "The Council's Call", description = "<The Council of Six has sought your aid against a 'great threat'.>\n\n<If they have turned their focus on something outside of the demon hordes pouring out of the Tomb of Sargeras, it must be truly dangerous.>\n\n<But how does the object you found on the Broken Shore fit into all of this? You know only that the Council awaits at the Violet Citadel.>You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Seek out the Council of Six in the Violet Citadel." }
WordHunterWoW_QuestEN[44782] = { title = "Away From Prying Eyes", description = "Wars are not won solely with armies charging bravely across the battlefield, {class}t.\n\nSometimes, it is the actions of individuals that matter most, fighting battles few ever hear about. That is why - \n\n<Khadgar furrows his brow slightly.>\n\nWe should really discuss this somewhere a tad more private. Let's move up to the Purple Parlor, shall we?", objectives = "Join the Council of Six in the Purple Parlor above the Violet Citadel.", progress = "We should discuss this matter further in the Purple Parlor just above us.", completion = "Don't worry, she'll be alright.\n\nWhatever demon did this to her didn't hang around long enough to finish the job." }
WordHunterWoW_QuestEN[44783] = { title = "From Bones They Rise", description = "Alright, the job is to get the broodmother under our control. But hear me out. A few more drakes would be a boon, right?\n\nWhile we're here, why don't we use our awesome power over undeath to raise some of her brood as well? Although the peak has claimed their corpses for the ice, I'm sure the embrace of undeath will be much more welcoming. We must find their frozen corpses and breathe your will into them.", objectives = "Revive 4 Deceased Thorignir in Thorim's Peak.", progress = "Have you granted the drakes their unbirth?", completion = "I could feel their energy, even in undeath." }
WordHunterWoW_QuestEN[44784] = { title = "Advanced Wanding", description = "", objectives = "" }
WordHunterWoW_QuestEN[44785] = { title = "Tea Party", description = "I...I-I'm sorry. I... I can't...\n\n\n<You hear footsteps behind you.>\n\n\nA... Abby? Wh...", objectives = "Find Abby Lewis.", completion = "Was that really Abby? Did she bring forth that... thing? We thought her dead not long ago.\n\nWhat could we have done to bring such... such horror upon our village?" }
WordHunterWoW_QuestEN[44786] = { title = "Midterm: Rune Aptitude", description = "", objectives = "" }
WordHunterWoW_QuestEN[44787] = { title = "The Bonemother", description = "It's time to call the mother, the true reason we came. She is strong, her sheer will and strength allowing her to face this peak in order to watch over the remains of her brood. While the Thorignir is a grand sight, I like my dragons a little more bony. She must die first.\n\nRemember the pyre where we met? She is its guardian, as the spirit was at the peak. If we light it, she will come.", objectives = "Light Thorim's Beacon at Thorim's Peak to raise Daumyr. Defeat her and raise her from death.", completion = "That was quite the entrance, Deathlord." }
WordHunterWoW_QuestEN[44788] = { title = "Work Study: Bestiaries of Azsuna", description = "", objectives = "" }
WordHunterWoW_QuestEN[44789] = { title = "Holding the Ramparts", description = "With their ground presence weakened the Legion has retaliated with additional forces.\n\nOur allies managed to track several of these demons to the skies above Black Rook. I fear they intend to establish a foothold.\n\nTake this hippogryph and scout the ramparts. Should this fear become a reality I ask that you deal with the threat swiftly.", objectives = "Scout the demonic presence atop Black Rook Hold.", progress = "Any word?", completion = "Our victory here is well deserved. With their forces subdued we can press our attacks to the forward camp and the monstrosity on the horizon." }
WordHunterWoW_QuestEN[44790] = { title = "Trial by Demonfire", description = "We are out of time. I have reports that a pitlord has come to Meredil. \n\nI have dispatched a strike force. We cannot let this demon flank our army here, nor can we let him find Shal'Aran. It is time to temper these recruits in a real battle.\n\nJoin our forces in Meredil, engage the demon, and help us ensure this new army of ours is not lost in its first conflict.", objectives = "Slay Rozzeleth in Meredil.", completion = "Well done. Sometimes a single victory is enough to bring an army together. With time, these recruits shall train others, and we can grow our army to many times this size." }
WordHunterWoW_QuestEN[44799] = { title = "Safe Keeping", description = "", objectives = "" }
WordHunterWoW_QuestEN[44800] = { title = "Against Magatha's Will", description = "Well? What are you waiting for? Hand over the Doomstone.", objectives = "Talk to Magatha Grimtotem, then bring the Doomstone to Farseer Nobundo.", completion = "The Doomstone! I thought it legend, but here it is before me\n\nCan you feel its power radiating? We must only use it in times of utmost need; its power has a heavy price.\n\nYou were right not to give it to Magatha. It could do much harm in her hands.\n\nI trust you to keep it safe while we prepare an appropriate home for it." }
WordHunterWoW_QuestEN[44801] = { title = "Defending Shal'aran", description = "", objectives = "" }
WordHunterWoW_QuestEN[44802] = { title = "Ancient Guidance", description = "", objectives = "" }
WordHunterWoW_QuestEN[44803] = { title = "Return to Karazhan: Master of the House", description = "Inside the pocket watch is a worn note.\n\n\"The next affair will take place in Morgan's Plot, it will cause quite a stir! The following guests will be in attendance:\n\nLord Ference, his preferred vintage is red.\nBaroness Millstipe, she will only attend on the promise of cheese. Strange woman.\nBaron Dreuger, a ravenous soul, any well spiced meat should keep him happy.\n\nAs always, I shall ring the bell should I need you.\n\n- Medivh\"", objectives = "Collect the listed items and bring them to the cemetery outside Karazhan.", progress = "What do you have there?", completion = "Wonderful, you brought dinner! Moroes was worried he would let his master down." }
WordHunterWoW_QuestEN[44805] = { title = "In the Thick of It", description = "", objectives = "" }
WordHunterWoW_QuestEN[44811] = { title = "Help on the Way", description = "", objectives = "" }
WordHunterWoW_QuestEN[44812] = { title = "Running on Empty", description = "", objectives = "" }
WordHunterWoW_QuestEN[44813] = { title = "Ley Line Interference", description = "", objectives = "" }
WordHunterWoW_QuestEN[44814] = { title = "Waning Refuge", description = "We have done all we can here.\n\nLet us get everyone into the boat and get out while we still can.\n\nWe have bought time for the others but nothing more.", objectives = "Leave Felsoul Advance on Deline's Gondola.", completion = "These people owe their lives to your bravery. They will not forget the risks we have taken for them." }
WordHunterWoW_QuestEN[44815] = { title = "Sick of the Sycophants", description = "", objectives = "" }
WordHunterWoW_QuestEN[44816] = { title = "Continued Exposure", description = "", objectives = "" }
WordHunterWoW_QuestEN[44817] = { title = "Stirring the Swarm", description = "", objectives = "" }
WordHunterWoW_QuestEN[44821] = { title = "In Dire Need", description = "The ill tidings you bear only increase the concerns the Council has been having.\n\nI know you have your hands full with the Tomb of Sargeras. Make no mistake, the battle for the tomb remains our top priority--but we must not think the Legion foolish enough to rely on brute force alone. They are far more cunning than that.\n\nPlease, hear us out.", objectives = "Hear out the Council of Six in the Purple Parlor.", completion = "So what do you say? Up for a challenge?" }
WordHunterWoW_QuestEN[44822] = { title = "Temporal Investigations", description = "I knew the shal'dorei dabbled in time magic, but this is simply incredible...\n\nElisande stopped time on our entire army!\n\nCome, let us investigate. Perhaps there is a way to break the spell - or at least discover how it is being maintained.", objectives = "Investigate Elisande's time spell with Khadgar.", completion = "We got lucky that time, but trying again could risk all our lives for nothing. We must find another way." }
WordHunterWoW_QuestEN[44823] = { title = "Thunder Totem Cleanup Detail", description = "", objectives = "" }
WordHunterWoW_QuestEN[44825] = { title = "Wisp in the Willows", description = "Wisps are the spirits of our Night elven brethren who have become one with the forest. But their minds and the way they perceive things are very different than in life.\n\nYou should bond with this little one. See through its eyes as it travels to the hidden pools and grows some trees.You will receive:", objectives = "Guide the Wisp through the Hidden Pools to grow 8 trees." }
WordHunterWoW_QuestEN[44827] = { title = "Citizens' Army", description = "I can barely get these civilians to stand in a straight line.\n\nThey are untrained, undisciplined, and underarmed.\n\nStill, they need to be ready for the real battle.\n\nKhadgar suggested we try some field training at the ruins of Black Rook Hold in Val'sharah. The risen forces of Lord Ravencrest apparently remember how to fight.\n\nGo, hero, and I will send some trainees to support you.", objectives = "Defeat 20 of Ravencrest's forces at Black Rook Hold in Val'sharah.", completion = "The trainees you helped cannot seem to stop talking about your fighting prowess. Already they are passing along what you taught them.\n\nI appreciate your help in this." }
WordHunterWoW_QuestEN[44829] = { title = "We Need Weapons", description = "So many of the rebels want to help in the coming battle. Our people have the will, they lack only the means.\n\nThey need weapons.\n\nFrom what Khadgar has told me, the fortress of Black Rook has plenty of munitions we could use.\n\nTravel to the fortress and place these beacons on some weapon caches there. Once placed, I can teleport them back.", objectives = "Recover 3 Weapon Caches at Black Rook Hold in Val'sharah.", progress = "How goes the search?", completion = "These weapons should prove quite useful in the coming conflict. Well done, hero." }
WordHunterWoW_QuestEN[44830] = { title = "Learning From the Dead", description = "I heard you were traveling to Black Rook Hold.\n\nIt was once home to the legendary Lord Ravencrest, a brilliant tactician. His knowledge may be exactly what we need to give us an edge against the Duskwatch.\n\nWhile you are at the Rook, keep your eyes peeled for any books that might have survived the ages that outline the Ravencrest's strategems.", objectives = "Recover 5 Books of Tactics from Black Rook Hold in Val'sharah.", progress = "How goes the search?", completion = "Excellent. The knowledge in these books should prove very useful in the days to come." }
WordHunterWoW_QuestEN[44831] = { title = "Taking a Promenade", description = "These people are foreign to us, despite our common heritage. They have changed much in the years they have been cloistered away.\n\nWe need to learn more about them, what they are capable of. We dispatched one of our scouts to infiltrate the Promenade and assess the defenses. The blood elves did the same, although I doubt their ability to be discreet.\n\nBoth are long past due for reporting back to us. Find them and make sure they are safe or at least did not die in vain.", objectives = "Locate the scouts in the Promenade.", completion = "It is good to know that they are alive. Their knowledge will be valuable in the coming siege." }
WordHunterWoW_QuestEN[44832] = { title = "Scouting the Breach", description = "If Ly'leth's information is accurate, there is a breach in the Sanctum of Order that could be our only way into the Nighthold.\n\nNo doubt they have magically sealed it - take Valtrois and protect her while she examines the seal. She is an exceptional talent, and I have total faith in her ability to break whatever enchantment they have cooked up.\n\nValtrois has her own methods of getting into the city and will meet you inside the Sanctum of Order.", objectives = "Aid Valtrois underneath the Sanctum of Order in Suramar City.", completion = "It appears Ly'leth was correct. This is an entrance to the Nightwell - and it is well protected. Nothing is impenetrable though.\n\nLet us have a look at the ley lines powering this shield, shall we?" }
WordHunterWoW_QuestEN[44833] = { title = "The Seal's Power", description = "The Nightwell is so overloaded that they could not spare anything for this seal. Instead, they are borrowing power from the ley lines.\n\nI have traced one of their power sources to Kel'balor. We should head there immediately so I can determine how best to disable this barrier.\n\nYes of course I said \"we.\" Surely you do not expect me to go without my bodyguard, do you?\n\nI shall meet you there!", objectives = "Investigate the ley line device at Kel'balor in the Crimson Thicket.", progress = "Have you and Valtrois learned anything about the barrier?", completion = "Valtrois told me everything. She is hard at work on a plan for bringing down that barrier.\n\nI am afraid all we can do for now is wait. Thank you for your help." }
WordHunterWoW_QuestEN[44834] = { title = "Nullified", description = "The magus in charge of the defenses here is powerful. Perhaps too strong, even for the both of us.\n\nFortunately, the sin'dorei know a thing or two about magic. The mage's barrier is strong, but we are clever.\n\nHe has somehow channeled enough energy into his staff to power another set of defense portals, but he has left it out of his sight. Bring me the staff and an energy source from one of those constructs. I should be able to create just the thing we need to take that shield out.", objectives = "Obtain the Charged Arcshaper Staff and a Volatile Construct Core for Sendath.", progress = "It is really child's play when you consider the magical weaves. I can see the flaws with just a few minutes of study.", completion = "Excellent work. The weapon will provide the proper housing, and the magical signatures on the core will let me bypass..." }
WordHunterWoW_QuestEN[44842] = { title = "Shield, Meet Spell", description = "There you have it, one arcane nullifier! Using their weapon and magical signatures to cloak the spell, it should tear apart the shield as good as any spellbreaker would.\n\nGo teach that amateur spellslinger what it means to wage war against the sin'dorei!", objectives = "Use the Arcane Nullifier to defeat Arcshaper Thorendis.", progress = "The nullifier should do most of the work for you. Just watch out for his offensive magic!", completion = "Good. With him out of the way we will be able to establish a stronger foothold once the main force arrives." }
WordHunterWoW_QuestEN[44843] = { title = "Crystal Clearing", description = "This portal is a problem. With it they can summon countless reserves.\n\nThe crystals nearby seem to be powering the gate. If we destroy those, we can set them back significantly.", objectives = "Destroy 4 Portal Crystals.", completion = "Nice work. They will not be opening that portal again any time soon." }
WordHunterWoW_QuestEN[44844] = { title = "Powering Down the Portal", description = "Destroying the crystals will stop them temporarily, but it will be meaningless if we do not deal with the person controlling the portal itself.\n\nI heard their overseer, Ingra, shouting orders for more power so that she could bring the stronger Legion lieutenants through the gate. We must stop her to truly seal the portal for good.", objectives = "Slay Overseer Ingra.", completion = "A portal that big will not be reopening any time soon. I would say that counts as weakening their defenses." }
WordHunterWoW_QuestEN[44845] = { title = "Break An Arm", description = "The insurgents you marshaled gave me some bad news, {name}.\n\nThe arcanists loyal to Elisande have reactivated the Arm of the Magistrix. The most powerful construct ever attempted, it raged out of control and decimated an entire district before it was disabled. Truly they must be desperate to turn it against us.\n\nThe scouts have spotted it in the Crimson Thicket to the north. We cannot allow it to reach full power if we are to succeed.", objectives = "Defeat the Arm of the Magistrix.", progress = "We must destroy the Arm!", completion = "We almost lost the invasion before we could begin. Good work." }
WordHunterWoW_QuestEN[44846] = { title = "Clearing the Path", description = "", objectives = "" }
WordHunterWoW_QuestEN[44847] = { title = "Straight From the Source", description = "", objectives = "" }
WordHunterWoW_QuestEN[44848] = { title = "Ch 5 Available Tracking Quest", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[44849] = { title = "Recruitment Drive", description = "Helya's kvaldir have been raiding Azeroth's coasts for centuries, and many worthy vrykul who were destined to become my Valarjar were stolen. \n\nNow that their cursed queen is defeated, the souls held captive in Helheim can finally be freed to join us!\n\nGo to Helheim with Aerylia. I assure you she will bring you back safely.", objectives = "Ask Aerylia to escort you to Helheim.", completion = "Keep your wits about you, <name>. There are many here who will attempt to steal your soul." }
WordHunterWoW_QuestEN[44850] = { title = "Arming the Army", description = "The recent battles have greatly depleted our supplies, and we will need arms for our new Valarjar. \n\nThe kvaldir have an abundance of weapons, armor, and other spoils from their raiding stockpiled in stolen crates. \n\nConfiscate whatever you can!", objectives = "Search stolen crates for 10 stolen blades and 10 stolen shields.", progress = "Did you find any supplies we can use in Helheim <name>?", completion = "Good. These will be invaluable in the coming battles." }
WordHunterWoW_QuestEN[44853] = { title = "Melee DPS Chosen", description = "", objectives = "" }
WordHunterWoW_QuestEN[44854] = { title = "AoE Chosen", description = "", objectives = "" }
WordHunterWoW_QuestEN[44856] = { title = "Cut the Cattitude", description = "", objectives = "" }
WordHunterWoW_QuestEN[44857] = { title = "Not There, Not Then, Not Forever", description = "", objectives = "" }
WordHunterWoW_QuestEN[44858] = { title = "Trolling Them", description = "My army is disciplined, and they will follow my order not to engage the Sin'dorei in combat unless I give the command.\n\nHowever, it is with some level of shame that I must admit both armies have been attempting to harass the other with pranks, littering our respective camps with insults.\n\nPlease, {name}, we need someone both armies respect to collect these items before fighting breaks out.", objectives = "Remove insulting items from the elven war camps.", progress = "We elves are long lived, but not as long lived as our prejudices it would seem.", completion = "Thank you, <name>. Hopefully, since our forces saw you performing this task they will come to their senses and stop this harassment." }
WordHunterWoW_QuestEN[44859] = { title = "Liadrin's Command", description = "Shal'Aran is bursting at the seams with refugees and rebels. We practically have an army now but not enough weapons or mana to keep everyone armed and un-withered.\n\nAnd in all of this, Lady Liadrin has a battery of requests I simply do not have the time to deal with.\n\nWill you go to her? Her growing army is hard to miss in Meredil.", objectives = "Speak with Lady Liadrin in Meredil.", completion = "I can relate to Thalyssra's frustration.\n\nI remember when I launched my first offensive. I swear I didn't eat or sleep for a week." }
WordHunterWoW_QuestEN[44860] = { title = "Trolling Them", description = "My army is disciplined, and they will follow my order not to engage the kaldorei in combat unless I give the command.\n\nHowever, it is with some level of shame that I must admit both armies have been attempting to harass the other with pranks, littering our respective camps with insults.\n\nPlease, {name}, we need someone both armies respect to collect these items before fighting breaks out.", objectives = "Remove insulting items from the elven war camps.", completion = "Thank you, <name>. Hopefully, since our forces saw you performing this task they will come to their senses and stop this harassment." }
WordHunterWoW_QuestEN[44861] = { title = "Arming the Rebels", description = "The Nightfallen rebellion is growing in number, but they have not fought a real war in ages.\n\nVictoire and Silgryn are doing their best to train the new arrivals, but could use an experienced hand.\n\nGo to them and show them some of the skills in battle you have picked up in your travels. I want those Nightfallen ready for battle when the time comes.", objectives = "Speak with Victoire in Meredil.", completion = "Every member of the Duskwatch has had centuries to perfect their fighting techniques. We do not have that much time to get these rebels in to fighting shape." }
WordHunterWoW_QuestEN[44862] = { title = "Arming the Rebels", description = "The Nightfallen rebellion is growing in number, but they have not fought a real war in ages.\n\nVictoire and Silgryn are doing their best to train the new arrivals and could use an experienced hand.\n\nGo to them and show them some of the skills in battle you have picked up in your travels. We need those Nightfallen ready for battle when the time comes.", objectives = "Speak with Victoire in Meredil.", completion = "Every member of the Duskwatch has had centuries to perfect their fighting techniques. We do not have that much time to get these rebels in to fighting shape." }
WordHunterWoW_QuestEN[44863] = { title = "Clearing the Air", description = "Ancient weapons require ancient offerings to regain the knowledge on how to construct them.\n\nIf you wish to learn how weapons forged from air are crafted, then you must first battle with beings born from it.\n\nBring me their cores and I will gift you the knowledge you seek.", objectives = "Recover a Cardinal Sky Core, a Cardinal Storm Core, and a Cardinal Wind Core for Lunelli. Bring them back to her in Shattrath when you have all three.", progress = "Be mindful of their attacks, for with air, you never know it's there until you feel it move across your skin.", completion = "I smell the air about you and see that you have returned triumphant.\n\nHere is the knowledge that you seek." }
WordHunterWoW_QuestEN[44864] = { title = "Scarlet Crusader", description = "", objectives = "" }
WordHunterWoW_QuestEN[44865] = { title = "Butler to the Great", description = "A ghostly dinner party awaits, ready for the spread and its dinner guests.", objectives = "Lay the table, and summon Moroes.", completion = "I can't believe it's finally over." }
WordHunterWoW_QuestEN[44867] = { title = "Contain their Advance", description = "", objectives = "" }
WordHunterWoW_QuestEN[44868] = { title = "Trial of Valor: Odyn's Judgment", description = "You've proven worthy to challenge Helya. Now with my blessing, the power to defeat her is yours.", objectives = "Defeat Helya within the Trial of Valor Raid.", completion = "It is done. Helya's reign comes to an end and now we move forward. You have done a great thing today, champion. Consider yourself counted among those in the Halls of Valor." }
WordHunterWoW_QuestEN[44869] = { title = "Talon Terror", description = "I just received word that the Shrine of Aviana is under attack by the Burning Legion! While the Druids of the Talon here are taking their time planning and strategizing their defense, our brothers and sisters are being slaughtered where they stand.\n\nI cannot stand idly by while my home shrine is in danger. Please, come with me to save my people.", objectives = "Use the portal in the Dreamway to meet Thisalee at the Shrine of Aviana in Mount Hyjal.", completion = "It took all my willpower not to jump into the fray without backup. Let's go!" }
WordHunterWoW_QuestEN[44870] = { title = "Mouths to Feed", description = "We have rescued many refugees, as you can see. Unfortunately this has revealed a new problem.\n\nThe arcan'dor fruit is our salvation, but it does not bear enough fruit right now to cure everyone. We must rely on mana a little longer to tide the refugees over.\n\nValtrois thinks that she may have a solution. Please go speak with her and see what she plans to do.", objectives = "Speak with Arcanist Valtrois in Shal'Aran.", completion = "It is good to see you. I could use a helping hand." }
WordHunterWoW_QuestEN[44871] = { title = "7.1 World - 850 - Special - Moroes 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[44872] = { title = "7.1 World - 850 - Special - Moroes 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[44873] = { title = "Oculeth Ex Machina", description = "I have a plan to feed Shal'Aran.\n\nNow that I am no longer starving for mana I have had time to study ley lines in new regions. I detected an eddy of mana in the ley lines of Azsuna. I have plenty of magic at my disposal, but we must visit the ley line in person in order to properly redirect the energy to Shal'Aran.\n\nOculeth has graciously offered to teleport us there, but I could use an assistant. Care to join me?", objectives = "Speak with Oculeth and teleport to Azsuna.", completion = "That was a little terrifying. Sometimes I am not entirely sure that Oculeth knows what he is doing." }
WordHunterWoW_QuestEN[44874] = { title = "Unbeleyvable", description = "Back to the task at hand!\n\nTake these ley line taps. We can use the resonant energies to properly redirect the flow, but they must be placed in precise locations. I will show you where.\n\nYour friend has agreed to... \"supervise\" us. Let us hope she just stays out of the way while the professionals take care of this.", objectives = "Assist Arcanist Valtrois with placing ley line taps.", progress = "This ley line energy will not move itself. We must give it encouragement.", completion = "That was more infuriating than it should have been. At least her natural talents mostly matched my calculations..." }
WordHunterWoW_QuestEN[44875] = { title = "The Art of Flow", description = "All done, {name}! We have but one more step and Shal'Aran will have all the mana it needs.\n\nNow that I have better access to the ley line below I can break the pool so that it will flow through properly. Given the chaotic state of this ley line it will require all of my concentration to redirect the energy.\n\nI must warn you that we will attract attention while I am doing this. You will need to protect me while I complete the process.\n\nSpeak to me when you are ready.", objectives = "Protect Arcanist Valtrois while she completes the ritual.", progress = "This ritual will shake the pool of energy loose, allowing it to flow through the ley line unimpeded.", completion = "It is done. Shal'Aran will have no want of mana now." }
WordHunterWoW_QuestEN[44876] = { title = "A Dance With Dragons", description = "I must say I am impressed, {name}.\n\nYou and your friend were able to fix a ley line, and you are not even dragons!\n\nYou both seem exhausted by this ordeal. Allow me to help you get back home.", objectives = "Speak with Stellagosa to ride back to Shal'Aran.", completion = "That is quite the adventure you had. Thankfully we now have plenty of mana for the refugees. Thank you, <name>." }
WordHunterWoW_QuestEN[44877] = { title = "Attack on the Roost", description = "Skylord Shadegrove has been leading the defense of the shrine, but I think he's starting to lose hope. Clearly he needs some more firepower behind him!\n\nLet's take out these demons and fend off the attack. They'll never see it coming!", objectives = "Kill 15 Legion invaders.", progress = "I love the feeling of my knife in a demon's back!", completion = "Ha! Take that, demon scum!" }
WordHunterWoW_QuestEN[44879] = { title = "Snowfeather Matriarch Tracking Q", description = "", objectives = "" }
WordHunterWoW_QuestEN[44880] = { title = "Direbeak Matriarch Tracking Q", description = "", objectives = "" }
WordHunterWoW_QuestEN[44881] = { title = "Sharptalon Matriarch Tracking Q", description = "", objectives = "" }
WordHunterWoW_QuestEN[44882] = { title = "Bloodgazer Matriarch Tracking Q", description = "", objectives = "" }
WordHunterWoW_QuestEN[44883] = { title = "A Speedy Delivery", description = "The Silver Hand are launching a second assault to the west, where the Alliance and Horde fleet previously landed during the first attack. Their objective is to take the beach and liberate any survivors or captives they can find.\n\nEven as we speak, they do battle against the enemy. There is little time to spare, we must aid them as soon as possible.\n\nMake your way down to the beach and find Justicar Julia Celeste. She is leading the Silver Hand's attack and will know best we can aid them.", objectives = "" }
WordHunterWoW_QuestEN[44884] = { title = "Defense of Emerald Bay", description = "", objectives = "" }
WordHunterWoW_QuestEN[44885] = { title = "Shipwrecked Survivors", description = "It appears that we have allies here on the Broken Shore.\n\nA small band of shipwrecked soldiers have been surviving here since the first assault. Their strength and tenacity will bolster our ranks.\n\nMake your way to their encampment along the beach and bring them here. Tell them that reinforcements have arrived, and the battle against the Burning Legion waits for no one.", objectives = "Speak with First Sergeant Steelfang.It appears that we have allies here on the Broken Shore.\n\nA small band of shipwrecked soldiers have been surviving here since the first assault. Their strength and tenacity will bolster our ranks.\n\nMake your way to their encampment along the beach and bring them here. Tell them that reinforcements have arrived, and the battle against the Burning Legion waits for no one.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[44886] = { title = "Unwanted Evidence", description = "<You find a shattered remnant of fel crystal clutched in Skovald's hand, still glowing with demonic power.\n\nIt seems the god-king didn't want it found. Did the crystal contain the message sent to him by Gul'dan?\n\nIf anyone can glean the meaning of the broken crystal, it's Khadgar.>", objectives = "Bring the Fel Crystal Fragment to Archmage Khadgar in Dalaran.", progress = "Greetings, <name>.\n\nDid you intercept Gul'dan's message to Skovald?", completion = "You believe Skovald didn't want you to find this crystal, eh? Let me have a look.\n\n<Khadgar peers at the fel crystal fragment, tracing the lines of power that run through it.>\n\nI have seen this sort of crystal before. They are used to convey orders that come from the highest ranks of the Legion.\n\nThis is not good." }
WordHunterWoW_QuestEN[44887] = { title = "Uncovering Orders", description = "It would seem secret orders have been parceled out by the Legion's masters. If they're determined to conceal their plan from us, it must pose a dire threat.\n\nWe know high-ranking demons and their allies are mobilizing in places of power. Odds are good that they have received similar crystals.\n\nPerhaps you can find one intact, or at least gather enough fragments that we can reassemble one and determine the Legion's target.", objectives = "Recover the Fragment of Spite from Blackrook Hold (Mythic), the Fragment of Power from Violet Hold (Mythic), and the Fragment of Torment from Vault of the Wardens (Mythic).", progress = "We need to get to the bottom of what the Legion is planning.", completion = "Well done! That couldn't have been easy.\n\nThis should be enough fragments. Let's have a look." }
WordHunterWoW_QuestEN[44888] = { title = "Aviana's Grace", description = "If this was only the distraction, where is the main force? Who else is under attack? We need to figure out who else is in danger! Aviana should know, she's got eyes everywhere.\n\nLet's go ask her. We should be able to contact her in the back room.", objectives = "Contact Aviana in the Shrine of Aviana.", completion = "Nature is in dire need, mortal. You must fix it." }
WordHunterWoW_QuestEN[44889] = { title = "Resource Management", description = "Now that you possess Helya's Horn, the kvaldir are yours to command. We may as well put them to good use for a change. \n\nI've dispatched my Val'kyr, Danica, to the Broken Shore. She has identified a few Legion targets that should be eliminated.\n\nAerylia will send you there when you are ready to leave.", objectives = "Talk to Aerylia to travel to the Path of Suffering on the Broken Shore.", completion = "Good to see you made it, Battlelord <name>!" }
