WordHunterWoW_QuestEN[44913] = { title = "reuse me", description = "Defeat Viz'aduum the Watcher in Karazhan (Normal).You will receive:", objectives = "Defeat Viz'aduum the Watcher in Karazhan on Normal difficulty." }
WordHunterWoW_QuestEN[44914] = { title = "Arms: The Thieving Apprentice", description = "The Focusing Iris has been stolen from the Dalaran Vaults! The thief was a mage of some skill, but we've been unable to track him.\n\nFortunately, the thief dropped a note from his master, addressing him as one of his \"apprentici.\" I know of only one mage who uses that particular pluralization - Archmage Xylem.\n\nI'll need you to investigate. In Azshara you will find his tower where he trains his apprentices. Go there, and see what Xylem is up to.\n\nSpecialization: Arms Warrior", objectives = "Travel to Xylem's Tower within Bear's Head in Azshara.", completion = "So someone stole the Focusing Iris and you suspect Xylem might be the culprit? You may be right. \n\nIt is no secret that the archmage has been seeking artifacts of late. However, after the discovery of an ancient grimoire in the Legashi ruins, Xylem has become... unstable. I fear the grimoire may be stealing his mind.\n\nI can help you gain audience with the archmage.  With any luck, you can reclaim the Iris peacefully." }
WordHunterWoW_QuestEN[44915] = { title = "Professionally Good Looking", description = "The archmage has recently locked himself away in his tower. If you wish to enter, you'll need help from some of his apprentices. I'm afraid you won't get it dressed like that.\n\nXylem has a thing for... outfits, and his apprentices use them to show rank. If you wish his apprentices to help you, you'll need to appear their superior. Such is their desire to impress the archmage, many of his apprentices will battle each other for the best pieces.\n\nI think you know where this is going.", objectives = "Collect the Fanciful Hat, Well-Tailored Robes, and Magnificent Mantle from Raethas Dawnseer, Lobos and Phloem in Azshara.", progress = "Feeling stylish?", completion = "Yes, I think that will do.\n\nThe apprentices outside the tower should think you outrank them now, so you should be able to get some information out of them. You'll need it to bypass the barrier." }
WordHunterWoW_QuestEN[44916] = { title = "99.0 [reuse me]", description = "99.0 [reuse me]You will receive:", objectives = "99.0 [reuse me]" }
WordHunterWoW_QuestEN[44917] = { title = "Return to Karazhan: The Tower of Power", description = "Your champions discovered that the area surrounding Karazhan is under an invasion from the Legion. This does not bode well.\n\nClimb the tower, and defeat all in your path.", objectives = "Defeat Viz'aduum the Watcher in Karazhan.", progress = "How are you finding the challenges of Karazhan?", completion = "Were you able to defeat the evils within Karazhan?" }
WordHunterWoW_QuestEN[44918] = { title = "A Message From Our Enemies", description = "{name}! The messages from Ly'leth we traced throughout the Terrace - we could not have known at the time, but somebody was watching.\n\nThis crystal was delivered by a courier early this morning. <Pointing to the crystal by her side.>\n\nI am afraid the message contained within is not for the faint of heart. It has not been shown to anyone else, but you deserve to see it for all you have done for us.", objectives = "Listen to Andaris's Message in Shal'Aran.", progress = "We have no time to waste.", completion = "I do not know what lies in store for us, but we cannot sit idly while Ly'leth is missing.\n\nWe must act now!" }
WordHunterWoW_QuestEN[44919] = { title = "A Challenge From Our Enemies", description = "Make no mistake. This message cannot be taken lightly. Any threat made against our people will be dealt with swiftly.\n\nWe must travel to the estate at once to discover what has become of Ly'leth.", objectives = "Meet Andaris at the Lunastre Estate in Suramar City.", completion = "The withered... defeated so easily.\n\nWe must find a way to negate the magic of the felborne. We cannot afford to fight if our own can be turned against us." }
WordHunterWoW_QuestEN[44920] = { title = "Order of Incantations", description = "The barrier shielding the tower can only be opened by activating the imbued gems in the correct order. The order is only known to Xylem and his inner circle of apprentices. No others have yet been able to decipher the code, and mistakes are met with deadly consequences.\n\nThe aspiring apprentices spend a lot of their time around the tower. Some may have seen or heard something that might point to a solution.\n\nLet us hope, for your sake, their information proves valuable.", objectives = "Speak with Xylem's apprentices in Bear's Head to decipher the code to open the barrier to his tower." }
WordHunterWoW_QuestEN[44921] = { title = "Lone Wolf", description = "My eyes and ears fly across Azeroth, bringing me back news of many things. My ally Goldrinn took to the barrows of Moonglade in mourning upon the death of Varian Wrynn. He has been untouched in the dream... until now.\n\nDemons have been seen invading the very same barrows, killing many more of our mortal druids in the process. You must go. Save Goldrinn, avenge our people! Take my hatchling Thisalee with you. Her tenacity and bloodlust is welcome in my clutch. You shall have my aid.", objectives = "Meet Thisalee Crow in Moonglade.", completion = "If Goldrinn is in the Dream, he's defenseless! We've got to help!" }
WordHunterWoW_QuestEN[44922] = { title = "Inside the Winter Storm", description = "There, it looks like there's a good spot to launch to right across from here. This path should take you all the way to the top.\n\nAccording to my  intel, your dragons should be up there. Let's just hope that they're still in a state to help you.", objectives = "Grapple across from the tower and climb to the top of the mountain path." }
WordHunterWoW_QuestEN[44923] = { title = "Helarjar Landing: Vrekt", description = "", objectives = "" }
WordHunterWoW_QuestEN[44924] = { title = "The Archmage Accosted", description = "With the barrier dispelled, Archmage Xylem is finally within reach!\n\nHopefully he'll be cooperative in returning the Iris...", objectives = "Confront Archmage Xylem.", completion = "It is as I feared, the archmage is beyond reason... and now he is beyond reach.\n\nYou have done a great thing here, freeing his apprentices from his corruption, but this fight is not over yet." }
WordHunterWoW_QuestEN[44925] = { title = "Closing the Eye", description = "We have received reports from the apprentices at Xylem's Tower that they've been able to use the remant of Xylem's portal to pinpoint his location.\n\nWe have orders from the Council of Six to open a portal directly to him, though whatever magic he's channeling on the other end is powerful enough to allow us to only keep it open for a brief window.\n\nThe apprentice, Joanna asked I give you this message before you proceed. Speak to me when you're ready.", objectives = "Speak with War Councilor Victoria to be teleported to Archmage Xylem's location and defeat him.", completion = "I apologize for my actions, <class>. I was a fool to tap into the power of the grimoire, and that folly could have cost Azeroth dearly. \n\nI thank you not only for purging and defeating the shadowy evil that had hold of me, but also for sparing my life.\n\nMyself, as well as all of Azeroth, are in your debt." }
WordHunterWoW_QuestEN[44926] = { title = "A Familiar Axe to Grind", description = "The construction of this blade feels familiar, but you can't quite recall where you may have seen something like it before.\n\nPerhaps someone at Chiselgrip might know more about its construction.", objectives = "Show the axe blade to Hoddruc Bladebender at Chiselgrip.\n\nProvided item:", completion = "Oh aye! I know the make of that chopper.\n\nTha master who made it also created the famous Bleakwood Hew. You may 'ave heard of it.\n\nAn' it just so happens I know how to make the hew too!" }
WordHunterWoW_QuestEN[44927] = { title = "Worth Its Weight in Steel", description = "Listen, ye seem like one who may be interested in getting a copy of those axe plans.\n\nCould probably make a pretty penny at the auction house on it. But I can't just hand 'em over to ya, lad. Not fer free.\n\nThat axe blade ye brought me, I could use more of those. Good steel in those blades. Don't worry, lad, I just need a few...\n\nWhat do ye say?", objectives = "Gather 30 Axe Blades from orcs and ogres around the Burning Steppes. Return them to Hoddruc in Chiselgrip when you've collected them all.", progress = "You see, I've got a shipment ta fill and it's been slim pickin' round these parts for good metal. Those blades are just what I'm lookin' for.", completion = "Oh ho! Look at all that STEEL!\n\nI'll have this shipment finished by the end o' the week. Well done, lad! Well done!\n\nAn' as I promised, here are those plans for the hew." }
WordHunterWoW_QuestEN[44928] = { title = "Something's Not Quite Right...", description = "Something is troubling me, champion.\n\nBeyond these simple japes, the Kirin Tor has had to break up a few fights between the elves. I am worried something - or someone - might be influencing them.\n\nYour disguise was made by the nightborne, yes? It is not unreasonable to assume they can do something similar.\n\nFortunately, Thalyssra has told me much about how the illusion works, and I believe this crystal can remove their disguise.\n\nWhy don't you check the camps, just to be safe?", objectives = "Remove the disguise of 5 Nightborne Infiltrators.", progress = "Were you able to find the instigators?", completion = "It is as I feared. Hopefully they will think twice before sending more spies." }
WordHunterWoW_QuestEN[44930] = { title = "Deadmines: Sea'in Red", description = "Arr, finally! I been stuck up here f'years with naught company but me own thoughts. Tis good to clap me eyes on another swashbuckling soul. Are ye up for a plot of revenge and skullduggery? These meddlin' Defias thugs murdered  me and me crew years ago before they took over this cave. I propose a series of counter-murders to bring about balance! Bring me proof ye've dealt with enough of the thieves to clog a bilge pump!", objectives = "Collect 100 Bloodied Defias Bandanas for Captain Bramblebeard.", progress = "Revenge is worth waitin' for. Not that I have much in the way of choice.", completion = "Ha ha ha! I hope those rotten thugs rot in whatever pit of misery spawned them." }
WordHunterWoW_QuestEN[44931] = { title = "REUSE", description = "<Your snowfeather hatchling looks at you timidly. It appears to be looking to you to help it survive and grow.>", objectives = "Raise your Snowfeather Hatchling to level 25." }
