WordHunterWoW_QuestEN[44940] = { title = "Inside the Winter Storm", description = "There, it looks like there's a good spot to launch to right across from here. This path should take you all the way to the top.\n\nAccording to my  intel, your dragons should be up there. Let's just hope that they're still in a state to help you.", objectives = "Grapple across from the tower and climb to the top of the mountain path." }
WordHunterWoW_QuestEN[44941] = { title = "Dances With Ravenbears (UNUSED)", description = "<The chieftain beckons for the ravenbears to gather the tribute and gestures toward the ritual circle outside.>\n\nCaw! Caw ca-caw!\n\n<It looks like he wants you to follow.>You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Help the Blackfeather ravenbears perform their tribute ritual." }
WordHunterWoW_QuestEN[44943] = { title = "Now That's Just Clawful!", description = "", objectives = "" }
WordHunterWoW_QuestEN[44944] = { title = "Aura of Uncertainty", description = "We may not know the Legion's intent just yet, but after analyzing your findings we will know soon enough.", objectives = "Help Khadgar unravel the mystery behind the fragments.", progress = "Have all the information you need?", completion = "The time has come, <name>." }
WordHunterWoW_QuestEN[44948] = { title = "Raising Your Snowfeather", description = "<Your snowfeather hatchling looks at you timidly. It appears to be looking to you to help it survive and grow.>", objectives = "Raise your Snowfeather Hatchling to level 25.", progress = "Erk?", completion = "<The hatchling seems to trust you a bit more now. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44949] = { title = "The Smell of Humans", description = "<You've noticed that your snowfeather hatchling shakes whenever humans are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of humans, so that it can get used to the smell.>", objectives = "Take your Snowfeather Hatchling to the Gilded Rose in Stormwind.", progress = "<Your snowfeather hatchling looks at you uncertainly.>", completion = "<The hatchling seems to be more comfortable around the sights and sounds of a human city. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44950] = { title = "Hunting Lesson: Northern Hawk Owls", description = "<Your snowfeather hatchling seems to get agitated when you are near other critters, none more so than the hawk owls of Highmountain. It fluffs up its plumage and squawks loudly whenever one is nearby. It appears to have a primal need for predation.> \n\n<It seems you will need to take your falcosaur out hunting.>", objectives = "Defeat 3 Northern Hawk Owls in Highmountain with your Snowfeather Hatchling.<Your snowfeather hatchling seems to get agitated when you are near other critters, none more so than the hawk owls of Highmountain. It fluffs up its plumage and squawks loudly whenever one is nearby. It appears to have a primal need for predation.> \n\n<It seems you will need to take your falcosaur out hunting.>", progress = "<Your snowfeather hatchling looks ready for some exercise.>", completion = "<The hatchling seems quite content with its victories, and settles in for a nap. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44951] = { title = "Tank Chosen", description = "", objectives = "" }
WordHunterWoW_QuestEN[44952] = { title = "Blackrock Depths: Jewel of the Depths", description = "Welcome to Everlook. Could I interest you in a new weapon of sorts?\n\nYou know, I'm not just into selling weapons of mass dismemberment here at the shop. I like rare jewels as well.\n\nPerhaps you and I can come to an arrangement of sorts in procuring a jewel I've had my eye on getting for quite some time. I have some great blacksmithing plans here you might be interested in, you know, in trade for your services.\n\nNow, onto the details...", objectives = "Travel to Blackrock Depths and obtain a Core of Bael'Gar, Core of Roccor, Essence of Incendius, and Essence of Magmus. Once you have all four items, combine them at the Black Forge near the entrance to Molten Core at the bottom of Blackrock Depths and bring the Blackrock Ruby back to Wixxrak in Everlook.", progress = "This ain't no easy task. It's why the jewel's so rare, you see?", completion = "Whoa, now that's a RUBY! I'd only ever seen one other of its kind in the world and now I have one.\n\nI tell ya, this is gonna make me stinkin' rich!\n\nBut uh, onto your payment. Here are those plans I was mentioning." }
WordHunterWoW_QuestEN[44953] = { title = "Allies in Highmountain", description = "<Your snowfeather hatchling emits a deep, chittering growl when you pass near Thunder Totem.> \n\n<The Highmountain Tribes immediately began attempting to evict the falcosaurs from their territory. It must consider them a threat to the flock, and the growl is probably its attempt to protect you.>\n\n<Show your falcosaur that you and it can work alongside the Highmountain Tribes.>", objectives = "Complete 5 World Quests in Highmountain with your Snowfeather Hatchling out.<Your snowfeather hatchling emits a deep, chittering growl when you pass near Thunder Totem.> \n\n<The Highmountain Tribes immediately began attempting to evict the falcosaurs from their territory. It must consider them a threat to the flock, and the growl is probably its attempt to protect you.>\n\n<Show your falcosaur that you and it can work alongside the Highmountain Tribes.>", progress = "<Your snowfeather hatchling isn't at all sure about this.>", completion = "<The hatchling trills at the sight of Thunder Totem. That's quite an improvement! It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44954] = { title = "Snowfeather Team Up", description = "<Your snowfeather hatchling looks at you and emits a sort of squawking bark. It appears to want to do something together as a team!>\n\n<To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", objectives = "Defeat 3 Pet Battle World Quests in Broken Isles with your Snowfeather Hatchling.<Your snowfeather hatchling looks at you and emits a sort of squawking bark. It appears to want to do something together as a team!>\n\n<To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", progress = "<Your snowfeather hatchling looks ready for your commands!>", completion = "<The hatchling rams you softly with its head and trills. It seems to like doing things with you quite a lot! It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44955] = { title = "Visitor in Shal'Aran", description = "Someone came to Shal'Aran while you were in the City. She asked for you specifically.\n\nI did not recognize her face, nor her voice, but she seemed trustworthy and earnest.\n\nShe is just outside the cavern. Meet with her and determine her purpose for coming here.", objectives = "Meet the stranger outside Shal'Aran.", progress = "What have you learned?", completion = "She looked good. The Arcan'dor truly is a miracle for our people.\n\nShe is a welcome ally in the fight to come. Silgryn will take good care of her." }
WordHunterWoW_QuestEN[44956] = { title = "Deadly Prey", description = "<After working together on recent pet battles, your snowfeather falcosaur seems much more interested in your combat abilities. It might learn a thing or two from watching you do battle with a powerful opponent.>", objectives = "Complete 1 Rare Elite World Quest with your Snowfeather Hatchling out.", progress = "<Your snowfeather hatchling looks ready to learn!>", completion = "<The hatchling looks at you with admiration. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44957] = { title = "Hunting Lesson: Spiketail Beaver", description = "<Your snowfeather hatchling has been interested in following beaver tracks recently. It must have found a new species to prey upon.>", objectives = "Defeat 3 Spiketail Beavers in Highmountain with your Snowfeather Hatchling.<Your snowfeather hatchling has been interested in following beaver tracks recently. It must have found a new species to prey upon.>", progress = "<Your snowfeather hatchling looks ready to hunt.>", completion = "<The hatchling looks more confident after besting those beavers, and settles in for a nap. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44958] = { title = "The Unfriendly Faction", description = "<When passing the other faction recently, your snowfeather walked right up to them without fear. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", objectives = "Complete 3 PvP World Quests with your Snowfeather Hatchling out.<When passing the other faction recently, your snowfeather walked right up to them without fear. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", progress = "<Your snowfeather hatchling seems to like the other faction a bit too much.>", completion = "<The hatchling emits a low hiss when you pass a member of the opposite faction. Mission accomplished! It will need to rest after this adventure.>" }
WordHunterWoW_QuestEN[44959] = { title = "Snowfeather Bonding", description = "<Your snowfeather hatchling keeps getting into your pack and making a mess. It squawks loudly whenever you remove it, and rams you with its head. Maybe you can distract it with a tiny pack of its own?>", objectives = "Buy a Tiny Pack from Susana Averoy in Dalaran for your Snowfeather Hatchling.", progress = "<Your snowfeather hatchling looks at you inquisitively.>", completion = "<You feel a special bond form between you and the hatchling. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44960] = { title = "Hunting Lesson: Mudshell Conch", description = "<Your snowfeather hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the snails of Highmountain.>", objectives = "Defeat 3 Mudshell Conches in Highmountain with your Snowfeather Hatchling and 2 Flying pets.<Your snowfeather hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the snails of Highmountain.>", progress = "<Your snowfeather hatchling preens.>", completion = "<The hatchling looks more confident in its abilities. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44961] = { title = "Teamwork Lesson: Naraxas", description = "<While victorious, your snowfeather hatchling squawked and pecked at its allies during some of those last fights. Showing it a good example of teamwork might help.>", objectives = "Defeat Naraxas in Neltharion's Lair in Highmountain with your Snowfeather Hatchling out.", progress = "<Your snowfeather hatchling looks to you for guidance.>", completion = "<The hatchling looks like it might have absorbed some of that lesson, at least it enjoyed the trip. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44962] = { title = "Hunting Lesson: Coralback Fiddler", description = "<Your snowfeather hatchling is particularly wary of the elemental pets in your menagerie. They will need to learn to work together if they are to get along. Hunting together against the new prey it has begun stalking may just do the trick.>", objectives = "Defeat 3 Coralback Fiddlers in Highmountain with your Snowfeather Hatchling and 2 Elemental pets.<Your snowfeather hatchling is particularly wary of the elemental pets in your menagerie. They will need to learn to work together if they are to get along. Hunting together against the new prey it has begun stalking may just do the trick.>", progress = "<Your snowfeather hatchling looks wary of your elemental pets.>", completion = "<The hatchling looks much more at ease around elementals now. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44963] = { title = "Ranged DPS Chosen", description = "", objectives = "" }
WordHunterWoW_QuestEN[44964] = { title = "I'll Just Leave This Here", description = "Valtrois has a plan for the Sanctum's energy barrier.\n\nSeveral key Arcway locations throughout Suramar harness the power necessary for it. These Energy Disruptors she made will remotely break the links simultaneously on activation, causing the barrier to fall.\n\nTake these devices and install them at the leylines, then return here for the surprise assault on the Sanctum.", objectives = "Place Energy Disruptors at the energy sources in Teloth'aran, Kel'balor and Elor'shan in Suramar.", completion = "The preparations are nearly complete. Oculeth will be ready to teleport us soon." }
WordHunterWoW_QuestEN[44965] = { title = "Stealth Chosen", description = "", objectives = "" }
WordHunterWoW_QuestEN[44966] = { title = "Healer Chosen", description = "", objectives = "" }
WordHunterWoW_QuestEN[44967] = { title = "Teamwork Lesson: Ursoc", description = "<Your snowfeather hatchling continues to fight with other pets when threatened. It must learn to remain calm under pressure, even when facing great beasts. Showing it an epic example of teamwork against a great beast might help.>", objectives = "Defeat Ursoc in the Emerald Nightmare with your Snowfeather Hatchling out.", progress = "<Your snowfeather hatchling looks to you for guidance.>", completion = "<The hatchling positively beams at you in pride for defeating such a frightening foe. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44968] = { title = "Snowfeather Team Rumble", description = "<Your snowfeather hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", objectives = "Defeat 3 Pet Battle World Quests with your Snowfeather Hatchling and 2 Undead pets.<Your snowfeather hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", progress = "<Your snowfeather hatchling is ready to go!>", completion = "<The hatchling looks proud of itself and preens after the victory. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44969] = { title = "Snowfeather Reunion", description = "<Your snowfeather hatchling has been lethargic as of late. It seems to be depressed. Perhaps it is time to return it to its place of origin?>", objectives = "Return the Snowfeather Hatchling to the Misty Coast in Highmountain." }
WordHunterWoW_QuestEN[44970] = { title = "Dual Boss Chosen", description = "", objectives = "" }
WordHunterWoW_QuestEN[44971] = { title = "The Smell of Orcs", description = "<You've noticed that your snowfeather hatchling shakes whenever orcs are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of orcs, so that it can get used to the smell.>", objectives = "Take your Snowfeather Hatchling to the Broken Tusk in Orgrimmar.", progress = "<Your snowfeather hatchling looks at you uncertainly.>", completion = "<The hatchling seems to be more comfortable around the sights and sounds of an orc city. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44973] = { title = "Raising Your Direbeak", description = "<Your direbeak hatchling appears uncertain about what to do with itself. It appears to be looking to you to help it survive and grow.>", objectives = "Raise your Direbeak Hatchling to level 25.", progress = "Erk!", completion = "<The hatchling struts around happily, clearing showing off. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44974] = { title = "The Smell of Dwarves", description = "<You've noticed that your direbeak hatchling shakes whenever dwarves are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of dwarves, so that it can get used to the smell.>", objectives = "Take your Direbeak Hatchling to the Stonefire Tavern in Ironforge.", progress = "<Your direbeak hatchling looks at you uncertainly.>", completion = "<The hatchling seems to be more comfortable around the sights and sounds of a dwarven city. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44975] = { title = "The Smell of Tauren", description = "<You've noticed that your direbeak hatchling shakes whenever tauren are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of tauren, so that it can get used to the smell.>", objectives = "Take your Direbeak Hatchling to the Inn in Thunder Bluff.", progress = "<Your direbeak hatchling looks at you uncertainly.>", completion = "<The hatchling seems to be more comfortable around the sights and sounds of a tauren city. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44976] = { title = "Hunting Lesson: Rose Taipan", description = "<Your direbeak hatchling seems to get agitated when you are near other critters, none more so than the rose taipans of Stormheim. It squawks loudly and slams its beak into the dirt whenever one is nearby. It appears to have a primal need for predation.> \n\n<It seems you will need to take your falcosaur out hunting.>", objectives = "Defeat 3 Rose Taipans in Stormheim with your Direbeak Hatchling.<Your direbeak hatchling seems to get agitated when you are near other critters, none more so than the rose taipans of Stormheim. It squawks loudly and slams its beak into the dirt whenever one is nearby. It appears to have a primal need for predation.> \n\n<It seems you will need to take your falcosaur out hunting.>", progress = "<Your direbeak hatchling looks ready for some exercise.>", completion = "<The hatchling seems quite content with its victories, and claws at your leg until you sit down and create a lap it can sit on. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44977] = { title = "Allies in Stormheim", description = "<Your direbeak hatchling scratches the ground and stares down a member of the Valarjar more than ten times its size.> \n\n<The Valarjar must have seen the falcosaurs as an excellent new source of meat, and begun hunting them immediately. Though a new species to the Broken Isles, it already fears the inhabitants of Stormheim.>\n\n<Show your falcosaur that you and it can work alongside the Valarjar.>", objectives = "Complete 5 World Quests in Stormheim with your Direbeak Hatchling out.<Your direbeak hatchling scratches the ground and stares down a member of the Valarjar more than ten times its size.> \n\n<The Valarjar must have seen the falcosaurs as an excellent new source of meat, and begun hunting them immediately. Though a new species to the Broken Isles, it already fears the inhabitants of Stormheim.>\n\n<Show your falcosaur that you and it can work alongside the Valarjar.>", progress = "<Your direbeak hatchling isn't at all sure about this.>", completion = "<The hatchling no longer cowers behind you when the storms crackle in Stormheim. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44978] = { title = "Direbeak Team Up", description = "<Your direbeak hatchling bites you. It appears to want to do something together as a team!>\n\n<To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", objectives = "Defeat 3 Pet Battle World Quests in Broken Isles with your Direbeak Hatchling.<Your direbeak hatchling bites you. It appears to want to do something together as a team!>\n\n<To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", progress = "<Your direbeak hatchling looks ready for your commands!>", completion = "<The hatchling nips at your feet excitedly. It seems to like doing things with you quite a lot! It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44979] = { title = "Dire Prey", description = "<Your direbeak falcosaur nearly trips you the next time you enter combat. It is eager to learn more about how to defeat deadly creatures. It might learn a thing or two from watching you do battle with a powerful opponent.>", objectives = "Complete 1 Rare Elite World Quest with your Direbeak Hatchling out.", progress = "<Your direbeak hatchling looks ready to learn!>", completion = "<The hatchling looks at you with interest. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44980] = { title = "Hunting Lesson: Tiny Apparition", description = "<Your direbeak hatchling seems to see prey that you cannot, sometimes staring at a wall for hours at a time. It must have found a new species to prey upon, or gotten into some mead.>", objectives = "Defeat 3 Tiny Apparitions in Stormheim with your Direbeak Hatchling.<Your direbeak hatchling seems to see prey that you cannot, sometimes staring at a wall for hours at a time. It must have found a new species to prey upon, or gotten into some mead.>", progress = "<Your direbeak hatchling looks ready to hunt.>", completion = "<Your direbeak certainly doesn't look afraid of ghosts. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44981] = { title = "The Unkindly Faction", description = "<When passing the other faction recently, your direbeak squawked at them for food. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", objectives = "Complete 3 PvP World Quests with your Direbeak Hatchling out.<When passing the other faction recently, your direbeak squawked at them for food. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", progress = "<Your direbeak hatchling seems to like the other faction a bit too much.>", completion = "<The hatchling scratches the ground aggressively when you pass a member of the opposite faction. Mission accomplished! It will need to rest after this adventure.>" }
WordHunterWoW_QuestEN[44982] = { title = "Direbeak Bonding", description = "<Your direbeak hatchling puffs up its feathers and growls at you in a display of dominance. It seems unhappy with the results, as you are not cowering in fear. It might like to dress up like a grown-up falcosaur and try again.>", objectives = "Buy a pair of Fake Teeth from Clockwork Assistant in Dalaran for your Direbeak Hatchling.", progress = "<Your direbeak hatchling looks at you inquisitively.>", completion = "<You feel a special bond form between you and the hatchling. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44983] = { title = "Hunting Lesson: Golden Eaglet", description = "<Your direbeak hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the eagles of Stormheim.>", objectives = "Defeat 3 Golden Eaglets in Stormheim with your Direbeak Hatchling and 2 Flying pets.<Your direbeak hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the eagles of Stormheim.>", progress = "<Your direbeak hatchling preens.>", completion = "<The hatchling builds a small nest of eaglet feathers, and settles in for a nap. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44984] = { title = "Teamwork Lesson: Fenryr", description = "<Your direbeak hatchling timidly avoided the other flying pets during their last battles together. Showing it a good example of teamwork might help.>", objectives = "Defeat Fenryr in Halls of Valor in Stormheim with your Direbeak Hatchling out.", progress = "<Your direbeak hatchling looks to you for guidance.>", completion = "<The hatchling has taken a large puff of wolf fur for its nest, and you're not entirely sure where it was concealing it. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44985] = { title = "Hunting Lesson: Stormstruck Beaver", description = "<Your direbeak hatchling looks warily at any loud piece of machinery you pass. You begin to wonder if something transpired between it and a mechanical pet at one point. They will need to learn to work together if they are to get along. Hunting together against the new prey it has begun stalking may just do the trick.>", objectives = "Defeat 3 Stormstruck Beavers in Stormheim with your Direbeak Hatchling and 2 Mechanical pets.<Your direbeak hatchling looks warily at any loud piece of machinery you pass. You begin to wonder if something transpired between it and a mechanical pet at one point. They will need to learn to work together if they are to get along. Hunting together against the new prey it has begun stalking may just do the trick.>", progress = "<Your direbeak hatchling looks wary of your mechanical pets.>", completion = "<The hatchling looks much more at ease around machines now. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44986] = { title = "Teamwork Lesson: Krosus", description = "<Your direbeak hatchling squawks loudly and panics when very large creatures are nearby, even if they are friendly. It must learn to remain calm under pressure, even when facing creatures many times its size. Showing it an epic example of teamwork against a monster the size of a mountain might help.>", objectives = "Defeat Krosus in the Nighthold with your Direbeak Hatchling out.", progress = "<Your direbeak hatchling looks to you for guidance.>", completion = "<The hatchling growls at you possessively. It seems... proud? It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44987] = { title = "Direbeak Team Rumble", description = "<Your direbeak hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", objectives = "Defeat 3 Pet Battle World Quests with your Direbeak Hatchling and 2 Humanoid pets.<Your direbeak hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", completion = "<The hatchling somehow still has energy, and runs off to play with your other pets. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44988] = { title = "Direbeak Reunion", description = "<Your direbeak hatchling won't stop emitting soft, melancholy squawks. It seems to be depressed. Perhaps it is time to return it to its place of origin?>", objectives = "Return the Direbeak Hatchling to Gull Rock in Stormheim." }
WordHunterWoW_QuestEN[44989] = { title = "Raising Your Sharptalon", description = "<Your sharptalon hatchling continues to shiver as it settles in at your side. It looks up at you with wide, unblinking eyes. It appears to be looking to you to help it survive and grow.>", objectives = "Raise your Sharptalon Hatchling to level 25.", progress = "Baroo!", completion = "<The hatchling is no longer shaking and clinging to your side. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44990] = { title = "Raising Your Bloodgazer", description = "<Your bloodgazer hatchling looks at you curiously, cocking its head to the side and emitting a low whistle. It appears to be looking to you to help it survive and grow.>", objectives = "Raise your Bloodgazer Hatchling to level 25.", progress = "Errrrrk...", completion = "<The hatchling looks strong and confident. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44991] = { title = "The Smell of Draenei", description = "<You've noticed that your bloodgazer hatchling shakes whenever draenei are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of draenei, so that it can get used to the smell.>", objectives = "Take your Bloodgazer Hatchling to the Inn in the Exodar.", progress = "<Your bloodgazer hatchling looks at you uncertainly.>", completion = "<The hatchling seems to be more comfortable around the sights and sounds of a draenei city. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44992] = { title = "The Smell of Night Elves", description = "<You've noticed that your sharptalon hatchling shakes whenever night elves are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of night elves, so that it can get used to the smell.>", objectives = "Take your Sharptalon Hatchling to the Inn in Darnassus.", progress = "<Your sharptalon hatchling looks at you uncertainly.>", completion = "<The hatchling seems to be more comfortable around the sights and sounds of a night elf city. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44993] = { title = "The Smell of Blood Elves", description = "<You've noticed that your bloodgazer hatchling shakes whenever blood elves are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of blood elves, so that it can get used to the smell.>", objectives = "Take your Bloodgazer Hatchling to the Silvermoon City Inn in Silvermoon.", completion = "<The hatchling seems to be more comfortable around the sights and sounds of a blood elf city. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44994] = { title = "The Smell of Undead", description = "<You've noticed that your sharptalon hatchling shakes whenever forsaken are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of forsaken, so that it can get used to the smell.>", objectives = "Take your Sharptalon Hatchling to the Inn in Undercity.", progress = "<Your sharptalon hatchling looks at you uncertainly.>", completion = "<The hatchling seems to be more comfortable around the sights and sounds of a forsaken city. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44995] = { title = "Hunting Lesson: Spring Strider", description = "<Your sharptalon hatchling seems to get agitated when you are near other critters, especially the spring striders of Val'sharah. It fluffs up its plumage and scratches the ground whenever one is nearby. It appears to have a primal need for predation.> \n\n<It seems you will need to take your falcosaur out hunting.>", objectives = "Defeat 3 Spring Striders in Val'sharah with your Sharptalon Hatchling.<Your sharptalon hatchling seems to get agitated when you are near other critters, especially the spring striders of Val'sharah. It fluffs up its plumage and scratches the ground whenever one is nearby. It appears to have a primal need for predation.> \n\n<It seems you will need to take your falcosaur out hunting.>", progress = "<Your sharptalon hatchling looks ready for some exercise.>", completion = "<The hatchling seems quite content with its victories, and butts you with its head lovingly. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44996] = { title = "Hunting Lesson: Erudite Manafiend", description = "<Your bloodgazer hatchling seems to get agitated when you are near other critters, none more so than the erudite manafiends of Azsuna. It makes an odd, low clucking noise and spreads its wings whenever one is nearby. It appears to have a primal need for predation.> \n\n<It seems you will need to take your falcosaur out hunting.>", objectives = "Defeat 3 Erudite Manafiends in Azsuna with your Bloodgazer Hatchling.<Your bloodgazer hatchling seems to get agitated when you are near other critters, none more so than the erudite manafiends of Azsuna. It makes an odd, low clucking noise and spreads its wings whenever one is nearby. It appears to have a primal need for predation.> \n\n<It seems you will need to take your falcosaur out hunting.>", progress = "<Your bloodgazer hatchling looks ready for some exercise.>", completion = "<The hatchling seems quite content with its victories, and clucks happily at you. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44997] = { title = "Allies in Val'sharah", description = "<Your sharptalon hatchling stubbornly refuses to enter Val'sharah when you approach.> \n\n<Though they revere nature, the Dreamweavers also must maintain the balance of nature, and began an aggressive campaign against the falcosaurs once their invasiveness was noted. It has likely seen the druids of Val'sharah slaughter some members of its flock.>\n\n<Show your falcosaur that you and it can work alongside the Dreamweavers.>", objectives = "Complete 5 World Quests in Val'sharah with your Sharptalon Hatchling out.<Your sharptalon hatchling stubbornly refuses to enter Val'sharah when you approach.> \n\n<Though they revere nature, the Dreamweavers also must maintain the balance of nature, and began an aggressive campaign against the falcosaurs once their invasiveness was noted. It has likely seen the druids of Val'sharah slaughter some members of its flock.>\n\n<Show your falcosaur that you and it can work alongside the Dreamweavers.>", progress = "<Your sharptalon hatchling isn't at all sure about this.>", completion = "<The hatchling no longer shivers when entering the dense foliage of Val'sharah. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44998] = { title = "Allies in Azsuna", description = "<Your bloodgazer hatchling emits a terrified squawk, and you sense the spirits of Azsuna are nearby.> \n\n<The spirits of the elves of Azsuna must seem strange and unnatural to your pet. It may instinctively fear them.>\n\n<Show your falcosaur that you and it can work alongside the spirits of the Court of Farondis.>", objectives = "Complete 5 World Quests in Azsuna with your Bloodgazer Hatchling out.<Your bloodgazer hatchling emits a terrified squawk, and you sense the spirits of Azsuna are nearby.> \n\n<The spirits of the elves of Azsuna must seem strange and unnatural to your pet. It may instinctively fear them.>\n\n<Show your falcosaur that you and it can work alongside the spirits of the Court of Farondis.>", progress = "<Your bloodgazer hatchling isn't at all sure about this.>", completion = "<The hatchling is more curious than afraid of the ghosts in Azsuna now. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[44999] = { title = "Sharptalon Team Up", description = "<Your sharptalon hatchling flaps its wings excitedly and squawks at you. It appears to want to do something together as a team!>\n\n<To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", objectives = "Defeat 3 Pet Battle World Quests in Broken Isles with your Sharptalon Hatchling.<Your sharptalon hatchling flaps its wings excitedly and squawks at you. It appears to want to do something together as a team!>\n\n<To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", progress = "<Your sharptalon hatchling looks ready for your commands!>", completion = "<The hatchling emits a loud \"baroo!\" It seems to like doing things with you quite a lot! It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[45000] = { title = "Bloodgazer Team Up", description = "<Your bloodgazer hatchling runs in a circle around your feet, nearly tripping you. It appears to want to do something together as a team!>\n\n<To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", objectives = "Defeat 3 Pet Battle World Quests in Broken Isles with your Bloodgazer Hatchling.<Your bloodgazer hatchling runs in a circle around your feet, nearly tripping you. It appears to want to do something together as a team!>\n\n<To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", progress = "<Your bloodgazer hatchling looks ready for your commands!>", completion = "<The hatchling beams at you. It seems to like doing things with you quite a lot! It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[45001] = { title = "Destructive Prey", description = "<Your sharptalon falcosaur watches carefully when you are in combat. It appears to be interested in your abilities. It might learn a thing or two from watching you do battle with a powerful opponent.>", objectives = "Complete 1 Rare Elite World Quest with your Sharptalon Hatchling out.", progress = "<Your sharptalon hatchling looks ready to learn!>", completion = "<The hatchling looks more confident in your abilities. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[45002] = { title = "Dangerous Prey", description = "<Your bloodgazer falcosaur continues to tremble timidly whenever a powerful creature is nearby. It would help to build its confidence to see you defeat such a creature.>", objectives = "Complete 1 Rare Elite World Quest with your Bloodgazer Hatchling out.", progress = "<Your bloodgazer hatchling looks ready to learn!>", completion = "<The hatchling caws at you. A compliment, perhaps? It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[45003] = { title = "Hunting Lesson: Terror Larva", description = "<Your sharptalon hatchling has been desperately rooting for worms in Val'sharah recently. It must have found a new species to prey upon.>", objectives = "Defeat 3 Terror Larvae in Val'sharah with your Sharptalon Hatchling.<Your sharptalon hatchling has been desperately rooting for worms in Val'sharah recently. It must have found a new species to prey upon.>", progress = "<Your sharptalon hatchling looks ready to hunt.>", completion = "<The hatchling gulps down one of the larva, then momentarily looks like it is going to be sick. You had better keep an eye on it. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[45004] = { title = "Hunting Lesson: Fledgling Kingfeather", description = "<Your bloodgazer hatchling has been flapping its wings excitedly and rubbing its beak on the trunks of trees in Azsuna. It must have found a new species to prey upon.>", objectives = "Defeat 3 Fledgling Kingfeathers in Azsuna with your Bloodgazer Hatchling.<Your bloodgazer hatchling has been flapping its wings excitedly and rubbing its beak on the trunks of trees in Azsuna. It must have found a new species to prey upon.>", progress = "<Your bloodgazer hatchling looks ready to hunt.>", completion = "<Besting another flying pet has really boosted your bloodgazer's confidence. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[45005] = { title = "The Uncongenial Faction", description = "<When passing the other faction recently, your sharptalon attempted to play with their pet. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", objectives = "Complete 3 PvP World Quests with your Sharptalon Hatchling out.<When passing the other faction recently, your sharptalon attempted to play with their pet. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", progress = "<Your sharptalon hatchling seems to like the other faction a bit too much.>", completion = "<The hatchling runs behind you when you pass a member of the opposite faction. Mission accomplished! It will need to rest after this adventure.>" }
WordHunterWoW_QuestEN[45006] = { title = "The Unfavorable Faction", description = "<When passing the other faction recently, your bloodgazer sniffed curiously at their pack. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", objectives = "Complete 3 PvP World Quests with your Bloodgazer Hatchling out.<When passing the other faction recently, your bloodgazer sniffed curiously at their pack. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", progress = "<Your bloodgazer hatchling seems to like the other faction a bit too much.>", completion = "<The hatchling puffs itself up when you pass a member of the opposite faction. Mission accomplished! It will need to rest after this adventure.>" }
WordHunterWoW_QuestEN[45007] = { title = "Sharptalon Bonding", description = "<Your sharptalon hatchling will instinctively run into the kitchen of any inn you enter and make a mess of the pots and pans. It has a tendency to get into any dishes that are laying about, especially the dirty ones. You may be able to curb this behavior by finding it some silverware of its very own.>", objectives = "Buy a Dirty Spoon from Mel Lynchen in Dalaran for your Sharptalon Hatchling.", progress = "<Your sharptalon hatchling looks at you inquisitively.>", completion = "<You feel a special bond form between you and the hatchling. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[45008] = { title = "Bloodgazer Bonding", description = "<Your bloodgazer hatchling seems to love rolling around in flowers. You surmise that an affinity to flowering plants has probably helped the flock locate fruits to consume in the past. It would probably be quite excited to have a special flower of its own!>", objectives = "Buy a Purple Blossom from Aerith Primrose in Dalaran for your Bloodgazer Hatchling.", progress = "<Your bloodgazer hatchling looks at you inquisitively.>", completion = "<You feel a special bond form between you and the hatchling. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[45009] = { title = "Hunting Lesson: Auburn Ringtail", description = "<Your sharptalon hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the raccoons of Val'sharah.>", objectives = "Defeat 3 Auburn Ringtails in Val'sharah with your Sharptalon Hatchling and 2 Flying pets.<Your sharptalon hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the raccoons of Val'sharah.>", progress = "<Your sharptalon hatchling preens.>", completion = "<The hatchling pulls at a shedding nail, it will be sharp again soon. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[45010] = { title = "Hunting Lesson: Juvenile Scuttleback", description = "<Your bloodgazer hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the crabs of Azsuna.>", objectives = "Defeat 3 Juvenile Scuttlebacks in Azsuna with your Bloodgazer Hatchling and 2 Flying pets.<Your bloodgazer hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the crabs of Azsuna.>", progress = "<Your bloodgazer hatchling preens.>", completion = "<The hatchling licks its wounds, hurt but satisfied. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[45011] = { title = "Teamwork Lesson: Dresaron", description = "<Your sharptalon hatchling does not seem particularly interested in your other pets, and largely ignores them during combat. Showing it a good example of teamwork might help.>", objectives = "Defeat Dresaron in Darkheart Thicket in Val'sharah with your Sharptalon Hatchling out.", progress = "<Your sharptalon hatchling looks to you for guidance.>", completion = "<The hatchling looks exhausted, and falls asleep immediately. It appears to be having some kind of nightmare. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[45012] = { title = "Teamwork Lesson: Serpentrix", description = "<While victorious, your bloodgazer hatchling distracted your other pets during crucial moments in combat. Showing it a good example of teamwork might help.>", objectives = "Defeat Serpentrix in Eye of Azshara in Azsuna with your Bloodgazer Hatchling out.", progress = "<Your bloodgazer hatchling looks to you for guidance.>", completion = "<The hatchling glows slightly with magical energy, what did it get into? It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[45013] = { title = "Hunting Lesson: Vale Flitter", description = "<Your sharptalon hatchling adamantly refuses to go anywhere near a body of water, squawking and scratching the ground whenever you wade in yourself. Perhaps working with some aquatic pets would help it get over this fear. Hunting together against the new prey it has begun stalking may just do the trick.>", objectives = "Defeat 3 Vale Flitters in Val'sharah with your Sharptalon Hatchling and 2 Aquatic pets.<Your sharptalon hatchling adamantly refuses to go anywhere near a body of water, squawking and scratching the ground whenever you wade in yourself. Perhaps working with some aquatic pets would help it get over this fear. Hunting together against the new prey it has begun stalking may just do the trick.>", progress = "<Your sharptalon hatchling looks wary of your aquatic pets.>", completion = "<The hatchling looks much more at ease around water now. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[45014] = { title = "Hunting Lesson: Felspider", description = "<Whenever you retire to an inn, your hatchling climbs the furniture and refuses to touch the ground. It will hop unsteadily from object to object, often causing a large mess. You recall that this may be due to a bad experience with fleas. Hunting together with some critter pets against new prey might help it get over this fear.>", objectives = "Defeat 3 Felspiders in Azsuna with your Bloodgazer Hatchling and 2 Critter pets.<Whenever you retire to an inn, your hatchling climbs the furniture and refuses to touch the ground. It will hop unsteadily from object to object, often causing a large mess. You recall that this may be due to a bad experience with fleas. Hunting together with some critter pets against new prey might help it get over this fear.>", progress = "<Your bloodgazer hatchling looks wary of your critter pets.>", completion = "<The hatchling looks much more at ease around insects now. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[45015] = { title = "Teamwork Lesson: Xavius", description = "<Your sharptalon hatchling has taken to hiding in your pack when you approach very powerful creatures in the world. It must learn to remain calm under pressure, even when facing the darkest of nightmares. Showing it an epic example of teamwork against a fearsome foe might help.>", objectives = "Defeat Xavius in the Emerald Nightmare with your Sharptalon Hatchling out.", progress = "<Your sharptalon hatchling looks to you for guidance.>", completion = "<The hatchling looks at you timidly. It appears to be a little afraid of your power. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[45016] = { title = "Teamwork Lesson: Skorpyron", description = "<Your bloodgazer hatchling growls and hisses at large beasts, seemingly without concern for its own safety. It will need to learn to rely on numbers to keep it safe. Showing it an epic example of teamwork against a great beast might help.>", objectives = "Defeat Skorpyron in the Nighthold with your Bloodgazer Hatchling out.", progress = "<Your bloodgazer hatchling looks to you for guidance.>", completion = "<The hatchling chews on a fragment of the great scorpion thoughtfully. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[45017] = { title = "Sharptalon Team Rumble", description = "<Your sharptalon hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", objectives = "Defeat 3 Pet Battle World Quests with your Sharptalon Hatchling and 2 Magic pets.<Your sharptalon hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", progress = "<Your sharptalon hatchling is ready to go!>", completion = "<The hatchling looks worn out, and spends quite a few minutes drinking after the victory. It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[45018] = { title = "Bloodgazer Team Rumble", description = "<Your bloodgazer hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", objectives = "Defeat 3 Pet Battle World Quests with your Bloodgazer Hatchling and 2 Beast pets.<Your bloodgazer hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", progress = "<Your bloodgazer hatchling is ready to go!>", completion = "<The hatchling looks quite full. What did it eat? It will need some time to recover from this adventure.>" }
WordHunterWoW_QuestEN[45019] = { title = "Sharptalon Reunion", description = "<Your sharptalon hatchling has not been eating recently. It seems to be depressed. Perhaps it is time to return it to its place of origin?>", objectives = "Return the Sharptalon Hatchling to the Verdant Cliffs in Val'sharah." }
WordHunterWoW_QuestEN[45020] = { title = "Bloodgazer Reunion", description = "<Your bloodgazer hatchling refuses to drink. It seems to be depressed. Perhaps it is time to return it to its place of origin?>", objectives = "Return the Bloodgazer Hatchling to Alluvanon's Delta in Azsuna." }
WordHunterWoW_QuestEN[45021] = { title = "Answers Unknown", description = "Have you noticed a change in Jubeka's demeanor? I know she's not the warmest of warlocks, but I fear she's been more withdrawn than usual.\n\nI imagine her mind lingers on Kanrethad, the council's one-time leader. Jubeka was steadfast in her commitment to keeping him banished, until the Burning Legion took her as their prisoner.\n\nHis fate is unknown, and it's clearly troubling our friend. The last thing she said to me, was that she felt his presence in Azsuna. Don't let her travel this path alone.", objectives = "Find Jubeka Shadowbreaker within Azsuna.", completion = "Shinfel should not have told you of my suspicions. This is my burden to bear.\n\nNevertheless, I am glad you are here. It would seem my fears are founded." }
WordHunterWoW_QuestEN[45022] = { title = "3+ Targets Chosen", description = "", objectives = "" }
WordHunterWoW_QuestEN[45023] = { title = "Hybrid Chosen", description = "", objectives = "" }
WordHunterWoW_QuestEN[45024] = { title = "Cult Culling", description = "The lure of Kanrethad is strong. Even when not in this world, there are those who wish to be near him at any cost, hoping to share in his power.\n\nA group of these fanatics are here in Faronaar, working tirelessly to bring Kanrethad back, I've learned as much from my prisoner.\n\nWe cannot let them succeed, {name}. Find their compound and kill as many of them as you can.\n\nI will remain here and see what else I can learn about their intentions.", objectives = "Head into Felfire Cavern and kill members of the Cult of the Green Flame.", completion = "Can it be true? Does some sliver of my friend remain within that wretched demon?" }
WordHunterWoW_QuestEN[45025] = { title = "Stealing the Source of Power", description = "My prisoner is a chatty one, {name}. He tells me that the Cult of the Green Flame is harnessing fel energy to fuel their efforts of bringing Kanrethad back from banishment.\n\nWithin their compound they are powering fel crystals that can hold a great amount of fel magic. Without the proper power to perform their ritual, the occultists will have a tough time succeeding in their task.\n\nSteal their fel crystals, but don't destroy them. We can always find a use for something so powerful.", objectives = "Collect 5 Fel Crystals.", progress = "Have you obtained the fel crystals?", completion = "Excellent work, as always, Netherlord. This should certainly buy us some time." }
WordHunterWoW_QuestEN[45026] = { title = "Expending Fel Energy", description = "Soon Kanrethad's banishment will fade, and he will return to our world. \n\nWe must keep him, and his power, out of the Legion's hands at any cost.\n\nIf my old friend is still in there somewhere, perhaps we can bring him back.\n\nThe crystals you recovered feed on fel energy. We can use the ravenous crystals to siphon away the magic that consumes Kanrethad.\n\nBut first, their power must be depleted. To do so, you will need to harness the power of the crystals and use their energy to kill demons.", objectives = "Harness the power of the Fel Crystals and expend their energy by killing demons within Faronaar.", progress = "Have the crystals been depleted?", completion = "Thank you, Netherlord. I will keep these crystals safe until they are needed.\n\nWhen we find Kanrethad, we will be ready." }
WordHunterWoW_QuestEN[45027] = { title = "To the Broken Shore", description = "It would seem that Kanrethad's twisted followers have begun their ritual on the Broken Shore.\n\nWe must act quickly. The Burning Legion cannot be allowed to use Kanrethad as their weapon.\n\nWe have acolytes on standby, ready to perform a ritual of summoning on the Broken Shore when you're ready.", objectives = "Head to the Broken Shore.", completion = "You're here, Netherlord! Quickly, there's no time to lose!" }
WordHunterWoW_QuestEN[45028] = { title = "The Fate of Kanrethad", description = "I can feel his presence, Netherlord! Kanrethad is here! His followers have set up camp in the nearby pass, and are performing the ritual to bring him back as we speak.\n\nQuickly, take the fel crystals. Arrange them in a circle around Kanrethad.\n\nIf placed correctly, the crystals should link together and begin to siphon the fel energy.\n\nNow go, before it's too late!", objectives = "Use the Fel Crystals to siphon fel energy from Kanrethad.", progress = "We cannot allow the Burning Legion to take control of Kanrethad.", completion = "I have lived with a heavy heart since the day I fulfilled my promise to banish Kanrethad. I never thought I'd live to see the day he would be returned to us.\n\nI thank you, Netherlord. You have lifted the burden of guilt from my shoulders, and in doing so, prevented the Legion from gaining control of one of our own." }
WordHunterWoW_QuestEN[45029] = { title = "Talon's Vengeance - Intro Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[45030] = { title = "The Fel-Etched Bone", description = "<The bone is covered in intricate runes, etched directly into the surface in what can only be powerful fel magic.>\n\n<Surely someone among the Kirin Tor in Dalaran would be interested in this.>", objectives = "Find someone interested in the Fel-Etched Bone. You suspect that the Kirin Tor in Dalaran are a good place to start." }
WordHunterWoW_QuestEN[45032] = { title = "Like the Wind", description = "", objectives = "" }
WordHunterWoW_QuestEN[45033] = { title = "The Inferno Stone", description = "<While just another bit of fel debris to the untrained eye, you recognize this stone as one of the catalysts used to accelerate the regeneration of the Legion's strongest warriors in the nether.>\n\n<What it is doing in Azeroth is uncertain. Perhaps the Kirin Tor in Dalaran could help you learn more?>", objectives = "Find someone who can help you study the Inferno Stone. You suspect that the Kirin Tor in Dalaran are a good place to start." }
WordHunterWoW_QuestEN[45034] = { title = "Fire the Cannons!", description = "It will take more than a damn shipwreck to bring me down. Those overgrown, vomit-reeking, demon felbags have another thing coming if they think that's all it's gonna take to stop me.  \n\n<Keeshan coughs up seawater, wiping his mouth dry with his sleeve.>\n\nUghh... I may need a little breather though. Here, take this flare gun and use it to call down artillery strikes on the beach. Rain hell on those worthless, half-goat bastards and I'll rendezvous with you back at the base when the mission is complete!", objectives = "Slay 14 demons." }
WordHunterWoW_QuestEN[45035] = { title = "The Call of Battle", description = "These demons have no honor! Rather than meet us in glorious, open-battle; they hide behind their barricades and siege weapons.\n\nThe Valarjar have come for the glory of battle and we will not be turned away by cowardly tactics!\n\nDestroy their cannons and bring down their barriers, so that our valiant Valarjar may face them in the true spirit of battle! When the dust of battle clears, the corpses of demons shall litter the ground... and the Valarjar will stand triumphant!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "" }
WordHunterWoW_QuestEN[45036] = { title = "Asgrim the Dreadkiller", description = "The spirit of one of our most honored warriors has disappeared from the Halls of Valor.\n\nAsgrim the Dreadkiller was a great warlord and king. For centuries, his spirit has dwelled in its rightful place within the Halls of Valor... until recently.\n\nCountless years ago, the Dreadkiller's bones were laid to rest not far from here by his warband. We will seek our answers there.\n\nSound Odyn's Horn upon the burial ground and summon his spirit before us.", objectives = "Sound Odyn's Horn upon the burial mound of Asgrim the Dreadkiller." }
WordHunterWoW_QuestEN[45037] = { title = "The Locket of Eldre'Thalas", description = "<Carefully prying open the locket, you find a portrait of Queen Azshara made entirely of precious stones.>\n\n<Highborne possessions like this are rare - to find one so pristine in the hands of the Legion is deeply troubling.>\n\n<You know the Kirin Tor in Dalaran may be able to tell you more.>", objectives = "Find someone who can tell you more about the Locket of Eldre'Thalas. You suspect that the Kirin Tor in Dalaran are a good place to start." }
WordHunterWoW_QuestEN[45043] = { title = "The Glowing Bloodthistle Petal", description = "<It is exceedingly rare to find bloodthistle outside of Blood Elf lands, especially a petal as fresh as this one.>\n\n<Perhaps the Legion merely claimed it off of a fallen combatant, but that seems far too convenient an explanation.>\n\n<You figure the Kirin Tor in Dalaran would likely be interested in this.>", objectives = "Find someone interested in the Glowing Bloodthistle Petal. You suspect that the Kirin Tor in Dalaran are a good place to start." }
WordHunterWoW_QuestEN[45044] = { title = "Weapon No More", description = "The spear you found certainly has the makings of troll designs from other blacksmithing crafts.\n\nPerhaps somebody at one of the camps here in Un'Goro will know more about it.", objectives = "Bring the Badly Broken Dark Spear to Ko'Zan at Mossy Pile in Un'Goro Crater.\n\nProvided item:", completion = "Ay mon, whatcha got der in your hands?\n\nDat be da Darkspear! Ya found it?!" }
WordHunterWoW_QuestEN[45045] = { title = "The Vial of Ancient Mana", description = "<Upon closer inspection, this vial appears to be filled with moonwell water, well-known for its potent arcane properties.>\n\n<Interestingly, it does not seem to have been tainted by its previous owner. Though that should be comforting, it only broods suspicion as to its origin.>\n\n<Someone among the Kirin Tor in Dalaran would definitely be interested in this.>", objectives = "Find someone interested in the Vial of Ancient Mana. You suspect that the Kirin Tor in Dalaran are a good place to start." }
WordHunterWoW_QuestEN[45046] = { title = "Like the Wind", description = "", objectives = "" }
WordHunterWoW_QuestEN[45047] = { title = "Like the Wind", description = "", objectives = "" }
WordHunterWoW_QuestEN[45048] = { title = "Like the Wind", description = "", objectives = "" }
WordHunterWoW_QuestEN[45049] = { title = "Like the Wind", description = "", objectives = "" }
WordHunterWoW_QuestEN[45050] = { title = "Infiltration Plans", description = "While the text is hard to follow and covered in demonic runes, it appears to be plans to infiltrate Dalaran. The Council of the Six will want to see this.", objectives = "Take the plans to the Council of the Six in Dalaran." }
WordHunterWoW_QuestEN[45051] = { title = "Reverse Blacksmithing", description = "And 'ere I thought I'd never see dis ting again!\n\nAlthough, it don't look like it used to. Aw mon, I'm gonna be in big trouble if I show up wit dis in my hand.\n\nDo ya tink you could help me fix it? I don't have da plans for it, cause you see, da first night I spent here, da creatures came up and stole all me tings.\n\nBut whadd'ya say? Help a bruddah out?\n\nI tink if you can figure out what it's made from, den you can fix it and I can write down da details on how it's made.", objectives = "Deconstruct the Broken Darkspear.", progress = "You're a life saver, bruddah! I'll be forever in your debt after dis.", completion = "Dem's some mighty fine materials dat was made of. No wonda' da boss wants it so bad." }
WordHunterWoW_QuestEN[45052] = { title = "Depleted Nether Crystal", description = "This crystal looks like something used in rituals of dark magic. Given that its energy is depleted, whoever this belongs to must have been successful in whatever ritual they were performing.\n\nThe mages of the Kirin Tor would likely be interested in investigating this.", objectives = "Take the crystal to the Council of Six in Dalaran." }
WordHunterWoW_QuestEN[45053] = { title = "Thief's Instructions", description = "The hastily scrawled note reads:\n\n\"I require the Focusing Iris for one of my spells. Show that you are truly the greatest of my apprentici and fetch it for me.\n\nOh, and make sure you don't leave this note lying around for some adventurer to find!\"\n\nIf someone is looking to steal the Focusing Iris, the Kirin Tor will likely want to know.", objectives = "Take the instructions to the Council of Six in Dalaran." }
WordHunterWoW_QuestEN[45054] = { title = "\"Ancient\" Elven War Orders", description = "These orders look official and bear the Ravencrest sigil, but they are far too new. There is also a hint of fel magic glimmering around the sides.\n\nThe Council of Six would be interested in seeing this.", objectives = "Take the forged orders to the Council of the Six in Dalaran." }
WordHunterWoW_QuestEN[45055] = { title = "A Taste of Their Own Medicine", description = "I been at dis camp for some time now, an' I know for a fact dat dose materials can be found right here in Un'Goro.\n\nTime ta give da creatures here some payback. Take from dem just like dey took from me! At least, you could do dat for me, right bruddah?\n\nI'll just wait here for ya to return wit' all da stuff.", objectives = "Kill creatures around Un'Goro Crater and retrieve 5 Stolen Enchanted Thorium Bars, 5 Mostly Powerful Mojos, 2 Calcified Diemetradon Scales, and 2 Bleached Stegodon Spikes. Bring them to Ko'Zan when you're done.", progress = "Thieving worms gonna get what dey deserve!", completion = "Oh mon, I wish I could'a seen da look on their faces when you pummled dem!\n\nNow dat we have all da materials, we just need to put it together." }
WordHunterWoW_QuestEN[45056] = { title = "Noressa", description = "She is still in there, {name}. Noressa, my wife.\n\nShe is in the Promenade while we wait outside, preparing to strike. Who knows what has happened to her?\n\nPlease, friend, I fear the worst. Tell her there is hope outside.\n\nWe had a small house in the south of the Grand Promenade, by the water gardens. She will probably be there during this madness.", objectives = "Rescue Noressa.", progress = "You must find her!", completion = "I cannot possibly thank you enough. We will be reunited, and I will see we are never separated again." }
WordHunterWoW_QuestEN[45057] = { title = "Saving My Head", description = "Seeing as how you're a blacksmith, I figured it'd be best if ya made da spear. You can use dis forge here to do what ya need to to do.\n\nI'll start writin' down what ya do and den we'll have us both da spear and da recipe!", objectives = "Use the forge near Ko'Zan to recreate the Darkspear.", progress = "Dis is probably da luckiest day of me life.", completion = "Dat's it, mon! Ya did it!\n\nI tink before I head off back to da Isles, I'll be making a few extra copies of dees plans, just in case.\n\nI'll make ya a copy too, in case I be needing your help wit' making another one." }
WordHunterWoW_QuestEN[45058] = { title = "Release the Wardens!", description = "", objectives = "" }
WordHunterWoW_QuestEN[45059] = { title = "Fel Infused Totem Fragment", description = "This appears to be a fragment of a relic or totem from Highmountain. It glows eerily with fel power. This should be brought to the Council of Six in Dalaran at once!", objectives = "Take the totem fragment to the Council of the Six in Dalaran." }
WordHunterWoW_QuestEN[45060] = { title = "Damaged Kirin Tor Insignia", description = "Whether it was lost or stolen, it is odd that a demon would possess an insignia of the Kirin Tor. \n\nThe Council of Six would no doubt be interested in this finding.", objectives = "Take the insignia to the Council of the Six in Dalaran." }
WordHunterWoW_QuestEN[45061] = { title = "Scrolls of the Faldrottin", description = "While it is definitely odd that a demon would carry a scroll of vrykul writings, what is even more interesting are the contents. \n\nThe writings appear to reference a vrykul prophesy of one who would unite the Tideskorn against the Burning Legion. This information should be brought to the Council of Six immediately.", objectives = "Take the scrolls to the Council of the Six in Dalaran." }
WordHunterWoW_QuestEN[45062] = { title = "Resisting Arrest", description = "Your findings do not disappoint, {name}.\n\nMake your way to the soul engine and use our newly acquired weapons to dismantle the power source.", objectives = "Use the withered to dismantle the Power Source inside the Soul Engine at Felsoul Hold.", progress = "There is much to be done.", completion = "Oculeth will be quite pleased with your findings. As you know, he's been working diligently on a new device for the withered." }
WordHunterWoW_QuestEN[45063] = { title = "The Felsoul Experiments", description = "Andaris's control over the withered poses a real threat. If we are to increase the withered's resistance against these effects, we must do so in an environment built from this very magic.\n\nHead for Felsoul Hold at once. When you arrive, I will send withered to aide in your efforts. It is of the utmost importance you do not leave until you are certain the experiments yield the appropriate results.", objectives = "Test the withered's resistance against fel magic at Felsoul Hold.", completion = "The withered seem to be adapting quite well." }
WordHunterWoW_QuestEN[45064] = { title = "Felborne No More", description = "The Felborne have begun to expand their grasp beyond the city's reach. A camp to the east in the Crimson Thicket is of a particular interest to us. Their outpost leader, Valthis Ama'ran, serves Andaris directly.\n\nNow is the time to put our withered training and Oculeth's device to the test. We cannot allow them to advance any further, {name}.\n\nHead for the camp and use the orb to sever the head of the beast. The time has come to begin our advance.", objectives = "Slay 8 Felborne and their leader, Valthis Ama'ran, at the Felborne Outpost in Crimson Thicket.", progress = "Has the threat been removed?", completion = "Our efforts have proven quite successful. I believe we are just about ready to make our stand." }
WordHunterWoW_QuestEN[45065] = { title = "Survey the City", description = "Never a dull moment! Well... perhaps this is not entirely true.\n\nI'm afraid I must ask you once more to return to the city to gather information. But this is not just any information - this is information extraction!\n\nI require specific coordinates to allow me to focus my teleportations with extreme accuracy. It will, unfortunately, take a bit of time to dig through the information once retrieved, but no matter. We have plenty else to do in the meantime.", objectives = "Use the Advanced Telemancy Beacon to survey the Terrace of Order in Suramar City.", progress = "Let's hope this is survey is our last. I grow quite tired watching you run around all day.", completion = "I will begin analyzing this data at once.\n\nFor now, let us turn our attention to more... <Oculeth touches his fingertips together in succession.>\n\n...interesting technological advances." }
WordHunterWoW_QuestEN[45066] = { title = "Experimental Instability", description = "In order to advance our studies I must ask you to recover a few particular items from my long-forgotten chambers.\n\nI assure you it is... mostly safe there, aside from a few unstable elements.\n\nMake your way to my workshop and locate the teleporter. I'll disable its cloaking device when you arrive.", objectives = "Gather the Telemancy Notes and 4 Discarded Orbs from Oculeth's Test Chamber.", progress = "Scavenging going well? Not too dangerous I hope.", completion = "Wonderful! Now the fun begins. You should speak with Thalyssra, I believe she is ready for more... testing." }
WordHunterWoW_QuestEN[45067] = { title = "Telemantic Expanse", description = "Understanding fel magic alone may not be enough, {name}.\n\nSpeak with Oculeth about diversifying our efforts. I hear he's got something... unique planned for us.", objectives = "Speak with Oculeth in Shal'Aran.", completion = "Let us begin." }
WordHunterWoW_QuestEN[45068] = { title = "Barrels o' Fun", description = "", objectives = "" }
WordHunterWoW_QuestEN[45069] = { title = "Barrels o' Fun", description = "", objectives = "" }
WordHunterWoW_QuestEN[45070] = { title = "Barrels o' Fun", description = "", objectives = "" }
WordHunterWoW_QuestEN[45071] = { title = "Barrels o' Fun", description = "", objectives = "" }
WordHunterWoW_QuestEN[45072] = { title = "Barrels o' Fun", description = "", objectives = "" }
WordHunterWoW_QuestEN[45073] = { title = "Loot and Plunder!", description = "I'm bein' honest here matey, I've got me own motives fer bein' here. Last time there was a bit of a debacle. Some drinkin', some gamblin', and a bit too much rum if ye catch me meanin'. Some words were said, some fists were thrown and... honestly it was quite a haze. I'm not the most welcome pirate here after that.\n\nBut they took me stuff! These lyin', dirty ol'... ahem. Could ye just take this torch and... burn their belongin's? I'd be grateful.", objectives = "Burn 8 Blacksail Booty.", completion = "Thank ye, me friend. I feel better knowin' I have been avenged." }
WordHunterWoW_QuestEN[45079] = { title = "The Village of Glenbrook", description = "<The book is a register of the inhabitants of Glenbrook.\n\nAll but a few of the names are crossed out.>", objectives = "Discover the fate of the Glenbrook villagers.", completion = "<Annie looks at you, her eyes hollow and empty. Her clothes are stained with blood, though she seems to be mostly unscathed. She stutters, but her words are unintelligible.>" }
WordHunterWoW_QuestEN[45083] = { title = "Crysa's Flyers", description = "I have obtained some of the most exotic species of carrion bird ever seen on Azeroth. Do you think you can stand up to them?", objectives = "Defeat Crysa in a pet battle.", progress = "The carrion birds are circling you!", completion = "There are feathers everywhere! What a mess." }
WordHunterWoW_QuestEN[45088] = { title = "Trial of Valor: The Lost Army", description = "While Helya's defeat is your primary objective, I require more of your aid. Helya has gained the ability to steal and corrupt the souls of my Valarjar. Her minions hold these souls, corrupting them. I am certain Helya herself hordes the greatest Valarjar souls to herself. You must recover these lost souls, then return them to me.\n\nDo this and I will reward you with blessed guard from the hall's armory.", objectives = "Gather 1000 Valarjar Soul Fragments within the Trial of Valor Raid.", progress = "Bring me the souls of my lost Valarjar. Only then will I reward you with the blessed armor you desire.", completion = "With these souls returned to the Halls of Valor my forces return to their former strength. As promised, the bounty is yours." }
WordHunterWoW_QuestEN[45095] = { title = "Treasure 001 - Crashed Horde Ship", description = "", objectives = "" }
WordHunterWoW_QuestEN[45096] = { title = "Treasure 002 - Fel Cave", description = "", objectives = "" }
WordHunterWoW_QuestEN[45097] = { title = "Treasure 003 - Puddle Cave", description = "", objectives = "" }
WordHunterWoW_QuestEN[45098] = { title = "Orders of Magnitude", description = "We've come across an alarming number of unauthorized orders for war munitions in the past few days, including an advanced long-range targeting device and a large amount of military grade explosives.\n\nThe targeting device in particular was ordered from Mux Manascrambler - he's something of a master of tracking technology.\n\nHead out to his shop in Gadgetzan and see if you can obtain the identity of the buyer. We have to get to the bottom of this before those goods are put to use.", objectives = "" }
WordHunterWoW_QuestEN[45099] = { title = "Hot On The Trail", description = "Targeting device, eh?\n\n<Mux eyes you warily for a moment.>\n\nYeah, I sold one. Never saw the guy's face, though. Real private fella.\n\nA punch card fell out of his pocket as he was leavin', though. I had one of my lackeys tail him out of town in one of my rocket cars to return it.\n\nCustomer service, y'know?\n\nLouse never came back! But hey, if you're lookin' for trouble, they were headed west. That's all I can tell ya.", objectives = "" }
WordHunterWoW_QuestEN[45101] = { title = "Imminent Launch", description = "This is not good.\n\nWe have alarms set up throughout Gnomeregan to detect any unauthorized personnel while we finish de-irradiating it.\n\nJust about every single one was tripped in the past few hours.\n\nBased on your recon, it's a safe assumption that Thermaplugg is down there, and he has enough firepower with him to decimate anywhere he pleases!\n\nThat's where you come in. I'll get you to Gnomeregan. Talk to the High Tinker once you're there and do whatever it takes.\n\nFor Azeroth!", objectives = "" }
WordHunterWoW_QuestEN[45102] = { title = "Begin the Assault", description = "The battle for our world has been hard fought, but with the power of your weapon and the combined forces of Azeroth, we have driven the demon invaders back at every turn.\n\nNow we stand once again upon the Broken Shore, poised to do that which we previously failed to accomplish. Let us not forget those who sacrificed everything to give us this chance. \n\nOur first objective is to take the hill before us, so that we may build a stronghold. Steel yourself, {name}. The assault on the Broken Shore begins now.", objectives = "Begin the assault on the Broken Shore." }
WordHunterWoW_QuestEN[45103] = { title = "We Ride!", description = "The time has come, Deathlord! Our scouts have marked a large amassing of demons not far from here. Lead us to victory, and show these demons the power of undeath!", objectives = "Lead the Four Horsemen in the battle against the Burning Legion.", completion = "Now we have proven the might of the Ebon Blade to the Legion. The ability to take down so many demons without fear of death... that is the power that we hold. We shall see many more demons fall to our blades, and we shall strike them down for Azeroth.\n\nSuffer well." }
WordHunterWoW_QuestEN[45104] = { title = "Your Next Assignment...", description = "Congratulations on making it through the Intern Expo!\nHowever, we're not through with you yet! You still have some \ntime left, so what better use of your time than to make \ntreasures and vignettes on the Broken Shore!", objectives = "Create interesting treasures and vignettes for patch 7.2!Congratulations on making it through the Intern Expo!\nHowever, we're not through with you yet! You still have some \ntime left, so what better use of your time than to make \ntreasures and vignettes on the Broken Shore!" }
WordHunterWoW_QuestEN[45105] = { title = "Lord Raz'gor", description = "The pit lord, Raz'gor, oversees this bulwark. If you wish to break the Broken Shore, Raz'gor must be defeated.\n\nFight you way past the demon blockade and find Lord Raz'gor. Slay the demon and you will strike a heavy blow to the Burning Legion's plans on the Broken Shore.", objectives = "Defeat Lord Raz'gor on the Broken Shore." }
WordHunterWoW_QuestEN[45110] = { title = "Treasure 004 - Fel Tower 001", description = "", objectives = "" }
WordHunterWoW_QuestEN[45111] = { title = "Everyone Loves a Good Fight", description = "The note reads:\n\n\"You shouldn't have blabbed about the brawlers, especially to those champions. Now that you have though, I suppose it's ok that they fight here on occasion, but you better prove yourself a true brawler first!\"", objectives = "Compete in 5 Brawls.", progress = "Compete in the Brawlers Guild to allow your champions to participate.", completion = "Ok, I'll let your champions come and prove themselves in the ring. If they manage to win themselves a fight, come talk to me again and we can see about letting them fight harder brawls." }
WordHunterWoW_QuestEN[45112] = { title = "Signs of Madness", description = "<Whoever this buyer is, they seem to have left in a hurry. Acrid fumes sit heavy in the air around you, and a campfire in the center of the area smolders.>\n\n<Perhaps something here can point you in the right direction?>", objectives = "Search the Deserted Workshop for information that might lead you to the buyer." }
WordHunterWoW_QuestEN[45116] = { title = "Your Next Assignment...", description = "Congratulations on making it through the Intern Expo!\nHowever, we're not through with you yet! You still have some \ntime left, so what better use of your time than to make \ntreasures and vignettes on the Broken Shore!", objectives = "Create interesting treasures and vignettes for patch 7.2!Congratulations on making it through the Intern Expo!\nHowever, we're not through with you yet! You still have some \ntime left, so what better use of your time than to make \ntreasures and vignettes on the Broken Shore!" }
WordHunterWoW_QuestEN[45117] = { title = "TRACKING", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[45118] = { title = "Helya's Horn", description = "{name}, we need to bolster our army by any means necessary. The kvaldir are cursed beyond redemption, but they are fierce warriors and are a resource we should not overlook. \n\nThey are eternally bound to obey Helya even through her death. If we can call them using her voice, they will follow us instead! \n\nWe recovered Helya's Horn from her corpse. Empower it so you can call the kvaldir when we have need of them.", objectives = "Kill enemies in Helheim to empower Helya's Horn.", completion = "Revenge is sweet. The kvaldir will be forced to obey us, now!" }
WordHunterWoW_QuestEN[45119] = { title = "Treasure 005 - Fel Tower 002", description = "", objectives = "" }
WordHunterWoW_QuestEN[45120] = { title = "Treasure 019 - Ruined Temple 002", description = "", objectives = "" }
WordHunterWoW_QuestEN[45121] = { title = "Treasure 006 - Pillar 001", description = "", objectives = "" }
WordHunterWoW_QuestEN[45122] = { title = "Treasure 007 - Back Beach", description = "", objectives = "" }
WordHunterWoW_QuestEN[45123] = { title = "Elemental: The Folly of Levia Laurence", description = "Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good.\n\nLevia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands.\n\nShe was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail.\n\nSpecialization: Elemental Shaman", objectives = "Ask around the city for information on Levia Laurence.", progress = "Have you found any clues to Levia's disappearance?", completion = "So it seems that Levia has fallen under the spell of a succubus' seduction. I fear her time alone as an outcast must have left her vulnerable to such tactics. I cannot help but feel some guilt for her turning down this path.\n\nIn any case, Levia is in great danger. She must be found!" }
WordHunterWoW_QuestEN[45125] = { title = "Dabbling in the Demonic", description = "Levia must have used these runes to aid her ritual. Even if she is as powerful as Modera says, she was a novice in demonic magic, so the runes must have helped stabilize the portal.\n\nI'll need you to find out what runes need to be activated to recreate her ritual. There are several books on runic magic in this room, which she no doubt studied for her ritual.\n\nOnce you have activated the runes, I will complete the spell.", objectives = "Activate the correct three runes to help Rittsyn Flamescowl complete the spell to stabilize the portal.", progress = "Quit fooling around and help me with this ritual!", completion = "I'm pleasantly surprised, <class>. Without your quick thinking, your mage friend would be lost to Agatha.\n\nThe portal is stabilized, and should lead to the mage's location." }
WordHunterWoW_QuestEN[45126] = { title = "Unlikely Seduction", description = "Mo... Modera sent you?\n\nNo...  you must... leave!  Agatha will be back any moment!\n\nSave... yourself...", objectives = "Defeat Agatha.", progress = "Save... yourself...", completion = "Disgusting! I can't believe I let myself fall under the spell of such a creature! \n\nI was such a fool! She made me think she really cared about me. In the end, it seems nothing I thought I knew about Agatha was true!" }
WordHunterWoW_QuestEN[45127] = { title = "Fel-Crossed Lovers", description = "That vile imp mother! If I wasn't so weakened I would dive down that pool and give her a piece of my mind!\n\n<Levia takes a deep breath to regain her composure.>\n\nIt's only a matter of time until Agatha can make use of the power she stole from me. We had best not be here when she does.", objectives = "Return to Archmage Modera in Dalaran.", completion = "So Levia is safe? That is a relief, though I wish we could have reached her sooner. An imp mother is bad enough - I can't imagine what Agatha will be capable of with Levia's power. And who knows what secrets Levia shared while under her thrall?\n\nI'm afraid that this battle may not be over yet.\n\nFor now, we should celebrate whatever victories we can get. Thank you for your assistance, <name>." }
WordHunterWoW_QuestEN[45128] = { title = "A Glorious Reunion", description = "You have done well, Battlelord {name}. Let us return to Skyhold. Odyn will want to hear of your success here.", objectives = "Speak to Aerylia, then report to Odyn.", completion = "You have done all that I hoped, and more, Battlelord <name>." }
WordHunterWoW_QuestEN[45129] = { title = "Appearance", description = "", objectives = "" }
WordHunterWoW_QuestEN[45130] = { title = "Appearance", description = "", objectives = "" }
WordHunterWoW_QuestEN[45131] = { title = "Appearance", description = "", objectives = "" }
WordHunterWoW_QuestEN[45132] = { title = "Before It's Too Late", description = "<If the infamous Sicco Thermaplugg is behind this, the implications are dire indeed.>\n\n<Worse still, he appears to have allied himself with the Legion - who knows what 'gifts' they have given the mad mekgineer.>\n\n<Mux back in Gadgetzan can hopefully help you track down Thermaplugg before it's too late.>", objectives = "" }
WordHunterWoW_QuestEN[45133] = { title = "Signs of Madness", description = "I'm tellin' you, I already told ya everything I know!\n\nIf you want any info on the fella that bought that targeting system, you'll have to follow my assistant out west.\n\nThe buyer's camp is somewhere out that way...\n\nI think.", objectives = "" }
WordHunterWoW_QuestEN[45134] = { title = "The Soul Harvesters", description = "", objectives = "" }
WordHunterWoW_QuestEN[45135] = { title = "Treasure 008 - The Lost Temple", description = "", objectives = "" }
WordHunterWoW_QuestEN[45136] = { title = "Treasure 009 - The Lost Temple 002", description = "", objectives = "" }
WordHunterWoW_QuestEN[45137] = { title = "Treasure 010 - Malgoreth's Chamber", description = "", objectives = "" }
WordHunterWoW_QuestEN[45141] = { title = "Treasure 011 - Vol'jin's Fall", description = "", objectives = "" }
WordHunterWoW_QuestEN[45142] = { title = "Treasure 012 - Behind Tomb of Sargeras", description = "", objectives = "" }
WordHunterWoW_QuestEN[45143] = { title = "Judgment Awaits", description = "Our ongoing offensive within the Broken Shore has drawn the interest of many paladins who wish to fight under your leadership. Some are more worthy than others, but only you can be the judge of that.\n\nThe new recruits are lingering in the camp just outside the chapel, awaiting your judgment.", objectives = "Use Highlord's Judgment to determine the worth of Silver Hand Recruits.", progress = "Not all are worthy of joining the Silver Hand.", completion = "Your judgment is firm and fair, Highlord.\n\nThese new recruits will learn much under your command.\n\nThough I am beginning to wonder, if my worthiness was tested, would I be found lacking?" }
WordHunterWoW_QuestEN[45144] = { title = "Treasure 013 - Ruined Temple", description = "", objectives = "" }
WordHunterWoW_QuestEN[45145] = { title = "Moonfang Family Relics", description = "As promised, here is the crescent key that will open my family's lockboxes, though nothing of value remains.\n\nI trust whatever you find you'll deliver to Delas? Our ancestor's things, whatever their worth, should remain in our family.", objectives = "Recover Moonfang family relics from within Shadowfen.", completion = "I know the name Nerus. He's a distant relative of mine, but why would he hold on to fel trinkets?\n\nThe answer to that question might be found within this scroll, but it appears to be blank." }
WordHunterWoW_QuestEN[45146] = { title = "Runic Reading", description = "There is something curious about this scroll. It appears to be an empty page to the untrained eye, but I can see a shimmer of runes appear briefly when I hold it up to the light.\n\nAs with most demonic runes, I will need fel blood to undo the magic that's been used to conceal whatever message is within this scroll.", objectives = "Collect 10 Fel Blood from demons throughout the Broken Isles.", progress = "I will need to submerge the scroll in demon blood in order for the runes to reveal themselves.", completion = "It should only take a moment for the runes to appear once I apply the purified blood." }
WordHunterWoW_QuestEN[45147] = { title = "Felstone Destruction", description = "<Delas' mouth drops open as the scroll falls from her hands and onto the floor.>\n\nThis cannot be... the runes... they detail a pact between the Burning Legion and my ancestors. A dark deal that would grant my ancestors protection from demons in this life, but in return, their spirits would belong to the Legion.\n\nThis fel pendant is an embodiment of the pact, and cannot be removed once worn.\n\nQuickly, {name}. You must use your artifact to destroy that cursed piece of jewelry!", objectives = "Destroy the Felstone Pendant.", completion = "If you were strong enough to destroy the pendant that bound my spirit to the Burning Legion, then there might be hope for my ancestors." }
WordHunterWoW_QuestEN[45148] = { title = "Oath Breaker", description = "Many years ago I made a pact with a man I thought not to be unlike myself. His promise of protection seemed too good to be true, but it was a deal I was desperate to make.\n\nIt wasn't until I had signed in blood that the dreadlord Zorak revealed himself.\n\nAs long as he lives, my ancestors will remain bound to the Burning Legion, allowing our enemies to amass an army of unwilling soldiers.\n\nHead to the Broken Shore and slay Oathbinder Zorak. His death will break the hold he has over my ancestors.", objectives = "Head to the Broken Shore and slay Oathbinder Zorak.", completion = "With Zorak dead, my ancestor's spirits can finally be free of their curse." }
WordHunterWoW_QuestEN[45149] = { title = "Ending the Crescent Curse", description = "We must do whatever we can to break the curse that befalls my ancestors. \n\nThe Burning Legion have set up camp within the ruins that house our dead, ready to make good on the dreadful pact that was drafted so long ago.\n\nEach of my ancestor's is burdened with a pendant that binds them to their demonic overlords. It cannot be removed, but as you have shown, with enough power it can be destroyed. \n\nEnd the curse that plagues my ancestors and set their spirits free!", objectives = "Free Felbound Spirits in Crescent Ruins by destroying their fel pendants.", progress = "You are the only one powerful enough to destroy the fel pendants that bind my ancestor's spirits to the Legion.", completion = "What you have done for my family will never be forgotten.\n\nThe spirits of the Moonfang family will forever be in your debt." }
WordHunterWoW_QuestEN[45150] = { title = "Treasure 013 - Fel Tower 003", description = "", objectives = "" }
WordHunterWoW_QuestEN[45151] = { title = "Treasure 015 - Ritual Altar", description = "", objectives = "" }
WordHunterWoW_QuestEN[45152] = { title = "Treasure 036 - Tomb Statue Book", description = "", objectives = "" }
WordHunterWoW_QuestEN[45153] = { title = "Treasure 016 - Undersea Naval Battle", description = "", objectives = "" }
WordHunterWoW_QuestEN[45154] = { title = "Treasure 017 - Egg Cave", description = "", objectives = "" }
WordHunterWoW_QuestEN[45158] = { title = "Treasure 018 - Crashed Alliance Sea Ship", description = "", objectives = "" }
WordHunterWoW_QuestEN[45159] = { title = "Cubic Conundrum", description = "<You find a mysterious cube. Its design is unfamiliar, but unmistakably ancient. \n\nThe cube's surface is inlaid with magical runes. Though inert, its properties may be worth investigating.\n\nPerhaps if you show it to Dariness the Learned in Dalaran, she could tell you more about it.>", objectives = "Take the Mysterious Cube to Dariness the Learned in Dalaran.\n\nProvided item:", completion = "<Dariness peers at the artifact you hand her.>\n\nA most interesting design! It reminds me of an ancient curio I read about long ago while still in training. I doubt it could be that though. Such a device has never been found.\n\nHmm, I wonder if it still works. Only one way to find out..." }
WordHunterWoW_QuestEN[45160] = { title = "Cubic Currents", description = "To determine this cube's purpose, we need to power it up. Hmm, I have an idea...\n\nThe Nightborne covet a substance you are no doubt familiar with called ancient mana. Should be just the thing for a relic this old. Gather a sufficient quantity and we'll attempt to get it working.\n\nBe careful in Suramar! It would be a shame if this curious cube were lost and became a memory once more.", objectives = "Obtain 300 Ancient Mana from Suramar", completion = "I trust you obtained all the ancient mana we need to infuse the cube?" }
WordHunterWoW_QuestEN[45161] = { title = "7.1.5 Special - 850 - Special - Brawlers - Fight 01 - Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[45162] = { title = "We Brought the Hammer", description = "Your champions found success in the brawl against the Warhammer Council. Bring this \"token\" to the Brawler's Guild as proof.", objectives = "Go to the Brawler's Guild.", completion = "Hey not bad, they beat the Council huh? Sure, they can advance to the next level." }
WordHunterWoW_QuestEN[45163] = { title = "Cleaning Up", description = "Your champions return successful. They tell a grand tale of how they really cleaned up against Bill the Janitor.", objectives = "Return the Broken Broom Handle to the Brawler's Guild.", completion = "You think you guys are tough, beating up a janitor and all? Well ok, I suppose I'll get you into the next fight." }
WordHunterWoW_QuestEN[45164] = { title = "7.1.5 Special - 850 - Special - Brawlers - Fight 02 - Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[45165] = { title = "7.1.5 Class Hall - Brawlers - Fight 01 - Overmax Reward Credit - Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[45166] = { title = "Treasure 020 - Murloc Beach Hut", description = "", objectives = "" }
WordHunterWoW_QuestEN[45167] = { title = "REUSE ME", description = "{name}, we will need to bolster our army by any means necessary to have any hope of driving back the legion. The kvaldir are cursed beyond redemption, but they are fierce warriors and are a resource we should not overlook. They are bound to obey whomever posesses Helya's Horn. You must obtain it. \n\nHer so-called helarjar were tasked with guarding it. You will have to take it from them.", objectives = "Find Helya's Horn." }
WordHunterWoW_QuestEN[45168] = { title = "Treasure 021 - Above Puddle Cave", description = "", objectives = "" }
WordHunterWoW_QuestEN[45169] = { title = "Treasure 022 - Hub Cliff", description = "", objectives = "" }
WordHunterWoW_QuestEN[45170] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[45171] = { title = "7.1 Class Hall - Special - PVP - PVP Intro Mission - Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[45172] = { title = "To Battle!", description = "Your champions have returned from exploring the battleground with a report detailing wild adventures and death-defying feats of strength and honor. In these ever shifting battles of conquest, more assistance is always required.\n\nWill you answer the call?", objectives = "Join and win in any battleground.", progress = "How are you faring in the battleground?", completion = "Well done!  Battlegrounds are certainly no place for the weak.\n\nWith your success, your champions will now look for more opportunities for you to prove your worth." }
WordHunterWoW_QuestEN[45173] = { title = "Desperate Times", description = "The conflict continues. As always, your assistance is needed in the great battlegrounds. Join the fray, defeat your enemies, and win glory for your faction.", objectives = "Join and win in any battleground.", completion = "Well done!" }
WordHunterWoW_QuestEN[45174] = { title = "The Hunt for Illidan Stormrage", description = "Allari the Souleater, an oracle of the Illidari, has been on the hunt for Illidan's soul for quite some time. She now believes that she has discovered its location and requires your assistance in its recovery.\n\nFind Allari at Illidari Stand in Azsuna and aid her in any way possible.\n\nIf Sargeras truly plans to use Illidan's body as a vessel for his own return then returning Illidan's soul to his body is integral in preventing the dark titan from returning to our world!", objectives = "Seek out Allari the Souleater at Illidari Stand in Azsuna.", completion = "The naaru heard my call? Interesting...\n\nVery well, let's get to work. We've found Illidan's soul - finally - and it's not where we expected it to be held." }
WordHunterWoW_QuestEN[45175] = { title = "Soul Prism of the Illidari", description = "Alas, I will not burden you with the location of the master's soul just yet, {name}. First we must craft a soul prism powerful enough to hold the master's boundless chaotic energies.\n\nTo do this I require lingering soul fragments from powerful beings found across this world. Bring me enough and I will craft a soul prism capable of holding the soul of the master - at least long enough to transfer into the naaru.", objectives = "Claim 5 Lingering Soul Fragments from the final bosses of Legion dungeons.\n\nHigher difficulty dungeons provide a greater chance and quantity of Lingering Soul Fragments.", completion = "The Soul Prism of the Illidari is ready for use.\n\nIllidan's soul was plucked from the Nether - stolen - and taken to the underworld. A place known as Helheim." }
WordHunterWoW_QuestEN[45176] = { title = "Trial of Valor: The Once and Future Lord of Shadows", description = "While tracking the master's physical body proved challenging, we were able to locate it in the Nighthold of Suramar. Our intelligence reports that Gul'dan is making final preparations to the Nightwell in order to use its power to usher the soul of Sargeras into Illidan's body.\n\nThe only way to stop that from happening is to put Illidan's own immortal soul back.\n\nTake the Soul Prism of the Illidari and venture to Helheim. Defeat Helya and use the prism on Illidan's soul! Return it to Light's Heart.", objectives = "Defeat Helya in the Trials of Valor raid and then use the Soul Prism of the Illidari to claim Illidan's Soul.", completion = "<Light's Heart illuminates brightly and seemingly consumes the Soul Prism.>" }
WordHunterWoW_QuestEN[45177] = { title = "The Nighthold", description = "Illidan's soul rests safely within Light's Heart. Take this vessel and deliver it to Khadgar with the following instructions:\n\nWhen Gul'dan attempts to tear the sky asunder and bring the dark titan into our world, call forth the power of this vessel and release Illidan's soul into his body.\n\nGo now, {name}. We do not have much time. The dark ritual will begin soon.", objectives = "Deliver Light's Heart to Khadgar at the Violet Citadel in Dalaran.", completion = "I... I will do my best, Battlelord. You will - of course - have to do the hard work and lead the assault on the Nighthold!\n\nFOR AZEROTH!" }
WordHunterWoW_QuestEN[45178] = { title = "Contagion Containment", description = "", objectives = "" }
WordHunterWoW_QuestEN[45179] = { title = "Win the Crowd", description = "The letter invites you to fight in one of the greatest events in the history of Azeroth. The grand arena battles, where fighters win glory and honor, and everyone will remember their names. Or at least until the next season.", objectives = "Fight and win in the arena.", completion = "Congratulations are in order I hear?" }
WordHunterWoW_QuestEN[45180] = { title = "An Island of War", description = "Your champions return weary and wounded. They bear a banner which, when placed in your hands, gives you a sense of foreboding, but also a surge of battle lust. They report to you of an island named Ashran, where heroes are constantly waging a war. The tides push back and forth, each side feinting and thrusting, always trying to gain the upper hand.\n\nAshran needs your help, will you answer the call?", objectives = "Complete the quests in Ashran.", completion = "Ashran is no place for the faint of heart. You did well." }
WordHunterWoW_QuestEN[45181] = { title = "7.1 Class Hall - Special - PVP - PVP Repeated - Battleground - Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[45182] = { title = "Frost: The Twisted Twin", description = "I have a request from an old friend, Karam Magespear, to help find his brother, Raest. Karam fears that Raest is dealing with dark powers, and wishes to stop him.\n\nOriginally Raest trained with the Kirin Tor, but such were his aspirations of power that he turned to the forbidden art of Necromancy. He was discovered and expelled from our order.\n\nFind Karam in the Legerdemain Lounge and see if you can lend a hand.\n\nSpecialization: Frost Mage", objectives = "Meet with Karam Magespear at the Legerdemain Lounge in Dalaran.", completion = "You come from the Kirin Tor? So you'll help me find my brother?" }
WordHunterWoW_QuestEN[45183] = { title = "7.1 Class Hall - Special - PVP - PVP Repeated - Ashran - Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[45184] = { title = "7.1 Class Hall - Special - PVP - PVP Repeated - Arena - Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[45185] = { title = "Message from the Shadows", description = "I know my brother has been misguided in the past, but I fear that he may have fallen in with an unthinkable evil. He recently began meeting in secret with a dark cult, hidden amongst the people of Dalaran.\n\nI travelled here to try to convince him of the error in his ways, but he would not be shaken from his course. Now, he has disappeared. \n\nWhen I last saw him, Raest was staying in a room upstairs. I was unable to find any clues there, but you might fare better.", objectives = "Search the upper room in the Legerdemain Lounge for a clue to Raest Magespear's location.", progress = "Have you found something?", completion = "A letter? From one of the cultists? \n\nThat could be the lead we need!" }
WordHunterWoW_QuestEN[45186] = { title = "Treasure 023 - Sargeras Tower 001", description = "", objectives = "" }
WordHunterWoW_QuestEN[45187] = { title = "Secrets in the Underbelly", description = "So my brother has gone off to perform some ritual with these cultists? That explains why he left, but still not to where...\n\nWait! This letter mentions some of these \"Nethersworn\" cultists seeking reagents in the Underbelly. Perhaps we still may be able to find them if we hurry!", objectives = "Question the Underbelly Lowlifes in the Underbelly to find more information about Raest Magespear's location.", progress = "Any leads, <name>?", completion = "Well, this definitely says... something." }
WordHunterWoW_QuestEN[45188] = { title = "The Wisdom of the Council", description = "I'm sorry, {name}, but I can't make heads nor tails of this. Riddles have never exactly been my strength.\n\nWe should take this cultist's writings to the archmage. Perhaps he could shed some light on this.", objectives = "Bring the Nethersworn Manifesto to Archmage Karlain in the Violet Citadel in Dalaran.", completion = "What's this, a cultist's manifesto?  \n\nSo Raest has really gone down a dark path, hasn't he?" }
WordHunterWoW_QuestEN[45189] = { title = "Treasure 024 - Fel River Rock", description = "", objectives = "" }
WordHunterWoW_QuestEN[45190] = { title = "Where it's Thinnest", description = "Though I have never heard of this \"Nethersworn\" cult, what this manifesto speaks of can't be good.\n\nI do have a theory, however. The writing speaks of \"the place its skin is thinnest.\" I think they might be referring to the place where the veil between Azeroth and the Twisting Nether is weakest - the Tomb of Sargeras. \n\nWith our forces having established a foothold at the Broken Shore, this would be an opportune time for Raest and his cultist allies to reach the tomb. I would suggest you stop them.", objectives = "Meet Karam Magespear at Felbreach Hollow in the Broken Shore.", completion = "My brother is here!" }
WordHunterWoW_QuestEN[45191] = { title = "Treasure 025 - Night Elf Ruins 001", description = "", objectives = "" }
WordHunterWoW_QuestEN[45192] = { title = "Runes of Rending", description = "My brother and his cultists are engaged in some kind of ritual at the far end of the cave. I tried to intervene, but my brother has left magical wards to block the way.\n\nIf you can find a way past them, we may be able to stop him in time!", objectives = "Bypass the wards in Felbreach Hollow and confront Raest Magespear.", progress = "We must not hesitate!", completion = "We're too late, the rift has closed!\n\nWe'll have to find another way to get to him." }
WordHunterWoW_QuestEN[45193] = { title = "One Step Behind", description = "It looks like Raest is out of our reach, but at least his cultists should prove less of a threat.\n\nWe should return to the Kirin Tor. They should be able to help us plan our next move.", objectives = "Return to Khadgar in the Violet Citadel in Dalaran.", completion = "So Raest escaped? This is unfortunate. \n\nStill, I will rest easier knowing the Nethersworn cultists will no longer skulk in the streets of Dalaran. I thank you for that.\n\nThe Kirin Tor will set out at once to figure out how we can reach Raest in the Twisting Nether. I will send for you when we find a way to reach him." }
