WordHunterWoW_QuestEN[45207] = { title = "The Nightborne Apprentice", description = "I would be happy to introduce you to my new apprentice if you do not mind traveling a bit. She is currently in the field keeping an eye on an enclave of Felborne resistance fighters who have sworn loyalty to the Legion. \n\nAs the first nightborne to join the Tirisgarde, I am sure she is eager to prove her skills!", objectives = "Meet Arcanist Ryanna in the Crimson Thicket.", completion = "I've heard so much about you, Archmage <name>. It is a pleasure to finally meet you!" }
WordHunterWoW_QuestEN[45208] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[45209] = { title = "Those Scrying Eyes", description = "Until recently, Ly'leth was sending magical messages to us regularly from within the Nighthold. She took care to hide these messages - only the most vigilant scryers could have detected them.\n\nThey could not be within the palace... too much interference from the Nightwell...\n\nOf course! The Terrace of Enlightenment! The Duskwatch must have set up a listening post there.\n\nCheck the scrying orbs for traces of Ly'leth's messages. We must learn what she was trying to tell us!", objectives = "Inspect 4 Duskwatch Scrying Orbs in the Terrace of Enlightenment.", completion = "So they did intercept her messages! I hope Ly'leth is okay...\n\nWe must investigate this breach she spoke of immediately!" }
