WordHunterWoW_QuestEN[45238] = { title = "Return to Karazhan: Cubic Cynosure", description = "Drat! The ancient mana doesn't seem to be working. I need to think the problem through, focus and...\n\nWait, that's it! Focus! We need to focus the energy of the ancient mana to activate the cube.\n\nI've heard tell of a mana wyrm in Karazhan with the means to focus its powers. Might be just what we need!\n\nWatch out, though. My sources tell me this wyrm is humongous!", objectives = "Obtain a Mana Focus from the Mana Devourer within Karazhan", completion = "You've done it! Was the wyrm truly gargantuan? Oh, nevermind, size is relative...\n\nLet us get this focus into the cube and see what it does!" }
WordHunterWoW_QuestEN[45239] = { title = "Cubic Coalescing", description = "Success! The cube's magic has been restored! I'm excited to see what it does!\n\nSince you did all the legwork, you should have the honor of activating it. Care to give it a try?", objectives = "Activate the Mysterious Cube", completion = "<Something about the power coursing through the cube urges you to take it into your possession.>" }
WordHunterWoW_QuestEN[45240] = { title = "Making Preparations", description = "Deathlord, we have uncovered an heirloom of great significance and power. Rimefang's harness has appeared in Icecrown Citadel. We must obtain it, rather than let it fall into the hands of others.\n\nI assume you'd like to retrieve the harness personally? We've sent one of our own, Minerva Ravensorrow, ahead to scout. You've met her before, yes? She has impressed us greatly, and we believe she can become quite powerful under your tutelage.\n\nI will open a death gate for you. It is best you meet her there.", objectives = "Take the Death Gate near Highlord Darion Mograine, then meet Minerva Ravensorrow.", completion = "Deathlord! The vrykul have the harness!" }
WordHunterWoW_QuestEN[45243] = { title = "On Daumyr's Wings", description = "The time is nigh, {name}. With these new dragons in our army, we are prepared for our assault on the Broken Shore. A large detachment of demons have appeared near one of our camps, and there are far too many of them for any of our allies to overcome.\n\nWho better to defeat these demons than those without fear of death? Those with quite the large secret weapon?\n\nTake Daumyr. We will meet you there.", objectives = "Ride Daumyr to the Broken Shore.", completion = "Let's show the Legion true power." }
WordHunterWoW_QuestEN[45244] = { title = "Treasure 031 - Cave Underneath Horde Ship", description = "", objectives = "" }
WordHunterWoW_QuestEN[45246] = { title = "Treasure 032 - Fel River Nook", description = "", objectives = "" }
WordHunterWoW_QuestEN[45248] = { title = "Treasure 033 - Fel Crystal Tower 000", description = "", objectives = "" }
WordHunterWoW_QuestEN[45249] = { title = "Treasure 034 - Beach Pole", description = "", objectives = "" }
WordHunterWoW_QuestEN[45250] = { title = "Treasure 035 - Dead Tree", description = "", objectives = "" }
WordHunterWoW_QuestEN[45251] = { title = "Redundancy", description = "A construct progenitor? What a creative solution to our problem!\n\nWe probably could channel Kathra'natir's power without releasing him now, but I want to add another layer of protection before we try, just in case. I will not have anyone accusing me of subterfuge!\n\nMeet me on the Broken Shore when you are ready.", objectives = "Meet Aethas on the Broken Shore.", completion = "Let us get to work, shall we?" }
WordHunterWoW_QuestEN[45252] = { title = "Treasure 037 - Above Lost Temple", description = "", objectives = "" }
WordHunterWoW_QuestEN[45253] = { title = "Treasure 038 - Above Felfire Pass", description = "", objectives = "" }
WordHunterWoW_QuestEN[45254] = { title = "Treasure 039 - Felfire Pass Chain Cage", description = "", objectives = "" }
WordHunterWoW_QuestEN[45255] = { title = "Treasure 040 - Fel Waterfall", description = "", objectives = "" }
WordHunterWoW_QuestEN[45256] = { title = "Treasure 041 - Spike Overlook", description = "", objectives = "" }
WordHunterWoW_QuestEN[45257] = { title = "Treasure 042 - Underwater 003", description = "", objectives = "" }
WordHunterWoW_QuestEN[45258] = { title = "Treasure 043 - Underwater 004", description = "", objectives = "" }
WordHunterWoW_QuestEN[45259] = { title = "Treasure 044 - Crashed Alliance Gunship", description = "", objectives = "" }
WordHunterWoW_QuestEN[45260] = { title = "One Day at a Time", description = "Thank you for coming, outlander. It is good to see you again.\n\nI have a situation in the city that needs your attention, but first... \n\nLet us talk of hope.\n\n<Thalyssra gestures toward the arcan'dor.>\n\nThe fruit of the arcan'dor can truly free my people from the Nightwell. However, it only grows so fast. It will take time to distribute this cure.\n\nI think it only right that you help me pass out the fruit as it is ready. Please take this, and give it to anyone.", objectives = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", progress = "In time, all of the shal'dorei will be free.", completion = "I will ask this of you again, as more fruit is ready.\n\nFor now, we have some disturbing news to discuss." }
WordHunterWoW_QuestEN[45261] = { title = "Continuing the Cure", description = "Given the events at the Waning Crescent, the refugees here are more eager than ever to receive the gift of the arcan'dor and be free of the Nightwell forever. \n\nFortunately, the tree has borne more fruit. Again, I ask that you honor us by giving this fruit to anyone here in Shal'Aran.\n\nWhen you are finished, we shall discuss further developments within the city. Silgryn reports that Arluelle has proven a fine student, and the two are making progress in evacuating citizens.", objectives = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", progress = "No matter what crises come up, we must stay the course and free my people from their addiction.\n\nWe take it one day at a time.", completion = "Good, now to set our attention to those still suffering within the city." }
WordHunterWoW_QuestEN[45262] = { title = "A Message From Ly'leth", description = "The arcan'dor bears fruit once again. Just in time, too - Ly'leth has sent us a message, and it seems she may have a lead on Vanthir. He is long overdue for this gift, assuming we manage to find him.\n\nGive a fruit to another citizen here in Shal'Aran while I finish decrypting Ly'leth's message.", objectives = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", completion = "There. I certainly hope Ly'leth has good news..." }
WordHunterWoW_QuestEN[45263] = { title = "Eating Before the Meeting", description = "Having Vanthir around has done much to lift the spirits of the people here. I dare say some have begun to relish their newfound freedom, even if they miss their beloved city.\n\nI will not rest until I can give it back to them.\n\nYou and I have an important meeting to attend. Before we go, let us distribute more of the arcan'dor's fruit. \n\nI want people to know that although I must leave for now, I have not abandoned them.", objectives = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", completion = "Very well, let us go." }
WordHunterWoW_QuestEN[45264] = { title = "Treasure 045 - South Peak", description = "", objectives = "" }
WordHunterWoW_QuestEN[45265] = { title = "Feeding the Rebellion", description = "More nightborne flee Suramar every day to join our cause.\n\nOur ranks are swelling, and with the aid of great heroes like yourself and the armies of the Horde and Alliance, our chances have never been better.\n\nHelp me hand out more fruit of the arcan'dor - each one is a life free from slavish dependence on the Nightwell!\n\nAfterwards, we shall speak on how best to assist our new allies in their siege.", objectives = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", completion = "Good. Now let us see to business at the warfront." }
WordHunterWoW_QuestEN[45266] = { title = "A United Front", description = "Our rebel fighters have been armed and morale is high - even the Alliance and Horde elves have ceased their squabbling.\n\nWe are nearly ready to march on the city.\n\nHand out this week's fruit, and then we can begin preparations.", objectives = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", completion = "The time has come." }
WordHunterWoW_QuestEN[45267] = { title = "Before the Siege", description = "So many years of my life spent studying within the Nighthold... \n\nNever had I considered that I would one day have to fight my way back in.\n\nTime is short. The battle will be upon us soon. \n\nPlease, continue our tradition and feed another refugee the fruit of the arcan'dor.", objectives = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", completion = "Just in time. We are ready to begin." }
WordHunterWoW_QuestEN[45268] = { title = "The Advisor and the Arcanist", description = "This new First Arcanist appointed by Elisande. This... Andaris. If she is as dangerous as I have heard, then Ly'leth may well be lost.\n\nI am sorry, I should not entertain such thoughts. It is just that we have received a troubling message.\n\nHelp me distribute the latest batch of the arcan'dor fruit, then we will discuss the message.", objectives = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", progress = "Are you ready?", completion = "I am glad we can still cure my people, but... I have troubling news." }
WordHunterWoW_QuestEN[45269] = { title = "A Taste of Freedom", description = "We are as ready as we will ever be. Once we put Valtrois' plan into action, we can attack the Sanctum of Order and put an end to Andaris. She will never expect us to have trained our withered against fel magic, and her hubris will be her downfall.\n\nCome, let us feed the people one last time.", objectives = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", progress = "Even if our failure means their doom, they deserve a taste of freedom, no matter how fleeting.", completion = "Very well. Let us begin." }
WordHunterWoW_QuestEN[45270] = { title = "Treasure 046 - Bundle of Cages 000", description = "", objectives = "" }
WordHunterWoW_QuestEN[45271] = { title = "Insurrection", description = "First Arcanist Thalyssra has received dark tidings regarding the Nightfallen rebellion and requires your assistance.\n\nJourney to Shal'Aran in Suramar and meet with her.", objectives = "Speak with First Arcanist Thalyssra in Shal'Aran.", completion = "Welcome hero. Your arrival could not have been better timed." }
WordHunterWoW_QuestEN[45272] = { title = "Insurrection: Missing Persons", description = "First Arcanist Thalyssra has requested your aid in searching for her missing people.\n\nShe has a lead from a very unexpected ally.\n\nMeet with her at Shal'Aran in Suramar.", objectives = "Speak with First Arcanist Thalyssra in Shal'Aran.", completion = "Welcome hero. Your arrival could not have been better timed." }
WordHunterWoW_QuestEN[45276] = { title = "Treasure 047 - Webbed Path", description = "", objectives = "" }
WordHunterWoW_QuestEN[45277] = { title = "Insurrection: Waxing Crescent", description = "First Arcanist Thalyssra has sent word: there has been communication from Ly'leth. Your help is needed.\n\nJourney to Shal'Aran in Suramar and lend what aid you can.", objectives = "Speak with First Arcanist Thalyssra in Shal'Aran.", completion = "You are going to want to hear this." }
WordHunterWoW_QuestEN[45278] = { title = "Insurrection: An Elven Problem", description = "The Alliance and Horde have arrived in Suramar. First Arcanist Thalyssra needs your help in providing an introduction.\n\nMeet with Thalyssra in Shal'Aran.", objectives = "Meet with First Arcanist Thalyssra in Shal'Aran.", completion = "It would seem the elves have returned to Suramar." }
WordHunterWoW_QuestEN[45279] = { title = "Treasure 048 - Western Island Tree", description = "", objectives = "" }
WordHunterWoW_QuestEN[45280] = { title = "Insurrection: Crafting War", description = "Refugees are flooding in to Shal'Aran, and many are willing to fight for Thalyssra's rebel army.\n\nThey need weapons, training and help from anyone who can provide it.\n\nGo to Shal'Aran and lend your assistance.", objectives = "Meet with First Arcanist Thalyssra in Shal'Aran.", completion = "This is an unexpected problem, but we have more soldiers than food or weapons." }
WordHunterWoW_QuestEN[45281] = { title = "Insurrection: March on Suramar", description = "First Arcanist Thalyssra has sent word: the time has come to launch our assault on Suramar. The elven armies of the Horde, Alliance, Kirin Tor and Nightfallen are assembled.\n\nThey only await your arrival to begin their assault.\n\nReport to Shal'Aran and meet with First Arcanist Thalyssra and prepare for battle.", objectives = "Meet with First Arcanist Thalyssra in Shal'Aran.", completion = "The time for our attack has come. It is time for us to take back Suramar from Elisande and her demonic allies!" }
WordHunterWoW_QuestEN[45282] = { title = "Insurrection: Elisande's Retort", description = "The combined forces of the elves stand ready to begin their siege on the gates of the Nighthold.\n\nReport to First Arcanist Thalyssra in Shal'Aran to begin the siege.", objectives = "Meet with First Arcanist Thalyssra in Shal'Aran.", completion = "The time for our attack has come. It is time for us to take back Suramar from Elisande and her demonic allies!" }
WordHunterWoW_QuestEN[45283] = { title = "Treasure 049 - Behind Purple Ritual", description = "", objectives = "" }
WordHunterWoW_QuestEN[45284] = { title = "Treasure 050 - Spikes Over Green", description = "", objectives = "" }
WordHunterWoW_QuestEN[45285] = { title = "Insurrection: As Strong As Our Will", description = "In the wake of Elisande's attack, the need is stronger than ever to add to the ranks of the Nightfallen rebellion.\n\nPlans are in motion that may help with this in an unconventional way.\n\nReport to First Arcanist Thalyssra in Shal'Aran for more details.", objectives = "Meet with First Arcanist Thalyssra in Shal'Aran.", completion = "Thank you for coming. Your skills will prove to be invaluable for this next part of our plan." }
WordHunterWoW_QuestEN[45286] = { title = "Treasure 051 - Death Knight Overhang", description = "", objectives = "" }
WordHunterWoW_QuestEN[45287] = { title = "Insurrection: Breaking the Nighthold", description = "First Arcanist Thalyssra sends word that her forces are ready. It is time for you to lead the attack against the Nighthold.\n\nReport to Shal'Aran in Suramar for details.", objectives = "Meet with First Arcanist Thalyssra in Shal'Aran.", completion = "The time for our attack has come. It is time for us to take back Suramar from Elisande and her demonic allies!" }
