WordHunterWoW_QuestEN[45289] = { title = "Treasure 053 - Underneath Tomb Bridge", description = "", objectives = "" }
WordHunterWoW_QuestEN[45291] = { title = "Return to Karazhan: Book Wyrms", description = "My incorporeal condition has allowed me to enter the tower safely for the first time. I must say, it's a bit of a shambles in there!\n\nI could use some help tackling my cleaning checklist. We should start with the library. All those musty tomes are bound to attract mana wyrms!\n\nPlease shelve any books that have fallen to the floor, or worse, taken flight. And if you find mana wyrms nibbling at the pages... step on them!", objectives = "Clean up the Karazhan Library.", progress = "How did it go?", completion = "You were HOW small? Gracious! That must have complicated things.\n\nIt looks like there are more books on the floor than when we started. It's as if the books keep jumping off the shelves or something...\n\nThis is going to be harder than I thought!" }
WordHunterWoW_QuestEN[45292] = { title = "Return to Karazhan: Rebooting the Cleaner", description = "The Guardian Medivh created the Curator to watch over Karazhan, but I fear the unit is behaving erratically. Prolonged periods of operation may have caused a malfunction.\n\nPlease go up to the Menagerie and disable the Curator. Also, search the area for a box of spare motivator crystals and return to me.\n\nEven with my basic knowledge I should be able to replace its motivator, and we can enlist the Curator's help in cleaning up the tower.", objectives = "Disable the Curator and find the Box of Spare Motivator Crystals.", progress = "Did you find the box of spares?", completion = "The box is empty? Drat!\n\nI may be a mage, but I'll never be able to copy Medivh's motivator crystal enchantment!" }
WordHunterWoW_QuestEN[45293] = { title = "Return to Karazhan: New Shoes", description = "Thus far my Karazhan cleanup project hasn't exactly been a rousing success. Time to try something new.\n\nNew, as in new shoes... horseshoes, that is! A box of horseshoes was left outside the tower. It's a problem finding a delivery person willing to set foot inside... mortality rates being what they are.\n\nIf you would, grab the crate and take it to Koren in the stables. Just be careful passing Attumen. The huntsman doesn't take kindly to outsiders.", objectives = "Deliver the Box of 'New' Horseshoes to Koren the Blacksmith in Karazhan.", progress = "How did it go?", completion = "Oh dear. My fault entirely!\n\nI should have ensured the horseshoes were in good shape before having you deliver them.\n\nThe humidity out here is a real killer!" }
WordHunterWoW_QuestEN[45294] = { title = "Return to Karazhan: High Stress Hiatus", description = "The new plays in the opera house have been well received by everyone... except cast members of the older shows. Egos are bruised and tensions are running high!\n\nRomulo and Julianne are ready to poison each other.\n\nTinhead is rusting with tears over his lack of adoration.\n\nLittle Red's cape was stolen by a disgruntled understudy, who ran off to play chess of all things.\n\nActors, am I right? We need them ready to perform in case the audience demands a revival. Please, help me calm their nerves!", objectives = "Help Darius soothe the old casts egos by finding a Positive Review amongst the audience members to simmer tensions between Romulo and Julianne, stealing a Bouquet of Roses from one of the new acts for Tinhead's vanity and finding where the understudy stashed Little Red's cape in the Chess room.", progress = "How did it go?", completion = "I can't believe you found what we needed!\n\nUh, not that I doubt you, it's just... well, this is the first time one of my projects has actually worked out.\n\nAnyway, I think delivering these items to the actors will ease tensions for a while.\n\nThis is a momentous day!" }
WordHunterWoW_QuestEN[45295] = { title = "Return to Karazhan: Clearing Out the Cobwebs", description = "I admit it... even as a spirit, I am deathly afraid of spiders. All those legs! Dripping fangs! Sticky webs coming out of their...\n\n<Darius does a squirming sort of shimmy that is uncomfortable to watch.>\n\nI'm sure a world-saving hero like you doesn't mind them, though. Which is good, since a whole brood of spiders has taken over the Servant's Quarters.\n\nYou'll handle this, right? If you don't get them all, they'll keep multiplying.", objectives = "Clean out spiders from the Servant's Quarters.", completion = "You got every single spider, right?\n\nEither way, I'll just check that one off the list. No need to check up on your work.\n\n<Darius makes a squinched-up face.>" }
WordHunterWoW_QuestEN[45296] = { title = "No Bones About It", description = "The Charred Bone Fragments still smolder with ancient power. Darius would be extremely interested in examining them and hearing of your defeat of Nightbane.", objectives = "Take the Charred Bone Fragments to Darius.", completion = "Nightbane has been defeated! I'm in awe!\n\nMany years have passed since the blue dragon Arcanagos was slain by the corrupted Medivh. Archmage Alturus sought out the remains of the fallen dragon in an effort to study the Guardian's power. \n\nIn retrospect, maybe not the best idea. \n\nYour help has been invaluable.\n\nI still have a lot of work ahead to clean up Karazhan, but for now I dare ask no more of you. Thank you again for your assistance, <name>." }
