WordHunterWoW_QuestEN[45301] = { title = "Taking Charge", description = "Mardum has been quiet for months. I wonder why the Legion is attacking us now? Could be in retaliation for destroying their battleship on the Broken Shore...\n\nWe had better head down ourselves and save the day, don't you agree?", objectives = "Talk to Kyra Lightblade and choose to fly down to Mardum.", completion = "Good, you made it." }
